-- Tool FAQ articles: the content behind every /faq/:slug page.
--
-- Generated by scripts/generate-tool-faq-sql.ts from the registries in
-- src/config. Do not edit by hand: change the copy there and run
-- npm run faqs:sql. Public read, admin write, one row per tool.
BEGIN;

CREATE TABLE IF NOT EXISTS public.tool_faq_articles (
  slug TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  route TEXT NOT NULL,
  category TEXT NOT NULL,
  question_count INTEGER NOT NULL DEFAULT 0,
  questions JSONB NOT NULL DEFAULT '[]'::jsonb,
  article JSONB NOT NULL DEFAULT '{}'::jsonb,
  seo JSONB NOT NULL DEFAULT '{}'::jsonb,
  word_count INTEGER NOT NULL DEFAULT 0,
  source TEXT NOT NULL DEFAULT 'registry',
  published BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_tool_faq_articles_category
  ON public.tool_faq_articles(category, published);

COMMENT ON TABLE public.tool_faq_articles IS
  'Questions, long form articles and SEO metadata for each tool FAQ page. Generated from src/config/flavour registries.';

ALTER TABLE public.tool_faq_articles ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Public can read published tool FAQs" ON public.tool_faq_articles;
CREATE POLICY "Public can read published tool FAQs"
  ON public.tool_faq_articles FOR SELECT
  USING (published = true);

DROP POLICY IF EXISTS "Admins can manage tool FAQs" ON public.tool_faq_articles;
CREATE POLICY "Admins can manage tool FAQs"
  ON public.tool_faq_articles FOR ALL
  USING (
    EXISTS (
      SELECT 1 FROM profiles
      WHERE profiles.id = auth.uid()
      AND profiles.role = 'admin'
    )
  );

GRANT SELECT ON public.tool_faq_articles TO anon, authenticated;
GRANT ALL ON public.tool_faq_articles TO service_role;

INSERT INTO public.tool_faq_articles
  (slug, name, route, category, question_count, questions, article, seo, word_count, source)
VALUES
  ('paint-calculator', 'Paint Calculator', '/paint-calculator', 'finishes', 5, $q$[{"q":"How many coats of paint do I need for a room?","a":"Two coats is the normal interior finish, and three when the colour changes sharply or the wall is patching bare plaster. The calculator applies the coats you choose and shows the litres for each one separately, so a single coat refresh is priced as a refresh. On a wall that has been skimmed, a mist coat first is usual practice, and it is priced as its own line because it consumes material without being part of the finish."},{"q":"How do I work out how much paint to buy for a room?","a":"Measure the walls you are painting, deduct the openings you are not painting, then divide by the coverage the product states. The calculator does the measuring arithmetic and the division, then rounds up to the tin sizes sold where you are working. Two things decide the answer more than the area does: the product's coverage, which differs widely between a premium emulsion and a contractor grade one, and whether you are changing colour, which costs an extra coat."},{"q":"Does the paint estimate include primer and undercoat?","a":"Yes, and on their own lines, with their own coverage and their own quantities. A primer or undercoat is a different product from a topcoat, consumed at a different rate, and pricing it as extra topcoat litres produces an order that is short on one and long on the other. If you are painting over a sound, previously painted wall, leave them out of the estimate and the total drops accordingly."},{"q":"What is not included in a paint estimate?","a":"Labour, masking, sanding, filling, caulking and any surface repair are outside this estimate, as are scaffolding and protection of floors and furniture. The estimate covers paint and primer quantities and their cost from the product records, which is the part you need before you go to the paint shop. It also leaves out any specialist product a substrate demands, because that is a specification decision rather than a quantity calculation."},{"q":"Does the calculator work in square feet?","a":"Switch the unit and the area, coverage and tin sizes all convert together, so a building measured in feet and a specification written in litres still produce one order. The conversion happens on the factors rather than on the final figure, so a square metre never becomes a scaled length. Enter coverage in the unit you are working in and the division stays in one system, which is what prevents the doubling errors that come from converting twice."}]$q$, $a${"summary":"Turns room measurements into the paint a repaint actually consumes, coat by coat.","description":"A paint estimate answers one question with a number: how many tins do I buy? Everything else on the page exists to make that answer trustworthy. Wall and ceiling areas are measured separately because they take different products, openings are deducted because nobody paints a window, and the number of coats is yours to set because a refresh and a colour change are not the same job.\n\nThe arithmetic is deliberately plain. Area to be painted, divided by the coverage the product states, multiplied by the number of coats, rounded up to the tin sizes your market sells. What makes the result usable is not the division but the discipline around it: coverage comes from the product record instead of an assumed spread rate, primer is priced as its own product with its own consumption, and waste is a stated percentage rather than a silent margin added to the litres.","functions":["Adds up the wall areas you enter, room by room, and keeps ceilings on their own line because they usually take a different product.","Deducts every door, window and opening you list, by width and height, so the measured area matches what a brush actually covers.","Divides the area by the coverage stated for the product you select, then multiplies by the coats you choose, showing the litres for each coat separately.","Adds primer and undercoat as their own products with their own coverage, so a bare plaster job and a repaint are priced differently.","Rounds the litres up to the tin sizes sold in the market you select, because paint is bought by the container and a part tin is a purchase.","Carries the waste percentage you set as a visible line, so the allowance for cutting in, roller loss and touch ups is stated rather than hidden."],"worked":"Take a room four metres by three, with a ceiling height of two and a half metres, one door two metres wide by one high and one window one and a half metres wide by one high. The wall perimeter is fourteen metres, so the gross wall area is thirty five square metres. The door takes two square metres and the window one and a half, leaving thirty one and a half square metres of wall. The ceiling adds twelve square metres, and it is priced as its own surface. Painting the walls only, in two coats, with a product specifying twelve square metres per litre, needs two and seven tenths litres per coat, so five and four tenths litres in total, which rounds to two five litre tins. Change the product to one specifying ten square metres per litre and the same room needs six and a third litres, which is still two tins of five, but three if your market sells four litre tins. That is the whole point of the tool: the same room, a different product, a different order.","advantages":["The litres per coat are visible, so a one coat refresh is not quoted at the price of a full repaint.","Coverage comes from the product data, which means a cheaper tin with thin coverage cannot look like a saving.","Openings are deducted rather than estimated around, which is where a hand calculation usually over orders.","Tin sizes follow the market, so the answer is an order a merchant can fill.","Primer stays on its own line, which prevents the common habit of pricing a bare wall as a painted one."],"limits":["It measures materials, not labour, masking, sanding or filling.","It does not judge whether the substrate needs sealing, stabilising or a specialist primer.","It does not assess colour coverage, which is a product property rather than a quantity.","Exterior surfaces, metal and masonry take different products and different coverage, which you supply per job.","It does not include scaffolding, access equipment or protection."]}$a$, $s${"title":"Paint calculator: how much paint and primer","description":"Turns room measurements into the paint a repaint actually consumes, coat by coat. A paint estimate answers one question with a number: how many tins do I buy?","keywords":"paint calculator, paint calculator: how much paint and primer, finishing materials, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 1071, 'longform'),
  ('tile-calculator', 'Tile Calculator', '/tile-calculator', 'finishes', 5, $q$[{"q":"How many tiles do I need for a floor or wall?","a":"Measure the floor or wall, then divide by the area of one tile, allowing for the joint if you want a close figure. The calculator does the division from the tile dimensions in millimetres or inches, so the count is in whole tiles and then converted to boxes. For a wall, measure each elevation separately and deduct the openings, because a room perimeter multiplied by height includes the door and window areas you are not tiling."},{"q":"Why does the tile calculator add a waste allowance?","a":"Because a tiled surface is not a rectangle. Edges need cuts, and cuts produce offcuts that cannot be used elsewhere. Tiles break in transit and on site, and a spare box left in the garage is what saves a matching problem when one cracks two years later. A straight lay in a large format needs around ten percent, a diagonal or herringbone layout needs fifteen or more, and the allowance is a percentage you set so it is visible in the total."},{"q":"How much tile adhesive and grout will I need?","a":"Adhesive follows the bed thickness and the coverage the product states, and grout follows the joint width, tile size and depth. The calculator asks for the coverage you are working to and multiplies it across the area, then converts to the bag size sold in your market. Grout is the one people underestimate: a small format tile with wide joints can consume several times the grout of a large format in the same area, so the calculator uses the geometry instead of a rate per square metre."},{"q":"Should I buy exactly the tiles the calculator shows?","a":"No. Buy the boxes the calculator shows, and keep the spare box. Tile production runs change shade, and a repair two years later needs a match that a new batch may not give. The boxes figure already includes the waste you set, so buying the raw area and hoping the cuts work out is how a job ends up one box short on a Friday afternoon."},{"q":"How do I allow for cuts, breakages and spares?","a":"Cuts at edges, breakages in transit and a spare for future repair are all waste, and waste is a percentage you control. Ten percent suits a straight lay, fifteen or more for a diagonal or herringbone, and more again for a room with many corners. It appears as its own line, so when a client asks why the order is larger than the floor area, the answer is a number on the page."}]$q$, $a${"summary":"Converts a measured area into the tiles and packs you have to buy, with the waste you choose.","description":"A tiling estimate has three quantities that fail independently: tiles, adhesive and grout. Tiles fail when the waste allowance is too thin for the pattern, adhesive fails when the bed thickness is assumed rather than chosen, and grout fails when the joint width and tile size are not both known. The calculator holds all three together so a job is not ordered in three separate trips to the merchant.\n\nThe mechanics are simple and unforgiving. Floor or wall area divided by the area of one tile gives the count, the layout pattern decides how much of that count is lost to cuts, and the tile size with the joint width decides how many square metres a bag of adhesive and a kilogramme of grout will serve. Because those relationships change with the pattern and the format, both stay as inputs you set, and the tool shows the square metres each bag covers rather than assuming one.","functions":["Calculates tile count from the surface area and the tile dimensions you enter, in millimetres or inches.","Applies the waste percentage you set, which covers edge cuts, breakages in transit and a spare box for later repair.","Reports boxes to buy from the coverage per box sold in your market, because tiles are ordered by the box.","Calculates adhesive from the bed thickness and the coverage stated for the product, with the notched trowel size reflected in the coverage you supply.","Calculates grout from the joint width, tile size and joint depth, which is the relationship that makes small tiles consume far more grout than large ones.","Keeps floor and wall areas separate, since the two take different adhesives and often different tiles."],"worked":"A bathroom floor is two and a half metres by two metres, so five square metres. With tiles of three hundred by three hundred millimetres, each tile covers nine hundredths of a square metre, which gives fifty six tiles before waste. Ten percent waste takes that to sixty two, and if the boxes hold eleven tiles you buy six boxes. The walls add eighteen square metres, and at three hundred by six hundred millimetres each tile covers eighteen hundredths of a square metre, so a hundred tiles, a hundred and ten with waste. Adhesive at four kilogrammes per square metre for a ten millimetre bed needs twenty kilogrammes for the floor and seventy two for the walls, so a twenty kilogramme bag and four more, not the single bag that a room count would suggest. Grout for a three millimetre joint on the floor needs roughly half a kilogramme per square metre, so two and a half kilogrammes, and the smaller wall tiles need more per square metre because the joints are denser.","advantages":["Tiles, adhesive and grout come out of one calculation, which matches how they are bought.","Waste is a stated percentage, so a diagonal layout can be given the allowance it needs.","Box coverage follows the market, so the order is a number you can place.","Grout follows the joint width and tile size, which is where hand estimates fall furthest short on small formats.","Floor and wall surfaces stay apart, which prevents a wall adhesive being counted at floor rates."],"limits":["It does not assess the substrate, which decides whether a backer board or a levelling compound is needed.","It does not include trims, spacers, waterproofing or movement joints.","It does not account for pattern specific cutting beyond the waste allowance you set.","It does not price labour, removal of existing coverings or waste disposal.","It does not guarantee a shade match between boxes, which is a supplier question."]}$a$, $s${"title":"Tile calculator: how many tiles and boxes","description":"A tiling estimate has three quantities that fail independently: tiles, adhesive and grout.","keywords":"tile calculator, tile calculator: how many tiles and boxes, finishing materials, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 1049, 'longform'),
  ('pop-ceiling-calculator', 'POP Ceiling Calculator', '/pop-ceiling-calculator', 'finishes', 5, $q$[{"q":"How do I calculate how much POP I need for a ceiling?","a":"Multiply each room's length by its width for the area, then add the perimeter for the framing, and it is the second figure that a quick estimate usually forgets. The calculator takes the dimensions room by room, converts the total area into boards at the size you specify, and converts the total perimeter into screed, channel and trim. Compound then follows the joints the chosen board size creates, so a smaller board raises both the board count and the compound."},{"q":"Does the POP calculator account for the ceiling design?","a":"It uses the dimensions of the design you are building, so a simple flat ceiling is priced accurately and a design with steps, coves or curves needs those features measured as extra runs. Measurement is yours to take, and the arithmetic on top of it is the calculator's. That division matters on a decorated ceiling, because the design detail is geometry rather than something a rate per square metre can carry."},{"q":"Are labour and scaffolding included in a POP ceiling estimate?","a":"They are not included. The estimate covers board, framing, compound, tape and trim, which is what you need to order before the work starts. Labour follows the design and the access, and scaffold depends on the ceiling height and what is underneath. Both are priced separately, and putting them into a material estimate produces a number that is accurate for neither."},{"q":"Can I estimate a POP ceiling by room count instead of area?","a":"Not reliably. Two rooms of the same count can differ by several square metres and by more in perimeter, which is what drives the framing. Entering each room's length and width takes a minute and gives an area and a perimeter the estimate can actually use. A room count is a budgeting shorthand, and the calculator is designed to replace it with the measurement the order depends on."},{"q":"How is the perimeter used in a POP estimate?","a":"Screed, channel and trim follow the perimeter of each room, so a long narrow room needs more of all three than a square room of the same area. The calculator takes the perimeter from the dimensions you enter and prices the framing against it. This is why an estimate built from area alone under orders on circulation spaces, corridors and long living rooms, and why the perimeter appears as its own line."}]$q$, $a${"summary":"Sizes a plaster of Paris ceiling from the area you are covering and the thickness you build.","description":"A POP ceiling is priced by three things that are easy to confuse: the board area that covers the room, the framing that holds it, and the compound that joints and finishes it. A room count gets none of them right, and an area alone misses the framing entirely, which is where a ceiling budget usually goes wrong. The calculator takes each room's length and width, builds the area and the perimeter from them, and carries both into the quantities.\n\nCeilings are not floors. The area decides board and compound, the perimeter decides screed, channel and trim, and the height of the room decides nothing at all except the scaffold you will need. Because a long narrow room and a square room can share an area and differ by several metres of perimeter, the tool keeps the two measurements apart and prices each against its own rule.","functions":["Builds ceiling area from each room's length and width, room by room, so an irregular plan is measured as the rooms it contains.","Calculates the perimeter of each room, which drives screed, channel and edge trim, and is what an area figure cannot give you.","Converts area into boards at the board size and coverage you specify, rounded up to whole boards.","Calculates jointing compound and tape from the board area and the joint density implied by the board size.","Keeps framing members separate from the suspended grid, since a direct fixed ceiling and a suspended one use different quantities.","Applies your waste percentage as a stated line rather than a hidden loading on the board price."],"worked":"A living room six metres by four and a half gives twenty seven square metres and a perimeter of twenty one metres. A second room three metres by nine gives the same twenty seven square metres but a perimeter of twenty four metres. Board quantities are identical, and the framing differs by three metres of screed and trim, which is the difference the room count would have hidden. At a board size of one and a half by one and a bit metres covering close to two square metres per board, the first room needs fourteen boards before waste. Compound follows the joints those boards create, and trim follows the twenty one metres, not the area.","advantages":["Perimeter is calculated, so framing and trim are not priced off an area figure that cannot produce them.","Each room is measured on its own dimensions, which handles an irregular plan without a separate drawing exercise.","Boards are rounded to whole units, so the order matches what a supplier delivers.","Compound and tape follow the board size, because a smaller board means more joints and more compound.","Waste is visible, so a design with many curves or recesses can be given the allowance it needs."],"limits":["It does not design the ceiling, so a curved or stepped design needs the quantities measured from your layout.","It does not cover lighting coves, cornices or decorative features beyond the trim you allow.","It does not include scaffold, access equipment or fixing to the structure above.","It does not assess the substrate, joist spacing or the fixings required for the board weight.","It does not include painting of the finished ceiling, which is measured separately."]}$a$, $s${"title":"POP ceiling calculator: cost and materials","description":"A POP ceiling is priced by three things that are easy to confuse: the board area that covers the room, the framing that holds it, and the compound that","keywords":"pop ceiling calculator, pop ceiling calculator: cost and materials, finishing materials, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 962, 'longform'),
  ('wallpaper-calculator', 'Wallpaper Calculator', '/wallpaper-calculator', 'interiors', 7, $q$[{"q":"How does the wallpaper calculator estimate the number of rolls?","a":"It estimates full height drops for each measured wall, then calculates the cut length of each drop from the wall height, trim allowance and pattern repeat. The cuts are packed into the usable roll length, and the result is rounded to whole stock units and priced packages. The displayed net area is a separate summary; it does not decide whether a particular offcut can replace a drop."},{"q":"Can I estimate wide rolls, US single or double rolls, and mural panels?","a":"Yes. A preset can start the estimate, or you can enter the usable dimensions printed on the product. For a priced package, enter how many physical rolls or mural panels it contains. Package names differ between suppliers and markets, so the package dimensions and count should come from the label you are buying, not from a regional assumption."},{"q":"Can I estimate paper, vinyl, non-woven, textile, peel-and-stick and patterned wallpaper?","a":"The material selection identifies the product type, while the calculation uses its dimensions and the pattern details you provide. It does not add a coverage multiplier because a product is described as vinyl, textile or non-woven. The label does not establish the paste, preparation or hanging method, so follow the product maker's instructions."},{"q":"How do free match, straight match and half-drop affect the estimate?","a":"Free match does not add a repeat offset. Straight match rounds the cut to the repeat you enter. Half drop alternates a half repeat offset on alternate cuts. The estimator represents these rules in a simplified cut length calculation, and it is not a complete layout that checks every strip against the roll and pattern sequence."},{"q":"Do doors and windows reduce the number of wallpaper rolls?","a":"The measured door and window areas reduce the net area display. The roll takeoff still plans full height drops across the wall because the openings' positions and surrounding geometry determine whether offcuts can be reused. Check the layout with the installer before ordering if you want to rely on offcut recovery."},{"q":"Does the calculator show live wallpaper prices or labor rates?","a":"No. Material and installation costs use the amounts you type in the selected currency. They are manual quotes for planning and are not verified or live supplier data. Changing the market does not convert an entered price into a different currency, so update the inputs using a local supplier quote."},{"q":"How much wallpaper paste should I buy?","a":"Paste packs are estimated only when paste is required and use the coverage per pack that you enter. Self adhesive and peel and stick selections do not add separate paste packs. Product instructions determine the suitable adhesive and its coverage, so verify those details for the chosen product and wall surface."}]$q$, $a${"summary":"Plans wallpaper rolls or mural panels from measured walls, product dimensions, pattern repeat and your own budget inputs.","description":"A wallpaper order begins with a measured wall, but the quantity depends on more than its area. The product has a usable width and length, each drop has to reach the wall height, and a repeated design may require extra length so adjoining drops meet. A quantity based only on square metres misses those constraints.\n\nThe calculator treats a roll as a set of cuts. It works out the full height drops needed across each wall, applies the waste allowance you choose, adjusts cut length for the trim and pattern repeat, then packs those cuts against the usable length of a roll. It rounds up to whole rolls or whole priced packages. Fixed mural panels use their printed dimensions and are counted as panels instead of continuous drops.\n\nOpenings are deducted from the displayed net wall area, but they do not automatically reduce the full height drop count. Their location and the shape of reusable offcuts affect whether material can be recovered, and the calculator does not have a cutting layout that can prove that recovery. This conservative distinction keeps the area summary from implying an order quantity that the layout cannot support.","functions":["Measures each wall from its entered width and height and subtracts the door and window areas from the net area display.","Counts full height drops from wall width divided by usable product width, rounded up for each wall.","Applies the selected allowance to the drop count, then determines cut length from wall height, trim and match repeat.","Packs the required cuts within each usable roll length and reports stock units and whole priced packages.","Counts mural panels from panel dimensions and the number of panels in a priced set, without treating them as roll goods.","Calculates material, paste and installation costs only from the prices and coverage inputs the user provides."],"worked":"Suppose a room has two measured walls with different widths and heights, and the chosen product has a stated usable width and roll length. The calculator counts drops on each wall separately, adds the chosen allowance, and calculates a cut for each drop. If the design has a repeat, the cut length rounds up to a matching repeat so the pattern can align. It then tests how many of those cuts fit into each roll and rounds the stock order to the package size entered. If a door is added, the net area decreases, but the full height drop count remains, because a drawing of the opening position and offcut reuse is needed to show that a complete drop can be recovered. A mural selection follows a different path: it counts fixed panels and priced sets. The resulting estimate can be checked against the product label and installer layout before an order is placed.","advantages":["Roll geometry, wall geometry and cost are separate, which makes each assumption easier to verify.","Pattern repeat changes the cut length only when the product match requires it.","The opening deduction is shown without claiming that every offcut can replace a full width drop.","Rolls, priced packages and fixed mural panels have distinct counting rules.","Manual supplier and labour quotes remain local user inputs and are not presented as live prices."],"limits":["The calculator does not generate a room elevation or a precise cutting schedule for each roll.","It cannot determine which offcuts are reusable without the opening positions and a complete layout.","It does not validate a product label, batch number, substrate, paste choice or installation method.","Pattern direction and matching instructions must be checked on the selected product.","Prices, tax and fitting rates are not verified by this calculator; confirm them with the supplier and installer."]}$a$, $s${"title":"Wallpaper Calculator","description":"A wallpaper order begins with a measured wall, but the quantity depends on more than its area.","keywords":"wallpaper calculator, wallpaper calculator, interior decor and window treatments, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 1081, 'longform'),
  ('screeding-calculator', 'Screeding Calculator', '/screeding-calculator', 'finishes', 5, $q$[{"q":"How much sand and cement do I need for a floor screed?","a":"Multiply the floor area by the thickness to get a volume, then split that volume by the mix ratio into sand and cement. The calculator does both steps and expresses cement in the bag size sold in your market, with sand by volume or by tonne. Two things move the answer more than the area does: the thickness, which multiplies everything, and the mix, because a one to three screed uses noticeably more cement than a one to five for the same volume."},{"q":"How thick should a floor screed be?","a":"Between forty and seventy five millimetres is common for a levelling screed over a prepared base, with thinner sections used for a wearing surface over a sound floor. Below about forty millimetres the risk of curling and debonding rises, and above seventy five the material cost climbs quickly. Those are specification judgements, so the calculator asks for your thickness and shows what it consumes rather than choosing one for you."},{"q":"Does a screeding estimate include the floor finish?","a":"No. Tile, stone, screed paint and any levelling compound above the screed are separate products with their own quantities and their own trades. The estimate covers the screed itself, which is what you order before the floor finish is even selected. Keeping them apart matters on a quotation, because a client changing the tile should not change the screed quantity, and mixing them makes that comparison impossible."},{"q":"What thickness should I enter for screeding?","a":"Enter the depth the specification calls for, in millimetres. If the base is uneven, the average depth is what governs the order, so measure the high and low points and use a figure that reflects the average rather than the minimum. The calculator shows the volume implied, which is the quickest way to sanity check whether the depth on a drawing meets the floor level you are trying to achieve."},{"q":"Does screeding cover a floor or a wall?","a":"Both, as separate surfaces, because they are measured and bought differently. A floor screed is a volume of sand and cement placed to a depth; a wall render is an area at a stated thickness, often with a different mix and a different finish. The calculator keeps the two apart so a wall is not ordered by the cubic metre and a floor is not priced from a render rate per square metre."}]$q$, $a${"summary":"Turns a floor area and a screed thickness into sand, cement and the bags behind them.","description":"A screed estimate is a volume calculation wearing an area costume. The floor area is what you measure, but the order is sand and cement, and those follow the depth. That is why thickness is the first input the tool asks for and why a change from forty to seventy millimetres changes the material by three quarters on the same floor.\n\nThe other half of the job is where the screed sits. A floor screed is ordered by volume, a wall render by area at a stated thickness, and a wearing surface over a sound base is thinner than a levelling screed over an uneven one. Keeping those cases apart is what stops a floor being priced at a render rate and a wall being ordered by the cubic metre.","functions":["Calculates screed volume from the floor area and the thickness you enter.","Converts volume into sand and cement from the mix ratio you specify, with cement in the bag size sold in your market.","Measures wall render separately, by area at the thickness you state, so the two do not share a rate.","Applies your waste percentage as a stated line rather than a loading on the sand price.","Keeps the floor finish, such as tile or paint, out of the screed quantity, since it is a separate product and a separate order.","Reports a blank thickness as missing, because the volume cannot be calculated without it."],"worked":"A floor of sixty square metres at fifty millimetres needs three cubic metres of screed. At a one to four mix by volume, that is six tenths of a cubic metre of cement and two and four tenths of sand, which in bags of fifty kilogrammes is roughly nine hundred kilogrammes of cement, or eighteen bags, and about four tonnes of sand once its density is applied. Take the same floor to seventy five millimetres and the volume rises to four and a half cubic metres, the cement to twenty seven bags, and the sand to six tonnes. Same floor, same mix, no change in the drawing's intent, and a third more material, which is why thickness cannot sit inside a trade rate.","advantages":["Thickness is an input, so a deeper screed shows up as the material it consumes.","Sand and cement are ordered in the units they are sold in, bags and tonnes, not as a bare volume.","Floor screed and wall render stay separate, which keeps their rates from being blended.","Waste is visible, so a rough base can be given the allowance it needs.","The floor finish is excluded, so the screed quantity is not inflated by the tile that sits on it."],"limits":["It does not assess the substrate, which decides whether a levelling screed is needed and how deep.","It does not design the mix, and it does not specify admixtures or reinforcement mesh.","It does not include curing compounds, edge insulation or movement joints.","It does not price labour, pumping, preparation or removal of the old floor.","It does not include the finished floor covering."]}$a$, $s${"title":"Screeding Calculator","description":"Turns a floor area and a screed thickness into sand, cement and the bags behind them. A screed estimate is a volume calculation wearing an area costume.","keywords":"screeding calculator, screeding calculator, finishing materials, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 927, 'longform'),
  ('foundation-calculator', 'Foundation Calculator', '/foundation', 'structure', 5, $q$[{"q":"How much concrete do I need for a foundation?","a":"Multiply each footing run's length, width and depth, add the runs, then add the waste allowance you work to. The calculator does that from the dimensions you enter and shows the total before waste as well as after, so a checking engineer can see both. Cement, sand and coarse aggregate then follow from the mix you specify, expressed in the bag size and the units your market sells, so the order is something a supplier can price."},{"q":"How many blocks do I need for the foundation?","a":"Take the wall length, multiply by the height, divide by the face area of the block you are using, then deduct the openings and add waste. The calculator works from the block size you specify, which matters because a four hundred and fifty by two hundred and twenty five millimetre block and a four hundred and forty by two hundred and fifteen millimetre block do not cover the same area. Mortar follows the joint thickness and the wall area, so a thinner joint reduces both the mortar and the cement in it."},{"q":"Is this foundation design?","a":"No, and it says so on the page. Footing width, depth and reinforcement are structural design decisions that follow from the load and the ground, and a quantity tool cannot make them. When those dimensions come from your engineer, this tool converts them into a material order. When they do not exist yet, the useful next step is a soil report and a design, not a guessed footing width."},{"q":"Does the foundation estimate include formwork?","a":"No. Formwork, hardcore, blinding, damp proofing and excavation are separate items with their own quantities, and they are usually priced by a different trade. The estimate covers the concrete and the blockwork, which are the two materials you need to order before the first pour. Adding formwork to a concrete quantity produces a figure that reads as complete while leaving several real costs out of it."},{"q":"Does the foundation cost include tax?","a":"No. Tax is not determined in this estimate. Where a configured tax rule applies to your market, it appears as its own line with the basis stated; where no rule applies, the total is shown without tax rather than with an assumed percentage. That matters when you are comparing quotes from different regions, because a figure with an invented tax rate cannot be compared with one without it."}]$q$, $a${"summary":"The materials a footing consumes: concrete ingredients, blockwork and formwork, from your own dimensions.","description":"A foundation estimate comes down to three quantities and one warning. The concrete in the footing, the blocks in the wall above it, and the mortar that holds them, plus a clear statement that none of it is a design. Everything the tool does follows from the dimensions you supply, and nothing is inferred from a building type, a plot size or a habit.\n\nThe warning matters as much as the arithmetic. Footing width, depth and reinforcement follow from the load and the ground, which are engineering questions answered by a soil report and a structural design. Once those dimensions exist, the material quantity is simple multiplication, and that is the part this tool owns. When the dimensions do not exist yet, the honest output is a request for them.","functions":["Calculates footing concrete from the length, width and depth of each footing run you enter, with a waste allowance as its own line.","Calculates blockwork from the wall length, height and block size, deducting the openings you list.","Calculates mortar volume from the joint thickness, block size and the wall area the blocks fill.","Expresses cement in the bag size sold in the market you select, with sand by volume, from the mix you specify.","Keeps the strip footing, the column bases and the blockwork on separate lines, so each can be checked against the drawing independently.","Reports a dimension left blank as missing instead of substituting a typical value."],"worked":"A strip footing one hundred and twenty metres in total run, six hundred millimetres wide and two hundred deep, needs fourteen and four tenths cubic metres of concrete. Add five percent waste and that becomes fifteen cubic metres, which in a one to two to four mix is roughly four and a third cubic metres of cement, eight and two thirds of sand and seventeen and a third of coarse aggregate, expressed in the bag size your market sells. A block wall of one hundred and twenty metres at nine hundred millimetres high is a hundred and eight square metres, and with a block of four hundred and fifty by two hundred and twenty five millimetres each covers just over a tenth of a square metre, so about a thousand and seventy blocks before openings and waste. The two numbers are separate purchases and separate deliveries, which is why they are separate lines.","advantages":["Footing concrete and blockwork are measured independently, so each can be checked against its own drawing detail.","Cement follows the bag size sold where you are building, which keeps the order usable across markets.","Openings are deducted with their dimensions, which is where a wall estimate usually over orders.","A blank dimension is reported as missing, so an incomplete drawing is visible before material is ordered.","The tool states plainly that it does not design, which keeps the engineering question with the engineer."],"limits":["It does not size footings, columns or reinforcement, and it will not infer them from a building description.","It does not assess ground conditions, bearing capacity or water.","It does not include formwork, hardcore, blinding, damp proofing or excavation.","It does not include the setting out or the labour to place the concrete.","Tax is not determined here, and it appears only where a configured rule applies to your market."]}$a$, $s${"title":"Foundation Calculator","description":"The materials a footing consumes: concrete ingredients, blockwork and formwork, from your own dimensions. A foundation estimate comes down to three","keywords":"foundation calculator, foundation calculator, structural materials, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 966, 'longform'),
  ('build-to-roof-estimator', 'Build to Roof Estimator', '/build-to-roof-estimator', 'structure', 5, $q$[{"q":"What is a build-to-roof estimator?","a":"A build to roof estimator prices the stages from the footings up to the roof covering: footing concrete, blockwork and mortar, roof members, sheeting and the eaves trim. It is a stage estimate, not a whole house estimate, and that boundary is the point. Builders use it to answer the question that comes before every other one, which is whether there is enough money to get the building closed and dry."},{"q":"How are roofing sheets calculated from a roof area?","a":"From the roof area, adjusted for pitch, then divided by the cover width of the sheet you are using and rounded up for the length of each run. Laps are part of the calculation, because a sheet that overhangs the eaves or laps the next one covers less than its nominal width. Enter the cover width the manufacturer states and the sheet length you will order, and the count comes back in whole sheets rather than square metres."},{"q":"Where does the eaves perimeter come from?","a":"From the plan dimensions of the building, since the eaves perimeter follows the wall line plus whatever overhang you set. It is not the same as the roof perimeter at the pitch, and it is not the wall perimeter at floor level, because both differ once there is an overhang. Fascia, gutter and soffit are all ordered from this figure, which is why a roof area alone cannot produce them."},{"q":"Where does the build to roof estimate stop?","a":"It stops at the roof covering. Windows, doors, finishes, plumbing, electrical, ceilings and external works are outside it, as are scaffolding, plant and labour. The stage boundary is deliberate: a number that runs into finishes has to make assumptions about specification, and those assumptions are where an estimate stops being checkable. The next stage is priced with its own tools on the same building dimensions."},{"q":"Why does the cement bag count change when I change the mix ratio?","a":"Because cement content is a property of the mix, not of the concrete volume. A one to two to four mix and a one to one and a half to three mix produce visibly different cement quantities from the same cubic metres, while sand and aggregate move in the other direction. Change the mix on the page and the bag count moves with it, which is what lets you compare a specification change against its material cost before you commit to it."}]$q$, $a${"summary":"One pass from substructure to roof covering, so the shell is priced as a single job.","description":"Building to roof is the stage where money runs out quietly. The frame is up, the roof is not covered, and the gap between the two is where a self build stalls. This estimator prices the work up to and including the roof covering, so the number on the page is what it takes to get a building closed and dry.\n\nIt works in the order the work happens. Footings, then blockwork with its openings deducted, then the roof structure, then the sheeting. Each stage produces its own materials, and each takes its quantities from dimensions you supply rather than from a rate per square metre of floor. What it deliberately does not do is carry on into finishes, services or joinery, because a stage estimate that runs past its stage is a number nobody can act on.","functions":["Calculates footing concrete and blockwork from the building's dimensions, with openings deducted and mortar calculated from the joint thickness.","Calculates roof members from the span and the spacing you set, with purlins and ridges counted as runs rather than guessed.","Converts roof area into sheeting at the cover width and sheet length you specify, including the end laps, so the order is in sheets.","Derives the eaves perimeter from the plan you enter, which is what fascia, gutter and soffit are ordered from.","Converts concrete into cement, sand and aggregate from the mix you choose, expressed in the bag size sold in your market.","Stops at the roof covering, leaving every stage beyond it out of the total."],"worked":"A single storey building ten metres by eight produces a hundred and ninety six metres of wall at a two point six metre height once the eaves overhang is included, less the openings you list. Blockwork for that wall, at a block covering just over a tenth of a square metre, comes to about a thousand eight hundred blocks. A pitched roof over the same plan at a thirty degree pitch gives a roof area of about a hundred and five square metres, which at a cover width of a metre and a sheet length of three metres is around forty sheets counting laps. The eaves perimeter, ten plus eight doubled, is thirty six metres, which is the fascia and gutter order. Four numbers, four deliveries, and none of them derived from the others.","advantages":["The total is a stage total, so it answers the question a self builder actually asks before starting.","Sheets are ordered by cover width and length, which is how a roofing supplier sells them.","Eaves perimeter is calculated separately, so gutter and fascia are not under ordered from a roof area.","Openings are deducted, which is where a wall estimate usually runs long.","Mix ratios change the cement count visibly, so a leaner mix shows its saving."],"limits":["It stops at the roof covering and does not include windows, doors, finishes, services or external works.","It does not design the structure, the roof pitch or the member sizes.","It does not include scaffolding, plant hire or labour.","It does not include gutters beyond the linear measurement, or rainwater disposal.","It does not determine tax, which appears only where a configured rule applies to your market."]}$a$, $s${"title":"Build to roof: cost from foundation up","description":"One pass from substructure to roof covering, so the shell is priced as a single job. Building to roof is the stage where money runs out quietly.","keywords":"build to roof estimator, build to roof: cost from foundation up, structural materials, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 958, 'longform'),
  ('retaining-wall-calculator', 'Retaining Wall Calculator', '/retaining-wall-calculator', 'structure', 5, $q$[{"q":"How wide should a retaining wall footing be?","a":"The page derives it from the wall height and the soil type, and shows both the width and the rule it came from. As a rule of thumb a footing runs between half and two thirds of the retained height, wider for weaker soils, and that is where the derived figure lands. It is a starting point for a material order, not a design. Where an engineer has specified a width, enter it and the quantities follow your figure, not the rule."},{"q":"How many weep holes does a retaining wall need?","a":"At roughly two metre centres along the retained face, with a fall to the outside, a gravel collar behind each one and a filter fabric to stop the wall silting up. The calculator counts them from the wall length and adds the pipe and the collar. Weep holes are the cheapest part of the wall and the most expensive to leave out, because a wall that cannot drain holds water and then fails, so the count is worth checking against the drawing."},{"q":"Can I use this instead of an engineer for a retaining wall?","a":"No. A retaining wall is a structure that fails suddenly when it fails, and the design depends on the soil, the water, the surcharge above it and the wall's own mass. The calculator measures the materials for a wall whose dimensions have been decided, and it flags the footing rule so the decision can be checked. Use it to order concrete and blocks, and use an engineer to decide how deep, how wide and how reinforced."},{"q":"What does the soil type change?","a":"It changes the footing width the page derives, and therefore the concrete and the excavation. Clay holds a steeper face than sand, and loose granular soil needs a wider base for the same height. The switch is deliberately visible rather than buried, because a wall specified for one soil and built in another is a wall whose footing is the wrong size for the ground it is actually in."},{"q":"What happens if I do not know the soil type?","a":"It stops and asks. An unknown soil type is reported as a missing input, because a default would produce a footing width with nothing behind it and a material order that looks finished. The useful next step is a trial pit or a soil report, and until that exists the honest output is a list of what is still unknown rather than a number that would be repeated in a quotation."}]$q$, $a${"summary":"The buried footing and the stem, with soil type changing the geometry, not the opinion.","description":"A retaining wall holds back soil, and the forces on it come from the ground rather than from the wall. That is why this calculator asks for the soil type before it will size a footing, and why it shows the width it derived and lets you overrule it. The material quantities are the easy part. The assumption behind them is the part worth reading.\n\nThe tool measures a wall as a wall: footing concrete, the stem in blocks or concrete, weep holes and the drainage behind it. Footing width follows a rule tied to the wall height and the soil, which is a starting point rather than a design. Where the soil is unknown, the honest answer is to say so, and the page does that instead of picking a value that would look confident and be wrong.","functions":["Calculates footing concrete from the width, depth and length of the footing run, with the width derived from the wall height and soil type.","Calculates the stem in blocks or concrete from the wall height and length, with the face area converted at the unit size you choose.","Sets weep holes at a spacing along the wall and counts them, with the pipe and the filter material they need.","Calculates the drainage layer behind the wall from the wall area and the thickness you specify.","Shows the footing width it derived and the rule behind it, so the assumption can be checked and overridden.","Reports an unknown soil type as a missing input instead of substituting a default."],"worked":"A wall twelve metres long and one point eight metres high, retaining ordinary clay, derives a footing of about nine hundred millimetres wide by two hundred and fifty deep on the rule the page shows. That footing run is twelve metres by zero point nine by zero point two five, which is two point seven cubic metres of concrete, three point two with waste. The stem at one point eight metres by twelve is twenty one and a half square metres of face, which in blocks is about two hundred and ten units plus waste. Weep holes at two metre centres along the retained face give six, each with its pipe and gravel collar. Change the soil to loose sand and the derived footing widens, and the concrete rises with it, before you have changed a single dimension yourself.","advantages":["The footing rule is visible, so the assumption can be argued with instead of trusted.","The derived width can be overridden when an engineer has specified something different.","Weep holes and drainage are counted, which is the part most estimates leave to the site.","Soil type changes the quantity rather than sitting in a note, so its cost is visible.","An unknown soil type blocks the calculation instead of hiding behind a typical value."],"limits":["It does not design the wall, and it does not check sliding, overturning or bearing pressure.","It does not size reinforcement or specify the block strength.","It does not assess groundwater, surcharge loads or slope stability above the wall.","It does not include excavation, backfill compaction or disposal of spoil.","It does not include drainage beyond the wall, such as a carrier drain or a soakaway."]}$a$, $s${"title":"Retaining Wall Calculator","description":"A retaining wall holds back soil, and the forces on it come from the ground rather than from the wall.","keywords":"retaining wall calculator, retaining wall calculator, structural materials, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 976, 'longform'),
  ('soffit-gutter-cost-estimator', 'Soffit, Fascia and Gutter Estimator', '/rainwater-gutter-soffit-cost-estimator', 'structure', 5, $q$[{"q":"How much gutter and fascia do I need for a roof?","a":"Measure the eaves perimeter, which is the wall line plus the overhang on every side, then add the fittings the run needs: corners, stop ends, outlets and joints. The estimator takes the plan dimensions and the overhang, returns the perimeter, and counts the fittings from your geometry. Gutter is not scaled from roof area, because a shallow roof and a steep roof of the same area have the same gutter and very different areas."},{"q":"How many downpipes does a roof need?","a":"From the roof plan area, the perimeter and the spacing you set. Each downpipe serves a length of gutter, so a long run needs more outlets, and the catchments either side are what the pipe has to carry. The estimator places them around the perimeter at the spacing you choose and counts the pipe, the brackets and the shoe for each. Whether that spacing is adequate is a drainage calculation that depends on the rainfall intensity where you are building."},{"q":"How much soffit area does an overhang create?","a":"The overhang depth multiplied by the eaves perimeter. A six hundred millimetre overhang on a forty two metre perimeter is twenty five square metres of soffit board, and the same roof with a three hundred millimetre overhang is half of that. The area is a flat measure of a sloping surface only where the soffit is horizontal, which most are, and where it is raked the depth you enter is the width of the board rather than a vertical drop."},{"q":"Will the fascia length match my roof estimate?","a":"It should, when both are measured from the same plan. The fascia runs around the same eaves line that the roof edge follows, so the numbers agree once the overhang is included in both. Where they disagree, the usual cause is a roof estimate built from the roof surface at the pitch and a fascia measured from the wall line, which differ by the overhang and by the pitch."},{"q":"How is downpipe spacing decided?","a":"By the length of gutter each downpipe serves. A common guide is one outlet per twelve to fifteen metres of gutter on a simple roof, closer on a valley or where two roofs meet, and always at the low end of a fall. The estimator takes your spacing and counts the pipe, but the adequacy of that spacing depends on the rainfall the roof will actually see, which varies enough by region that it is a design input rather than a default."}]$q$, $a${"summary":"The roof to wall band: fascia, gutter run, soffit area and the downpipes that drain it.","description":"Rainwater goods are ordered by the metre and by the fitting, and both come from the roof edge rather than from the roof area. The estimator works from the eaves perimeter, adds the overhang to produce soffit area, puts downpipes where the runs justify them, and returns an order that a merchant can fill.\n\nThe three lines behave differently. Gutter and fascia follow the perimeter directly. Soffit follows the perimeter multiplied by the overhang depth, so a deeper overhang costs more without changing the roof. Downpipes follow the roof plan area and the spacing you set, which is why a long low roof can need fewer than a compact steep one of the same area. Keeping the three apart is what stops one being scaled from another.","functions":["Calculates the eaves perimeter from the plan dimensions and the overhang you set.","Calculates gutter and fascia in metres from that perimeter, with stop ends, corners and outlets counted from the plan.","Calculates soffit area from the perimeter multiplied by the overhang depth.","Places downpipes from the roof plan area and the spacing you specify, counting the pipe, brackets and shoes.","Applies the fall and the outlet positions you describe, so a long run is not priced as a single outlet.","Reports a blank overhang as missing, because soffit area cannot be calculated without it."],"worked":"A roof plan of twelve by nine metres with a six hundred millimetre overhang has an eaves perimeter of forty two metres. Gutter and fascia are forty two metres each, with four corners, two stop ends and, at a spacing of ten metres, five outlets. Soffit is forty two metres multiplied by zero point six, which is twenty five square metres of board. Downpipes at a spacing of eight metres around the perimeter give six, each with its brackets and its shoe. The roof area never entered the gutter order, which is the mistake this page exists to prevent.","advantages":["Gutter, fascia and soffit are calculated from the edge, which is what they are bought from.","Outlets and downpipes are placed by the spacing you set, not by a count per roof.","Soffit follows the overhang depth, so a deeper detail shows up in the order.","Corners, stop ends and shoes are counted, which is where a linear estimate runs short.","A missing overhang is reported instead of assumed."],"limits":["It does not size the gutter or the downpipe, which follows from the rainfall intensity and the roof area.","It does not design the falls or the drainage route beyond the outlet.","It does not include the soakaway, carrier drain or connection to a sewer.","It does not include the roof covering, which is measured by the roofing tool.","It does not include labour, access equipment or replacement of existing goods."]}$a$, $s${"title":"Soffit, Fascia and Gutter Estimator","description":"Rainwater goods are ordered by the metre and by the fitting, and both come from the roof edge rather than from the roof area.","keywords":"soffit, fascia and gutter estimator, soffit, fascia and gutter estimator, structural materials, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 901, 'longform'),
  ('electrical', 'Electrical Estimator', '/electrical', 'services', 5, $q$[{"q":"How do I estimate electrical materials for a building?","a":"Count the points and measure the routes. The estimate takes your schedule of sockets, switches, light positions and outlets, multiplies each by the run you measured, and returns cable by size, conduit, boxes, plates and the board. Two inputs drive everything: the number of points, which sets the accessories, and the average or measured route, which sets the cable. A layout that is not yet marked up cannot produce a cable figure, and the tool says so."},{"q":"Can I use the electrical estimate instead of an electrician?","a":"No, and the page says so. Cable size follows current, protection and volt drop; circuits follow the load and the wiring regulations where you are building; testing and certification follow the installation. The estimate measures materials for a design someone else has made. What it gives you is an order you can price before work starts, which is a different document from a certificate."},{"q":"Why is the cable quantity different from what my electrician measured?","a":"Usually because the route differs. An electrician measuring on site follows the actual path through joists, around obstructions and down the wall, and often adds a margin by habit. The estimate uses the length you enter, so if your average run is a straight line between board and point, it will be short. Enter the length you would actually pull, including the drop at each end, and the two numbers converge."},{"q":"How do I count points for a wiring estimate?","a":"Count what you are installing, not what a schedule of rates assumes for a room. Each socket, switch, light position and fixed outlet is a point with its own run, and the count converts into cable, conduit, boxes and plates. Two rooms with the same floor area can differ by ten points, which is the difference the estimate is built to carry. Counting from the drawing also makes the estimate checkable against the second fix."},{"q":"Does the cable length include the drop to each point?","a":"Yes, when you enter a measured route. The distance is from the distribution board to the point along the path the cable takes, which includes the climb from the board and the drop from ceiling level to a socket. A route measured along the wall at socket height understates the cable by the drop, which on a two storey building is a meaningful number of metres across the whole job."}]$q$, $a${"summary":"A wiring material take off that refuses to size a cable category you have not measured.","description":"An electrical estimate is a count and a length. The count is points, the length is the route from the board to each point, and everything else on the page is those two numbers multiplied by the materials a circuit needs. Cable, conduit, boxes, switches and boards all follow from them, which is why the estimate is only as good as the layout it is built from.\n\nWhat the tool will not do is design the installation. Cable size follows current, protection and volt drop, circuits follow the load and the regulations in force where you are building, and both are an electrician's decisions. Once those are made and the points are marked, the material quantity is arithmetic, and that is the part the estimator owns. Where a run has not been measured, it is reported as missing instead of estimated.","functions":["Counts points from the schedule you enter: sockets, switches, light positions and fixed appliance outlets, each with its own run.","Multiplies the points by the measured route length, including the drop from ceiling level to each accessory.","Selects cable by the circuit type and size you assign, then sums the length by size for the cable order.","Counts back boxes, mounting boxes, plates and accessories from the points, and boards from the circuits you specify.","Applies the waste allowance you set to the cable and the accessories, as separate visible lines.","Reports an unmeasured run as missing, so an incomplete layout cannot total as a finished one."],"worked":"A three bedroom house with forty two points, an average run of eleven metres including the drop, gives four hundred and sixty two metres of route. Allow ten percent for dressing and terminations and the cable order is about five hundred and ten metres, split by the sizes you assigned: sockets on two point five square millimetre, lighting on one point five. Add forty two back boxes, the plates for the same count, one distribution board with the ways you specified, and the outlets. The estimate is a count and a length throughout, and the only figure a sparky is likely to change is the route, which is why measurement is the input that matters.","advantages":["Points and routes stay separate, so a change in layout does not disturb the cable arithmetic.","Cable is summarised by size, which is how it is bought.","Accessories are counted from the points, so back boxes and plates are not forgotten.","An unmeasured run shows as a gap instead of a guessed length.","The estimate states that design and certification sit with the electrician."],"limits":["It does not size cable, select protective devices or check volt drop.","It does not design circuits, earthing or the consumer unit's configuration.","It does not include testing, certification or the labour to install.","It does not include specialist systems such as fire alarm, data or CCTV unless you count them as points.","It does not know your local wiring regulations, which is a design input you supply."]}$a$, $s${"title":"Electrical Estimator","description":"A wiring material take off that refuses to size a cable category you have not measured. An electrical estimate is a count and a length.","keywords":"electrical estimator, electrical estimator, building services, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 917, 'longform'),
  ('conduit-wiring-estimator', 'Conduit and Wiring Estimator', '/electrical-conduit-wiring-estimator', 'services', 5, $q$[{"q":"How much conduit do I need for a house?","a":"Measure the runs. Conduit is bought by length, so the only figure that matters is the path each run takes from the board through the building to its last point, plus the drops at each end. An average of nine metres over twenty odd points is a typical flat; a larger house with long corridors and two floors is nearer twelve. The estimator multiplies your measured runs by their count and adds the boxes and couplings the joints need."},{"q":"How do I know which cable size to use?","a":"From the circuit design, not from the estimate. Cable size follows the current the circuit carries, the protective device, the grouping and the volt drop, and every one of those is a design decision made against the wiring regulations where you are building. The estimator asks you what size you are pulling and adds the lengths by size, so the cable order matches the design. Using the tool to choose a size would be using a measuring tape as a rule book."},{"q":"Are junction boxes and switch plates included?","a":"Yes, both are counted. Boxes follow the points, with a box at every accessory and at every joint, and switch plates follow the switches. Couplings follow the joints in the run, which is a function of the length and the stock lengths you buy. That is why the accessory count is not a rate per square metre: a room with four switches and no sockets needs four boxes and four plates, whatever its floor area."},{"q":"Which conduit types can I estimate?","a":"Surface, concealed and buried, each on its own line, because they are different products with different costs and different installation work. A surface run in a garage and a buried run to a gate light do not belong in one total. The estimator keeps them apart and applies your measured length to each, so a change of method shows in the order instead of disappearing into an average."},{"q":"How much cable goes inside a conduit?","a":"The cable runs inside the conduit on the same path, so its length follows the conduit's length with the number of cores you specify for the circuit. Where a run carries three circuits, the cable is counted three times and the conduit sized for the group. A draw wire or spare capacity is a separate item you add deliberately, not an allowance folded into the cable, because a spare capacity that nobody records tends to be forgotten at second fix."}]$q$, $a${"summary":"A shopping list for a wiring loop: conduit, wire by the reel, and the boxes that join them.","description":"Conduit is the one electrical material that is bought almost entirely by length, and its length is decided by the route rather than by the number of rooms. The estimator takes the runs you describe, adds the boxes and couplings those runs need, and returns an order in the units a supplier sells.\n\nCable inside the conduit is measured on the same run, because it is pulled through the same path. That single decision, measuring conduit and cable from one route, is what keeps the two orders consistent. Where a run carries three circuits the conduit is larger, and the estimator lets you say so per run instead of applying one size across the building.","functions":["Calculates conduit length from the runs you enter, with the number of bends and the drop at each end included.","Sizes each run from the cable count you assign, so a busy run is not priced as a single circuit.","Counts boxes, couplings and saddles from the run length and the points along it.","Measures the cable on the same route, with the cores and size you specify per circuit.","Reports a run with no measured length as missing rather than assuming a per point average.","Keeps surface, concealed and buried conduit on separate lines, since they take different products."],"worked":"A flat with twenty two light and socket points on a measured route averaging nine metres gives a hundred and ninety eight metres of conduit, and the same length of cable per single circuit run. Allow ten percent for terminations and the order is about two hundred and eighteen metres of conduit with the same in cable, plus twenty two boxes, the couplings for the joints and saddles at the spacing you set. Add one run of four circuits on a longer path and that run is sized up, with its cable counted three times over, which is what the per run inputs are for.","advantages":["Conduit and cable are measured from one route, so the two orders agree.","Runs are sized individually, which matches how a busy corridor differs from a bedroom.","Bends and drops are counted, which is where a length-only estimate falls short.","Boxes and couplings follow the run, not a rate per point.","A run without a measurement is reported as a gap."],"limits":["It does not size conduit or cable, and it does not check fill or derating.","It does not design circuits, protection or earthing.","It does not include trunking, tray or ladder unless you measure it as a run.","It does not include testing, certification or labour.","It does not cover fire alarm or data containment, which have their own requirements."]}$a$, $s${"title":"Conduit and Wiring Estimator","description":"Conduit is the one electrical material that is bought almost entirely by length, and its length is decided by the route rather than by the number of rooms.","keywords":"conduit and wiring estimator, conduit and wiring estimator, building services, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 881, 'longform'),
  ('steel-beam-calculator', 'Steel I-Beam Calculator', '/structural-steel-i-beam-calculator', 'structure', 5, $q$[{"q":"How do I calculate the weight of a steel I-beam?","a":"Multiply the mass per metre of the profile by the length, then by the number of members. The profile's mass is a published property, so a three hundred by one hundred and fifty universal beam carries roughly forty kilogrammes for every metre of its length, and two six metre beams weigh four hundred and eighty kilogrammes before any cutting allowance. The calculator does that from the profile and length you select, and summarises the order by profile so a fabricator can quote from it."},{"q":"How far can a steel I-beam span without support?","a":"There is no single answer, because the span depends on the load above it, the restraint the floor gives the top flange and the deflection the finish can tolerate. What the page does is flag the point at which a section stops being safely selectable from a table, at eight metres on the default rule, and say so rather than return a section. Beyond that point the span is an engineering question with a real answer, and it is not one a weight calculator should invent."},{"q":"Why is there no default price for steel?","a":"Because there is no verified steel price book for most markets. A made up rate per tonne would produce a total that looks authoritative and is wrong, and a quotation built on it fails when it meets a real supplier. The tool asks for the price you have been quoted and multiplies it, so every cost on the page can be traced to a document. Where a market does have a verified price, the tool uses it."},{"q":"How do I choose the beam profile?","a":"From the design, and the tool measures what the design specifies. Depth follows the span and the load, mass follows the depth once the profile family is chosen, and the family itself follows the connection detail and what the fabricator stocks. Where two profiles work structurally, the lighter one is usually the cheaper one to erect and the heavier one the cheaper to buy, which is a commercial judgement rather than a calculation."},{"q":"Does the steel estimate include connections, base plates or fire protection?","a":"No. Connections, base plates, bolts, welds and fire protection are all outside the estimate, as are erection, crane hire and painting. They are priced by the fabricator and the erector, and they are often a third of the delivered cost of the steel. The estimate covers the members by profile and weight, which is the part a supplier quotes on and the part you can check with a tape measure on delivery."}]$q$, $a${"summary":"Span to tonnage, because steel is bought and quoted by mass, not by length.","description":"A steel beam is bought by weight, so the calculation is a section multiplied by a length. Everything that makes it interesting sits around that multiplication: which profile, what mass per metre, how long, and what happens when the span gets long enough that the section stops being the only question.\n\nThe estimator returns the weight and the cost from a price you enter, because there is no honest default for steel in a market without a verified price book. That is a deliberate refusal, not a gap. Where the tool has a verified price it uses it; where it does not, it asks, because a made up tonne rate is the kind of number that ends up in a tender and then in an argument.","functions":["Calculates the mass of a beam from the profile's mass per metre and the length you enter, with the count for multiple members.","Summarises the order by profile, so a mixed frame produces a schedule rather than a single total.","Flags spans at the threshold where a section needs checking by an engineer, at eight metres on the default rule.","Costs the steel from the price per tonne or per metre you enter, with no assumed market rate.","Adds a cutting and fabrication allowance only as a percentage you set, so its size is visible.","Reports a missing span or profile as incomplete instead of choosing a section."],"worked":"Two beams of six metres in a three hundred by one hundred and fifty universal beam, at a mass of about forty kilogrammes per metre, come to four hundred and eighty kilogrammes plus a five percent cutting allowance, which is five hundred and four. Enter a price of one thousand per tonne and the steel is five hundred and four units of cost, with fabrication, connections and fire protection outside it. Push the same beam to nine metres and the page raises the span flag, because beyond the threshold the section is no longer something to select from a table without a check.","advantages":["Weight is calculated from the profile rather than estimated from the length.","A mixed frame produces a schedule by profile, which is what a fabricator quotes from.","The span threshold is flagged in the open rather than buried in documentation.","The price is yours to enter, so the cost line is traceable to a supplier rather than to an assumption.","A missing input is reported, which keeps an incomplete frame from looking finished."],"limits":["It does not design the beam, and it does not check bending, shear or deflection.","It does not size the section for a span, a load or a floor.","It does not include connections, base plates, bolts, welds or fire protection.","It does not include erection, crane hire or paint.","It does not determine tax or duties, which appear only where a configured rule applies."]}$a$, $s${"title":"Steel I-Beam Calculator","description":"Span to tonnage, because steel is bought and quoted by mass, not by length. A steel beam is bought by weight, so the calculation is a section multiplied by a","keywords":"steel i-beam calculator, steel i-beam calculator, structural materials, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 926, 'longform'),
  ('plumbing', 'Plumbing Estimator', '/plumbing', 'services', 5, $q$[{"q":"How do I estimate plumbing materials for a building?","a":"Measure the runs and count the fixtures. Supply, waste and drainage are measured separately because they take different pipe and different falls, and fittings are counted where those runs turn or branch. The estimate then returns pipe by diameter, fittings by type and the fixtures with their valves and traps. A plumbing estimate that starts from a fixture count and a rate per bathroom will be short on pipe and fittings every time."},{"q":"Does the plumbing estimate include a soakaway or septic tank?","a":"No, it does not. A septic tank, soakaway or treatment plant is a separate design, sized from the occupancy and the ground, and it has its own material and excavation quantities. The estimator covers the pipe, fittings and fixtures inside the building. Where a drainage run leaves the building, measure it as a drainage run and price the tank or soakaway separately, so the two numbers stay checkable."},{"q":"Which pipe sizes should I choose?","a":"From the design and the fixture demand, not from a table in a quantity tool. Supply sizes follow the flow and pressure available, waste sizes follow the fixtures discharging into them and the fall, and drainage follows both plus the local regulations. The estimator asks which size you are running and adds the length by size, so the order matches a design that has already been made."},{"q":"What does a plumbing estimate include?","a":"Pipe measured by length, fittings counted, and the fixtures you schedule with the valves, traps and connections each one needs. Supply, waste and drainage stay on their own lines. Insulation, supports and fixings are counted where you specify them. It is a material estimate for the plumbing installation, and it deliberately stops at the fixtures rather than wandering into the rooms around them."},{"q":"How do I allow for pipe falls and bends?","a":"Falls add length on drainage runs, since a pipe running at a gradient covers more distance than its horizontal projection, and bends add fittings at every change of direction. Measure the route along its actual line and count the bends the route needs. The estimator uses your measured route, and a route you have not measured is reported as missing instead of being closed with an assumption."}]$q$, $a${"summary":"Fixture counts and measured pipe runs turned into pipes, fittings and valves.","description":"A plumbing estimate follows the pipe. Runs are measured, fittings are counted where the runs turn and branch, and fixtures are counted where they are installed. The three are bought differently, so they are calculated separately and then presented as one order.\n\nWhat the estimator refuses to do is guess the route. A plumbing layout in a building that is not yet built is a drawing rather than a measurement, and a measured route and a straight line between two fixtures differ by a surprising amount once risers, bends and falls are counted. Where a run has not been measured, the page reports it, which is the difference between an estimate that can be checked and one that merely looks complete.","functions":["Calculates pipe length from the measured runs you enter, by diameter and by service.","Counts fittings at the terminations and branches you describe: elbows, tees, reducers and couplers.","Counts fixtures from your schedule, with the valves and traps each one needs.","Separates supply, waste and drainage runs, since they take different materials and different falls.","Applies the waste allowance you set to pipe and fittings as separate visible lines.","Reports a run without a measurement as missing rather than assuming a length per fixture."],"worked":"A bathroom refit with four fixtures, a measured supply run of twenty two metres in fifteen millimetre pipe and a waste run of nine metres in forty millimetre, gives thirty one metres of pipe, twenty eight fittings at the terminations and branches, and the fixtures with their valves and traps. Add a water heater and its isolation valves and the schedule grows by the fittings that connection needs. Nothing in the order came from the fixture count alone, which is the reason the runs are the input that matters.","advantages":["Pipe, fittings and fixtures are counted separately, which matches how they are bought.","Supply, waste and drainage runs stay apart, so materials are not mixed.","Fittings follow the route, which is where a per fixture rate runs short.","A missing measurement is reported, keeping an incomplete layout visible.","Valves and traps are counted with the fixtures that need them, and not left to second fix."],"limits":["It does not size pipe or design the system, and it does not check pressure or flow.","It does not include water storage, pumping or treatment beyond what you count.","It does not include sanitary ware outside your schedule.","It does not include excavation, trenching or making good.","It does not include labour, testing, chlorination or certification, which the installer carries."]}$a$, $s${"title":"Plumbing Estimator","description":"Fixture counts and measured pipe runs turned into pipes, fittings and valves. A plumbing estimate follows the pipe.","keywords":"plumbing estimator, plumbing estimator, building services, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 810, 'longform'),
  ('doors-windows', 'Doors and Windows Estimator', '/doors-windows', 'structure', 5, $q$[{"q":"How do I estimate doors and windows for a building?","a":"Count them from the door and window schedule, by type and size, then let the estimator add the frames, linings and ironmongery each unit needs. Two counts drive everything: how many units of each type, and what specification each type carries. A room list is not a schedule, because a bedroom door and a bathroom door are different products with different ironmongery, and a count that mixes them produces an order that has to be corrected on site."},{"q":"Are frames and hardware included?","a":"Frames and architraves are added where your specification calls for them, and ironmongery is counted from the unit types: hinges by leaf, locksets and handles per door, stays and restrictors per window. What is not included is the installation side, which covers sealant, foam, packers, fixings and the labour to hang and adjust. Those are priced by the fitter, and folding them into a unit price hides the difference between a straightforward opening and an awkward one."},{"q":"Should I add a waste allowance to doors and windows?","a":"No. A waste allowance exists because a material is cut from a longer length or a larger sheet, and a door is not cut from anything. Waste on doors and windows is really damage, mis measurement or a change of mind, and the way to handle that is a stated contingency rather than a percentage applied to every unit. The estimator returns whole units, which is what arrives on the lorry."},{"q":"What happens if I leave the door and window counts blank?","a":"It reports the schedule as missing and leaves the line empty. A blank door count means the schedule has not been made yet, not that the building has no doors, and filling the gap with a count per room would produce an order that looks complete and is wrong. The page is designed so an unfinished design shows as unfinished, which is more useful than a number that has to be unpicked later."},{"q":"How are hinges and locksets handled?","a":"Hinges are counted per leaf, so a pair of doors carries twice the hinges of a single leaf, and the specification decides whether that is two or three per leaf. Locksets, handles and closers are counted per door, with the type following the schedule, since a bathroom lock and a front door lock are different products. The estimator links all of this to the unit type, so changing a door's specification changes its ironmongery without a second pass."}]$q$, $a${"summary":"A schedule of openings turned into frames, leaves and the hardware that goes with them.","description":"Doors and windows are counted, not measured, which makes this the simplest estimate in the catalogue and the one most often got wrong. The reason is that the count is decided by a schedule, and a schedule that is a room list rather than a door and window list will always be short.\n\nThe estimator works from the counts you enter, by type and size, and returns the units, frames and ironmongery each one needs. It does not add a waste percentage to a door, because a door is not cut from a longer door. It does not invent a count when you leave the schedule blank, because a blank schedule is a design that has not been finished rather than a house with no doors.","functions":["Counts doors and windows by type and size from the schedule you enter.","Adds frames, architraves and linings per opening according to the specification you choose.","Counts ironmongery from the unit types: hinges by leaf count, locksets, handles, stays and closers.","Calculates glazing and sill items where the unit type calls for them.","Reports a blank schedule as missing rather than defaulting a count per room.","Separates external and internal units, since they are different products with different performance requirements."],"worked":"A three bedroom house with nine internal doors and eleven windows: the doors bring nine units, nine frames, nine linings and eighteen hinges if two hinges per leaf are specified, plus nine locksets and nine sets of handles. The windows bring eleven units with their frames and sills, and the opening restrictors or stays the specification calls for. Nothing is multiplied by a waste factor, because the order is whole units. Change a window to a door and the schedule moves by one in each direction, which is exactly what a schedule is for.","advantages":["Units are counted rather than measured, which is how they are bought.","Ironmongery follows the unit types, so hinges and locks are not forgotten.","External and internal units stay apart, which keeps performance specifications clear.","A blank schedule is reported instead of filled with a per room assumption.","No waste allowance is applied to items that cannot be cut from stock."],"limits":["It does not design the openings, and it does not check structural lintels or restraints.","It does not specify performance, security or fire ratings.","It does not include installation, sealants or expanding foam.","It does not include decoration or making good around the openings.","It does not check the schedule against the drawing, which is a takeoff job."]}$a$, $s${"title":"Doors and Windows Estimator","description":"Doors and windows are counted, not measured, which makes this the simplest estimate in the catalogue and the one most often got wrong.","keywords":"doors and windows estimator, doors and windows estimator, structural materials, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 853, 'longform'),
  ('quotes', 'Quote Pipeline', '/quotes', 'quotes', 5, $q$[{"q":"What do the stages on a quote mean?","a":"Open means sent and awaiting a decision. Viewed means the client has opened the link, which is a useful signal but not agreement. Accepted and declined are decisions, recorded by you or by the client. Expired means the validity date passed without an answer. Each state is recorded, so a quote that has been read is not treated the same as one that has not, and the totals on the page only claim what the records support."},{"q":"When does a quote expire?","a":"On the validity date the quote carries, which you set when it is issued. A quote is an offer with a shelf life, and material prices move, so the date is part of the offer rather than an administrative detail. When it passes, the quote leaves the open list and appears as expired, and it can be revised and reissued at current prices. Reissuing creates a new quote, which is why the old one is left visible rather than deleted."},{"q":"Why are the totals shown per currency?","a":"Because a quote in one currency cannot be added to a quote in another without an exchange rate, and inventing a rate would make the total a fiction. Each currency is summed on its own, so the pipeline shows what is owed in each. That matters in a market where a client pays in local currency and a supplier quotes in another, because the two totals answer different questions and a blended figure answers neither."},{"q":"How is the acceptance rate calculated?","a":"From the quotes that reached a decision. Accepted divided by accepted plus declined, with open and expired quotes left out because they have not resolved either way. That is why the rate moves when a decision lands rather than when a quote is sent. Where no quote has resolved yet, the rate is reported as undetermined instead of as zero, because zero would read as failure when the truth is that there is no evidence yet."},{"q":"Which quotes should I chase?","a":"The oldest open quotes first, and among those the ones that have been viewed without an answer. Age is the honest signal, because a quote that has been sitting for three weeks is closer to expiry than one sent on Monday. The pipeline orders them by age and marks the ones that have passed your chasing threshold. Which one to call first is a judgement about the client and the job, and the page gives you the facts to make it rather than the decision itself."}]$q$, $a${"summary":"Where each quote stands, what came back, and which ones have gone quiet.","description":"A quote is not a number, it is a state. It is sent, it is viewed, it is accepted or it lapses, and the difference between those states is the difference between work you will do and work you have lost track of. The pipeline exists because most contractors can price a job and far fewer can say, on a Monday morning, which of last month's quotes are still alive.\n\nEverything on the page is derived from the quote records themselves. Value is reported per currency because a client in one country and a supplier in another do not share a unit, acceptance rate is calculated from resolved quotes rather than from a wish, and expiry follows the date the quote carries. Nothing is estimated, and nothing is filled in when a field is missing.","functions":["Groups quotes by state: open, viewed, accepted, declined and expired, so the list reflects where each one actually stands.","Totals value per currency, keeping each currency its own sum so no exchange rate is invented.","Calculates acceptance rate from quotes that reached a decision, and reports the rate as undetermined until there is one.","Flags quotes as needing chasing when they are past the point you set and still open.","Reports expiry from the validity date on the quote, so a lapsed quote leaves the open list without being deleted.","Shows the age of each open quote, which is the number that decides what to chase first."],"worked":"Twelve quotes were sent last month: eight are still open, three accepted and one declined. Acceptance rate is three from the four that reached a decision, so seventy five percent, and the eight open quotes are not in the calculation because they have not resolved. Two of the open ones are past fourteen days, so they appear as needing chasing, and their combined value is the number worth a phone call this week. If one of the eight expires on Friday without an answer, it moves to expired and the open value falls, which is a real change in the pipeline rather than a tidy up of a list.","advantages":["States are explicit, so a quote cannot be mistaken for work in hand.","Value is kept per currency, which keeps a parallel market honest.","Acceptance rate uses decided quotes only, so it means something.","Chasing follows age rather than memory.","Expiry is a state change, not a deletion, so the history survives."],"limits":["It does not send quotes or chase clients for you.","It does not convert currencies, and it will not invent a rate.","It does not decide what to price, which remains a commercial judgement.","It does not record payments or invoices against accepted quotes.","It does not infer acceptance from a conversation or a verbal yes."]}$a$, $s${"title":"Quote Pipeline","description":"Where each quote stands, what came back, and which ones have gone quiet. A quote is not a number, it is a state.","keywords":"quote pipeline, quote pipeline, construction materials, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 897, 'longform'),
  ('client-estimate', 'Client Estimate and Quote Engine', '/project-workspace/:id/client-estimate/new', 'quotes', 5, $q$[{"q":"How is the total on a quote built?","a":"From the priced lines. Each line carries a quantity from a calculator and a rate you set, and the total is their sum, not a rate applied to a floor area. Transport and tax appear as their own lines when they are configured, so the arithmetic is visible at every step. That structure is deliberate: a client who queries a total can be shown which line produced it, which is not possible with a single figure carrying an undisclosed loading."},{"q":"Does editing a quote recalculate the job?","a":"A draft does, because a quote should follow the job. Change a dimension and the quantity changes, so the draft recalculates and the total reflects what is now being offered. An approved quote does not, because it is a record of an agreement rather than a working document. That split is the whole reason the system distinguishes the two states, and it is what allows a revision to be compared against the original."},{"q":"Why can I not edit an approved quote?","a":"Because the client agreed to a specific document. Editing an approved quote in place would leave the copy they hold and the copy you hold describing different jobs, which is where disputes start. If the scope changes, the job is re measured and a new quote is issued with its own validity date, so the history shows what was offered, what was accepted and what changed. The approved original stays visible, which is the point of keeping it."},{"q":"What does the client see when I share a quote?","a":"The same lines and the same total, in the order they appear, with the validity date the quote carries. There is no separate client view that rounds or hides a line, and no price that appears only on one side. If transport or tax was not included, the document shows the total without it, which is more honest than an inclusive figure that nobody can decompose when a client asks why the number moved."},{"q":"Are transport and tax added automatically?","a":"Only where they are configured. Transport is a line you add when you charge it. Tax is not determined by the engine: where a rule applies to your market it appears with its basis stated, and where none applies the quote shows a total without tax and says so. That refusal is deliberate, because an invented percentage produces a number that looks final, is wrong for the jurisdiction, and is very hard to correct once a client has accepted it."}]$q$, $a${"summary":"The quote engine itself: costs in, markup applied once, and a record the client answers.","description":"A client estimate is where a calculation becomes an offer. The engine has already produced the quantities; this is the layer that turns them into lines with prices, a total, a validity date and a document a client can accept. It is deliberately the least clever part of the system, because an offer has to be stable.\n\nThat stability is why an approved quote stops changing. Once a client has agreed a number, editing it in place would mean the document they accepted and the document in the system no longer match. The engine recalculates when the job changes, the quote records what was agreed, and a revision becomes a new document with its own date rather than an edit to a settled one.","functions":["Builds the total from the priced lines, applying the quantity and the rate each line carries, with no hidden loading.","Recalculates a draft quote when the underlying job changes, so a quantity correction flows through before it is sent.","Locks an approved quote against editing, preserving the total the client agreed to.","Applies transport and tax only where they are configured, and states where they are not.","Renders a shareable document that carries the same lines and total the system holds.","Keeps the record of what was sent, so a later query can be checked against the offer rather than a memory of it."],"worked":"A job of four lines, masonry, concrete, roofing and labour, totals from the quantities the engines produced and the rates you set. Add transport as a single line if you charge it, and leave tax out where no rule applies, so the total is the sum it appears to be. Send it, and the client sees those lines in that order with that total. If they ask for a cheaper roof covering, the job is re measured, a new draft is produced, and the approved original stays as it was, which is what makes a comparison possible and an argument shorter.","advantages":["The total is the sum of the lines, so a client can check it without trusting a percentage.","A draft recalculates when the job changes, which prevents stale quantities being quoted.","An approved quote is stable, which protects both parties.","Transport and tax appear only where they are configured, with the gap stated.","The shared document and the record cannot drift apart."],"limits":["It does not decide the rate for labour or plant.","It does not determine tax, and it will not apply an assumed percentage.","It does not include work the underlying calculation did not measure.","It does not send reminders or chase acceptance.","It does not price variations outside the measured job."]}$a$, $s${"title":"Client Estimate and Quote Engine","description":"The quote engine itself: costs in, markup applied once, and a record the client answers. A client estimate is where a calculation becomes an offer.","keywords":"client estimate and quote engine, client estimate and quote engine, construction materials, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 881, 'longform'),
  ('using-frelux', 'Using FRELUX', '/faq', 'platform', 8, $q$[{"q":"Are the FRELUX construction calculators free?","a":"The calculators are free to use, and no account is needed to measure a quantity or read an answer page. An account is what carries the work: saved estimates, quotes with their states, and the client side of a quote. Measuring is free because a quantity should never be behind a paywall; keeping a pipeline of quotes and their history is the part that costs money to run."},{"q":"Do I need an account to use the calculators?","a":"No. You can open any calculator, enter dimensions and read the result without one. An account is needed when you want to keep the estimate, send it as a quote, or come back to it later. The distinction is deliberate: a visitor checking how many blocks a wall needs should not have to register to find out, and a contractor running a pipeline needs the records an account provides."},{"q":"How accurate are FRELUX calculators?","a":"The quantity is as accurate as the dimensions you enter, and the arithmetic on top of them is exact. Where the answer is less certain, the page says why: a coverage rate is a property of a product you select, a price comes from a market book or from you, and a tax line is left undetermined rather than assumed. So the honest answer is that the measurement is reliable, the inputs are yours, and the places where an assumption would otherwise sit are visible."},{"q":"Where do the prices in an estimate come from?","a":"Either from the price book of the market you select, or from a figure you enter. Where a market has a verified book, the tool uses it and the line can be traced to it. Where it does not, the tool asks for the price rather than falling back to another country's number, because a labour or material rate imported from a different market is a fiction with a decimal point. The same rule applies to steel, where no default exists at all."},{"q":"Why does an estimate say tax is not determined?","a":"Because applying a percentage that is not the rate for your jurisdiction would produce a confident wrong number, and a wrong number is worse than a stated gap. Where a tax rule is configured for your market, it appears as a line with its basis shown. Where none is configured, the estimate says tax is not determined. You can then add the rate that applies to you, and the total carries it as your figure rather than as the tool's assumption."},{"q":"How long does identity verification take?","a":"An administrator normally reviews a submitted identity document the same working day. If no administrator is available, the request is approved automatically fifteen minutes after submission, so verification never waits on someone being at a desk, and the account changes status without you resubmitting."},{"q":"Why is my account still unverified after I uploaded my ID?","a":"Because uploading a document does not grant pro status by itself. The document is held as a pending check while the account stays a client account and unverified, until an administrator approves it or the fifteen minute automatic approval runs and elevates the account."},{"q":"Which document can I upload to become a pro?","a":"One government identity document in your own name: a Nigerian NIN of eleven digits, an international passport, a drivers licence or a voters card. The number must be readable and must match the name on the account, and anything that does not match is sent back for review."}]$q$, $a${"summary":"What FRELUX does, how the numbers are produced, and what it will never pretend to know.","description":"FRELUX is a set of construction calculators that measure materials, a quote layer that turns those measurements into an offer, and a property intelligence layer that reads documents and plans. The thing that ties them together is a rule: the AI reads, the engine calculates. Nothing on the site guesses a quantity from a description when it can measure it from a dimension.\n\nThat rule explains most of the behaviour a new user notices. Prices come from the market you select or from a figure you enter. Tax is reported as undetermined rather than applied as a default. A blank input produces a gap rather than a typical value. Every one of those is the same decision seen from a different angle: a number you can check is worth more than a number you cannot.","functions":["Measures quantities from dimensions you enter, across the calculator catalogue, with each result showing its own arithmetic.","Uses prices from the selected market's price book, and asks for a figure where no verified price exists.","Refuses to determine tax, reporting it as undetermined unless a configured rule applies to your market.","Reports missing inputs as gaps rather than filling them with typical values.","Carries measured quantities into a client estimate with the rates you set.","Reads documents and plans to extract dimensions, and hands those to the deterministic engine rather than calculating from them directly."],"worked":"Take a wall of twenty metres by two point four, with four openings, priced in a market with a verified block price and no configured tax rule. The estimate returns the blocks, the mortar, the cement in the bag size that market sells, and a total that says tax is not determined. Change the market to one without a verified block price and the tool asks you for the block price instead of substituting another country's figure. Two behaviours, one rule: nothing is assumed on your behalf that you would not want assumed in a tender.","advantages":["Every quantity on the page can be traced to an input and a rule.","Prices are either from a verified book or from you, never invented.","A tax gap is stated rather than filled with a default percentage.","Missing inputs show as missing, which keeps an unfinished estimate visible.","The same measured quantities feed the calculators, the documents and the quote."],"limits":["It does not design structures, circuits, drainage or anything else that requires an engineer.","It does not verify that the dimensions you enter match the building.","It does not determine tax, duties or levies.","It does not include labour, plant or preliminaries unless you price them yourself.","It does not replace a code, a specification or a professional's judgement."]}$a$, $s${"title":"Using FRELUX","description":"FRELUX is a set of construction calculators that measure materials, a quote layer that turns those measurements into an offer, and a property intelligence","keywords":"using frelux, using frelux, construction materials, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 1048, 'longform'),
  ('demolition-calculator', 'Demolition and Debris Takeoff', '/demolition-calculator', 'sitework', 5, $q$[{"q":"How is demolition debris volume worked out?","a":"Measure each element in place, convert it to a solid volume, then apply a bulking factor to get the loose volume that goes in the skip. A wall of eighteen metres by two point four by two hundred and fifteen millimetres is nine point three cubic metres in place and about twelve and a half loose. The takeoff does that per element and per material, because the factor differs between brick, concrete and timber, and it rounds the result to skips at the capacity you hire."},{"q":"What is the bulking factor for?","a":"Bulking is the change in volume when a material is broken up. A cubic metre of wall in place occupies more than a cubic metre of space once it is rubble, because the pieces do not fit together the way the wall did. Factors vary by material and by how finely it is broken, so the page applies one per material and shows it. Ignoring bulking is the most common way a demolition estimate comes out a skip short and the site stops waiting for a lorry."},{"q":"How many skips will the job need?","a":"From the loose volume and the capacity of the skip you hire. Eight cubic yards is a common size, smaller ones are available, and the takeoff rounds up to whole skips because half a skip is not a thing you can order. Loose volume divided by capacity gives the count, and where the total lands just over a whole number, the usual choice is the larger skip rather than a second visit, since a return trip costs more than the difference in capacity."},{"q":"Can I mix walls, slabs, floors and roofs in one estimate?","a":"Yes, and they stay on separate lines. A job that removes a roof, a wall and a slab produces three different volumes with three different factors, and the total is their sum. Keeping them separate is what lets you see that the roof is most of the debris, or that the slab is what pushes the job from two skips to three. A single blended factor would give a total that is roughly right and cannot be checked against any single element."},{"q":"Does it cover permits, asbestos or disposal charges?","a":"No. Permits, notifications, asbestos surveys and disposal charges are outside the takeoff, and the last two matter more than they look. Asbestos cannot be identified from dimensions, and its presence changes both the method and the cost by an order of magnitude. Disposal charges vary by site, by material and by jurisdiction. The takeoff gives you the volume that those charges are applied to, which is the part it can honestly calculate."}]$q$, $a${"summary":"Turns a strip out into a debris volume and a skip count, element by element.","description":"Demolition is priced by what leaves the site. The structure comes down easily enough on paper; the debris is what fills skips, needs lorries and costs money by the tonne or the cubic metre. This takeoff converts the elements you are removing into a loose volume, and the loose volume is the number the disposal is priced on.\n\nThat conversion is the whole trick. A wall measured in cubic metres in place becomes a larger volume once it is broken, because broken masonry and concrete do not stack the way they stood. The bulking factor carries that change, and it is the difference between ordering four skips and needing seven. Where the factor is uncertain, the page says so rather than presenting a tidy number as fact.","functions":["Measures each element being removed from its own dimensions: walls by length, height and thickness, slabs by area and depth, roofs by area and construction.","Applies a bulking factor per material to convert solid volume into loose volume.","Converts loose volume into skips or loads at the capacity you specify, rounded up.","Counts elements by type, so a mixed demolition shows which material produces most of the debris.","Adds the weight estimate where a density applies, for disposal priced by the tonne.","Reports an element entered without dimensions as incomplete."],"worked":"A brick wall eighteen metres long, two point four high and two hundred and fifteen thick is about nine point three cubic metres in place. Broken, at a bulking factor of about one and a third, that becomes twelve and a half cubic metres loose, which is two skips of eight cubic yards with room to spare, or three if the skip is the smaller size. A concrete slab of forty square metres at a hundred and fifty millimetres adds six cubic metres, and seven and a half loose, so the job needs a third skip. Both figures came from the same rule, which is why mixing materials in one estimate still produces a usable total.","advantages":["Debris is calculated from the elements removed rather than from a rate per room.","Bulking is applied per material, so masonry and timber are not treated alike.","Skips are counted at the capacity you specify, so the order matches what you can hire.","A mixed demolition shows which element produces the bulk of the debris.","Weight is available where disposal is priced by the tonne."],"limits":["It does not assess structural stability, sequencing or temporary works.","It does not identify asbestos, and it does not cover hazardous waste handling.","It does not include permits, notifications or disposal charges, which vary by site and jurisdiction.","It does not include plant, labour or protection of retained structures.","It does not verify the construction of what is being removed."]}$a$, $s${"title":"Demolition and Debris Takeoff","description":"Turns a strip out into a debris volume and a skip count, element by element. Demolition is priced by what leaves the site.","keywords":"demolition and debris takeoff, demolition and debris takeoff, groundwork and site clearance, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 922, 'longform'),
  ('drainage-calculator', 'Drainage Materials Takeoff', '/drainage-calculator', 'sitework', 5, $q$[{"q":"Does the drainage tool design the falls?","a":"No. Gradients come from the drainage design, because they follow from the levels available and the self cleansing velocity the pipe needs. The takeoff asks for the fall you have designed and uses it to calculate the pipe length along the run and the level difference between its ends. Choosing a gradient is a design decision with a code behind it, and a materials calculator that picked one would be making a decision it cannot defend."},{"q":"How are pipes counted?","a":"By length, along the run and at the gradient, with the fittings counted at every junction and change of direction. The takeoff takes each run you describe, multiplies by nothing except its measured length, and sums the pipe by diameter and material. Where a run has not been measured, it is reported as missing, because a per chamber assumption produces a pipe order that is short on long runs and long on short ones."},{"q":"Where do inspection chambers come from?","a":"From the layout. A chamber goes where the pipe changes direction, where two runs meet, where the run changes diameter and at the head of a run. The takeoff counts them from the route you enter, with their covers and their benching, rather than applying a chamber per house. That is why a courtyard with four connections needs more chambers than a straight run of the same pipe length."},{"q":"Are bedding and surround included?","a":"Bedding and surround are calculated from the trench you describe, at the depth and width you enter, so the granular material is a quantity rather than an allowance. Where a specification calls for a surround rather than a bed, say so by entering the dimensions that apply, and the volume follows. It is the item most often omitted from a drainage estimate and the one that stops a gang on the first morning."},{"q":"Is this a hydraulic or code compliance design?","a":"No. It is a materials takeoff, so it counts what a designed system needs. Whether the gradients are adequate, whether the pipe sizes carry the flow and whether the layout complies with the drainage regulations where you are building are design questions with a code behind them. The takeoff assumes those answers exist and converts them into pipe, chambers, bedding and excavation, which is the part that can be counted."}]$q$, $a${"summary":"A preliminary pipe, chamber and bedding takeoff from the runs you measured.","description":"A drainage takeoff counts pipe, chambers and bedding, and it does all three from a route rather than from a property. The route is the layout you have drawn: pipes running between chambers, chambers at the changes of direction, and bedding under the whole of it.\n\nThe result is a materials list, not a hydraulic design. Pipe sizes, gradients and chamber positions come from the drainage design, which follows from the flows, the levels and the regulations where you are building. What the takeoff does is convert that design into pipe, fittings, chambers and bedding, in the quantities a merchant and a groundworks gang both work from.","functions":["Calculates pipe length from the runs you enter, along the gradient you specify rather than the straight line between ends.","Counts inspection chambers and gullies from the layout: at changes of direction, at junctions and at the head of each run.","Calculates bedding and surround from the trench length and the dimensions you give.","Counts fittings and connections at each junction, with the type following the pipe material you select.","Adds excavation volume where you enter the trench width and depth, so spoil is not forgotten.","Reports a run without a measured length as missing rather than assuming a distance per chamber."],"worked":"A run of thirty metres between two chambers, falling one in eighty, is thirty metres of pipe along its line, and its ends differ in level by three hundred and seventy five millimetres. Bedding at a hundred and fifty millimetres deep and three hundred wide is thirteen and a half cubic metres of granular material for that run. Add four more chambers at the junctions and the gullies at the low points, and the order is pipe, chambers, gullies, bedding and the excavation those dimensions imply. Nothing in it was derived from the number of bathrooms, which is the figure a rule of thumb would use.","advantages":["Pipe follows the route and the fall, not the straight line between two points.","Chambers are counted from the layout, which is where a length-only takeoff falls short.","Bedding and surround are calculated from the trench, so the granular order is real.","Excavation volume is available, so spoil is not a surprise.","A missing measurement is reported instead of assumed."],"limits":["It does not design gradients, pipe sizes or chamber levels.","It does not calculate flows or check hydraulic capacity.","It does not verify compliance with drainage regulations or codes.","It does not include soakaways, treatment plants or connection charges.","It does not include labour, plant or reinstatement."]}$a$, $s${"title":"Drainage Materials Takeoff","description":"A drainage takeoff counts pipe, chambers and bedding, and it does all three from a route rather than from a property.","keywords":"drainage materials takeoff, drainage materials takeoff, groundwork and site clearance, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 826, 'longform'),
  ('drywall-calculator', 'Drywall and Stud Partitioning', '/drywall-calculator', 'finishes', 5, $q$[{"q":"What does the drywall tool take off?","a":"Board on every face, framing by length, and the sundries that follow from both. It measures the partition, deducts the openings, converts the area into sheets at the size you buy, and separately counts studs at your spacing, track in top and bottom runs and the noggings for the rows you specify. Screws, jointing compound and tape then follow from the sheet size, because a smaller sheet means more joints and more compound."},{"q":"Are openings deducted automatically?","a":"Yes, on the faces they interrupt. A doorway removes board from both sides of a single partition, and the takeoff deducts it from each face rather than from the total once. Window and door heights matter as well as widths, because a deduction is an area. What an opening does not remove is framing: the studs either side of it, the head and the sill detail stay, which is why the board figure falls and the stud count barely moves."},{"q":"How is framing counted?","a":"By length, at the spacing you set. Studs are counted along the wall, plus one at each end, plus the studs either side of every opening, which the takeoff adds rather than leaving to site. Track is counted in top and bottom runs at the wall length, and noggings follow the rows you specify. Spacing is your input because it follows from the board thickness, the height and the performance required, and it changes the stud count directly."},{"q":"Are screws and jointing included?","a":"Both are included. Screws follow the board count and the fixing pattern, and jointing compound and tape follow the joints that the sheet size creates, so a partition with many joints gets the compound it needs. What is not included is the labour to tape and finish, and the finishing level itself, which is a specification decision about how flat the wall has to be for the decoration going on it."},{"q":"Does it design the partition?","a":"No. It measures materials for a partition whose specification has already been decided. Fire resistance, acoustic separation, height and deflection all change the board type, the layer count and the stud section, and those are design decisions with a code behind them. The takeoff converts the decided design into boards, studs and sundries, and it will not choose a stud for a three metre partition that needs a deflection head."}]$q$, $a${"summary":"Boards, studs, tracks, fixings and jointing for the partitions you measured.","description":"A drywall takeoff is a wall measured twice: once as a face area for board, once as a length for framing. The two numbers look similar and behave nothing alike. Board follows the area less the openings; studs, track and noggings follow the length and the spacing, which is why a wall with a wide doorway loses board and keeps nearly all its framing.\n\nThe takeoff returns boards, studs, track, screws, jointing compound and tape, each on its own line and each from its own rule. It does not design the partition: fire rating, acoustic performance, deflection and head details are specification decisions, and they change the board and the studs without changing the arithmetic this tool performs.","functions":["Calculates board from the face area on each side of the partition, at the sheet size you specify and rounded to whole sheets.","Deducts openings you list, by width and height, from the board area on the faces they interrupt.","Counts studs from the wall length at the spacing you set, plus the track in top and bottom runs and the noggings for the rows you specify.","Calculates screws from the board count and the fixing pattern, and jointing compound and tape from the joints the sheet size creates.","Separates single layer from double layer, since the board, screws and compound all double while the studs stay.","Reports a partition entered without a height as incomplete."],"worked":"A partition of nine metres by two point seven, single layer each side, at sheets of one point two by two point four, gives forty eight point six square metres of board across both faces, less a doorway of two square metres on each face, so forty four point six. At two point eight eight square metres per sheet that is sixteen sheets with waste. Studs at six hundred centres over nine metres give sixteen, plus top and bottom track in eighteen metres, plus noggings for the rows specified. The doorway removed four square metres of board and no framing at all, which is the distinction the takeoff exists to keep.","advantages":["Board and framing are calculated from different measurements, so an opening is treated correctly.","Sheet size drives both the board count and the jointing, which keeps the two consistent.","Track and noggings are counted, not assumed to come with the studs.","Single and double layer are handled without a second estimate.","The tool measures and does not design, which keeps the specification with you."],"limits":["It does not design the partition, its fire rating or its acoustic performance.","It does not assess the structure the partition fixes to.","It does not include insulation, sealant, deflection heads or movement joints.","It does not include taping labour, finishing levels or decoration.","It does not include openings in the framing beyond the board deduction."]}$a$, $s${"title":"Drywall and Stud Partitioning","description":"A drywall takeoff is a wall measured twice: once as a face area for board, once as a length for framing.","keywords":"drywall and stud partitioning, drywall and stud partitioning, finishing materials, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 873, 'longform'),
  ('flooring', 'Flooring Materials Estimator', '/flooring', 'finishes', 5, $q$[{"q":"Which floor coverings does it price?","a":"Timber and laminate in packs, tile and stone by area and box, vinyl in sheet or tile, and carpet by the square metre with its underlay. Each is bought differently, so the estimator applies the coverage the product states rather than a single rate. Where a product is priced per square metre you get an area, and where it comes in packs you get whole packs, because a part pack is not something a merchant will sell you."},{"q":"How is the pack count decided?","a":"Area divided by the coverage the pack states, then rounded up, with your waste percentage applied before the rounding. A pack that covers two point two square metres will not tile a four point two by three point six room into a whole number, so the seventh pack becomes eight with the allowance. Because the rounding happens once across all the rooms, a whole floor is cheaper in packs than the same rooms ordered separately."},{"q":"Why does it ask for skirting perimeter as well as area?","a":"Because skirting is a length, not an area. A square room and a long narrow room can share a floor area and differ by several metres of skirting, and the skirting is bought by the length. Doorways interrupt the run, so they are deducted, and the same perimeter gives you the edge trim and the scotia where the covering meets a wall it does not run under."},{"q":"Is the waste percentage fixed?","a":"No, it is yours to set. A straight lay in a square room loses around five percent, a diagonal or herringbone in a hallway with several doorways loses fifteen or more, and a plank layout running through several rooms loses more again because the offcut at one end rarely fits the next. The percentage appears as its own line so a client can see what was allowed and why."},{"q":"Does it include levelling or underlay preparation?","a":"Levelling and preparation are outside the estimate. A subfloor that is out of flat needs a compound, which is a separate product with its own coverage, and one that is damp needs a membrane before anything is laid on it. Both are assessed on site rather than from dimensions, so the estimator asks instead of assuming, and a floor laid on a bad subfloor fails whether or not the pack count was right."}]$q$, $a${"summary":"Plank and sheet flooring by the pack, with the skirting and underlay that go with it.","description":"Flooring is the one finish bought in packs with a published coverage, which makes the arithmetic simple and the ordering easy to get wrong. Packs cover a stated area, cuts waste part of it, and the room's perimeter decides the skirting and the edge trims, which have nothing to do with the floor area at all.\n\nThe estimator keeps the two apart. Area decides packs, perimeter decides skirting and trim, and the waste percentage sits between them as a visible line you control, since a straight lay in a square room and a herringbone in a hallway with six doorways do not lose the same proportion of a pack.","functions":["Calculates floor area from the room dimensions and converts it into packs at the coverage each pack states.","Applies the waste percentage you set, before rounding to whole packs.","Calculates skirting and edge trim from the perimeter, less the doorways you list.","Separates the covering, the underlay and the fixings, since each has its own coverage rate.","Reports a room entered without dimensions as incomplete rather than defaulting a size.","Handles more than one room, so a whole floor is one pack count rather than a per room order."],"worked":"A room four point two by three point six is fifteen point one square metres. At two point two square metres per pack that is seven packs before waste, and eight with a ten percent allowance, which leaves a spare board and a half for the doorway and a future repair. The perimeter is fifteen point six metres, less one point eight for the doorways, so thirteen point eight metres of skirting. Underlay at fifteen square metres per roll means two rolls. The skirting did not change when the covering changed, which is the point of measuring the perimeter.","advantages":["Packs follow the published coverage rather than an assumed area.","Waste is a stated percentage, so a difficult layout can carry the allowance it needs.","Skirting follows the perimeter, so a change of covering does not disturb it.","Underlay and fixings have their own coverage, so none of them is estimated from the floor area by habit.","Multiple rooms produce one order, which is how flooring is bought."],"limits":["It does not assess the subfloor, its flatness or its moisture.","It does not include levelling compound or preparation beyond what you add.","It does not include adhesives for glue down products unless you price them.","It does not include door undercuts, thresholds or stair work.","It does not design the expansion gaps or the layout."]}$a$, $s${"title":"Flooring Materials Estimator","description":"Flooring is the one finish bought in packs with a published coverage, which makes the arithmetic simple and the ordering easy to get wrong.","keywords":"flooring materials estimator, flooring materials estimator, finishing materials, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 834, 'longform'),
  ('masonry-calculator', 'Masonry, Brickwork and Blockwork', '/masonry-calculator', 'structure', 5, $q$[{"q":"Which wall types does the masonry tool cover?","a":"Block walls, brick walls and thin joint systems, with the unit size and joint thickness following the type you select. Each has its own coverage per unit and its own mortar volume, so the tool does not blend them. Where a wall uses more than one type, measure each as its own wall and add the results, which keeps the block count and the brick count separate for ordering."},{"q":"How are openings handled?","a":"Deducted by width and height with their quantity, so doors, windows and vents come out of the unit count rather than being added as an afterthought. An opening is an area, not a count, so a wide low window and a narrow tall one are handled by their dimensions. What is not deducted is the extra cutting and the lintel above, which are separate items you price on their own."},{"q":"Does it work in different countries and markets?","a":"Yes. Cement packaging and mortar specifications come from the market you select, so a fifty kilogramme bag and a twenty five kilogramme bag are both handled, and the engine never falls back to one country's packaging when a market is set. Where the market's specification differs on joint thickness or mix, that is an input you can enter, so the same wall can be priced to a local practice without changing the tool."},{"q":"Are mortar and packaging included?","a":"Both are included, and they follow the wall rather than being added per square metre. Mortar volume follows the wall type and the joint thickness, so a thin joint system uses a fraction of the mortar a ten millimetre joint does, and the cement follows the mix you specify. Cement is expressed in the bag size sold in your market, so the order is a number of bags rather than a weight to convert at the counter."},{"q":"Does it check the wall structurally?","a":"No. It measures materials. Slenderness, lateral support, movement joints and reinforcement for a wall that is retaining or carrying load belong to an engineer, and a quantity tool that offered an opinion on them would be answering a question it cannot see the inputs for. Use the count to order blocks and the engineer's design to decide how the wall is built."}]$q$, $a${"summary":"Blocks, mortar and packaging for walls, with the openings taken out first.","description":"Masonry is where construction estimating starts, and it is still the discipline most often done by rule of thumb. A wall has a length, a height and a thickness, and from those three numbers come the units, the mortar and the cement, with no need for a rate per square metre that hides which block it assumed.\n\nThe calculator asks for the wall type because the unit differs: a block wall, a brick wall and a thin joint system have different unit sizes, different joint thicknesses and different mortar volumes. Openings are deducted by dimension, and the mortar follows the joint rather than the wall area, which is why a change of block size moves the cement as well as the count.","functions":["Calculates unit count from the wall area and the unit size you select, at the joint thickness specified.","Deducts openings by width, height and quantity, so doors, windows and vents come out of the count.","Calculates mortar volume from the joint thickness, the unit size and the wall area the units fill.","Converts mortar into cement and sand from the mix you choose, with cement in the bag size sold in your market.","Handles block, brick and thin joint walls, with the unit and joint inputs following the type.","Reports a wall entered without a height as incomplete rather than assuming a course count."],"worked":"A wall of twenty four metres at two point seven, in four hundred and fifty by two hundred and twenty five millimetre blocks at a ten millimetre joint, gives sixty four point eight square metres. A door and two windows account for five point four square metres, leaving fifty nine point four, which at a block covering just over a tenth of a square metre is about five hundred and eighty blocks before waste. Mortar at ten millimetres over that area is a little over half a cubic metre, which in a one to five mix is about a hundred kilogrammes of cement and the sand that goes with it.","advantages":["The unit and joint are inputs, so a change of block size changes both the count and the mortar.","Openings are deducted by dimension, which is where a hand count runs long.","Cement is expressed in the bag size sold in your market.","Wall types are distinguished rather than treated as one material.","A wall without a height is reported instead of guessed at a course count."],"limits":["It does not check the wall structurally: slenderness, lateral support and reinforcement are an engineer's work.","It does not include lintels, damp proof courses or wall ties unless you price them separately.","It does not include scaffolding, labour or mortar mixing plant.","It does not assess the foundation or the substrate the wall sits on.","It does not include plaster or render, which are measured by the finish tools."]}$a$, $s${"title":"Masonry, Brickwork and Blockwork","description":"Masonry is where construction estimating starts, and it is still the discipline most often done by rule of thumb.","keywords":"masonry, brickwork and blockwork, masonry, brickwork and blockwork, structural materials, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 866, 'longform'),
  ('paving-calculator', 'Paving and Block Paving', '/paving-calculator', 'sitework', 5, $q$[{"q":"How are pavers counted?","a":"Area divided by the area of one paver including its joint, then rounded up, with a cutting allowance for the pattern. A two hundred by one hundred paver at a ten millimetre joint covers about two hundred and thirty one square centimetres of finished surface, so forty eight square metres needs roughly two thousand two hundred. The count comes back in whole pavers, and the pattern adds to it, because herringbone cuts differently from a stack bond."},{"q":"Does the laying pattern change the quantity?","a":"Yes, through the cutting allowance. A stack bond in a rectangular area loses very little to cuts, a running bond loses more at the edges, and a herringbone or basket weave loses more again because the offcuts rarely fit anywhere. The calculator applies the allowance for the pattern you select, so the same area in two patterns produces two different paver counts, which matches what a paver layer would order."},{"q":"Are bedding sand and subbase included?","a":"Both are calculated from the area and the depths you enter, not assumed. Bedding sand is a thickness over the whole area, and subbase is a greater thickness that is compacted to a finished level, so it is ordered as a loose volume or a tonnage. Because the depths are yours, a garden path at a hundred millimetres of subbase and a driveway at two hundred are priced as the different jobs they are."},{"q":"Are these depths design values?","a":"No, they are inputs. Subbase and bedding depths follow from the traffic, the ground and the drainage, and they are the difference between a pavement that lasts and one that ruts in the first wet season. The calculator asks for the depths your specification calls for and shows the volumes they imply, so you can see the material cost of a specification change before you commit to it."},{"q":"Is edge restraint included?","a":"Edge restraint is calculated from the perimeter, less the openings you enter, and it is included as a line because it is bought by the metre and often forgotten. A pavement that is not restrained at its edges spreads, whatever the subbase. The perimeter also gives you the length of any channel or kerb you are adding, which is why the takeoff asks for the plan rather than only the area."}]$q$, $a${"summary":"Pavers, bedding sand and subbase from the area, the pattern and the depths you set.","description":"Paving is a surface over a structure, and both are bought by different measures. The pavers follow the area and the pattern, the bedding and subbase follow the area and the depth, and the edge restraint follows the perimeter, which is why a paving estimate that starts and ends with a paver count is only half a takeoff.\n\nThe calculator keeps the three apart and lets you set each depth, because those depths are specification decisions rather than defaults. A driveway and a garden path do not share a subbase, and a change from one to the other changes the granular volume by more than it changes the paver count. Where a depth is left blank, the page asks rather than choosing.","functions":["Calculates paver count from the area and the paver size you specify, at the joint width and pattern you select.","Applies the pattern's cutting allowance, since a herringbone loses more to cuts than a stack bond.","Calculates bedding sand from the area and the bed depth you set.","Calculates subbase from the area and the depth you set, in tonnes or cubic metres.","Calculates edge restraint from the perimeter, less the openings you list.","Reports a missing depth as an input rather than substituting a typical value."],"worked":"A driveway of forty eight square metres in two hundred by one hundred millimetre pavers, at a ten millimetre joint, comes to about two thousand two hundred pavers before cutting, and a herringbone pattern adds close to ten percent for the cuts at the edges. Bedding sand at thirty millimetres is one point four cubic metres. Subbase at a hundred and fifty millimetres is seven point two cubic metres, which is around fourteen tonnes once compacted density is applied. Edge restraint runs the perimeter, eighteen metres for an eight by six rectangle, less the driveway opening. The pavers changed by nothing when the subbase depth changed, which is why the two are separate lines.","advantages":["Pavers, bedding and subbase are calculated from their own rules rather than one blended rate.","The pattern changes the cutting allowance, which is where hand counts fall short.","Depths are inputs, so a driveway and a path are priced differently.","Edge restraint follows the perimeter, which a paver count cannot produce.","A missing depth is reported rather than assumed."],"limits":["It does not design the pavement, its subbase depth or its drainage.","It does not assess the ground or its bearing capacity.","It does not include kerbs, channels, gully connections or drainage falls.","It does not include labour, compaction plant or excavation disposal.","It does not include sealants or jointing sand beyond the quantity you specify."]}$a$, $s${"title":"Paving and Block Paving","description":"Pavers, bedding sand and subbase from the area, the pattern and the depths you set. Paving is a surface over a structure, and both are bought by different","keywords":"paving and block paving, paving and block paving, groundwork and site clearance, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 839, 'longform'),
  ('plastering-calculator', 'Plastering and Rendering', '/plastering-calculator', 'finishes', 5, $q$[{"q":"What does the plastering tool distinguish?","a":"Internal plaster and external render, and within those the difference between a gypsum finish and a cement based one. They differ in mix, thickness and preparation, so the calculator asks which you are applying before it calculates anything. Where a wall takes a render base coat and a plaster skim, measure the two as their own surfaces, because the products and the thicknesses are not interchangeable."},{"q":"How is the sand and cement worked out?","a":"From the area and the thickness, which gives a volume, then from the mix you specify. A one to four mix splits that volume into one part cement and four of sand, and the cement is then converted to the bag size sold in your market. A bagged product instead asks for its coverage, because a manufactured plaster states how many square metres a bag will cover at a stated thickness, which is a more direct route than a mix."},{"q":"Does thickness really change the quantity that much?","a":"Yes, and more than most people expect, because material follows volume. Doubling the thickness doubles the sand and cement on the same wall, and a two coat render at eighteen millimetres total uses well over twice the material of a single ten millimetre coat. That is why the thickness is an input and why the page shows the volume: a specification change that looks like a detail on a drawing is a lorry load of sand."},{"q":"Are beads, scrim and bonding agents included?","a":"Beads, scrim and bonding agents are counted where the specification calls for them. Beads follow the corners, reveals and stops you enter, measured as lengths, since a stop bead at a ceiling line is a metre of bead rather than an area. Scrim follows the joints and the changes of material. Bonding agent follows the area you treat, at its stated coverage, and it is the item most often left out of a plaster estimate."},{"q":"Does it allow for surface preparation?","a":"Only where you enter it. Surface preparation is a site judgement: a dusty wall needs a bonding agent, a smooth concrete wall needs a key, and a painted wall may need more than either. The calculator asks for the area you are treating and adds the product at its coverage, so the preparation is priced as its own line rather than folded into a trowel rate that assumes a perfect substrate."}]$q$, $a${"summary":"Cement and sand for plaster and render, by area and by the thickness you build.","description":"Plastering is a thickness business wearing an area costume. The area decides how much trowel work there is, and the thickness decides how much sand and cement arrives on site, which is why two walls of the same size with different specifications are different orders.\n\nThe specific difference is that plaster and render are not one material. A gypsum plaster on a wall inside and a cement render on a wall outside have different mixes, different thicknesses and different preparation, and the calculator keeps them apart so a wall is not priced at the other's rate. Beads, scrim and bonding agents are counted separately where the specification calls for them.","functions":["Calculates plaster or render volume from the area and the thickness you enter.","Splits the volume into sand and cement, or into bags of a bagged product, according to what you select.","Counts beads from the corners, reveals and stops you enter, by length.","Counts scrim and tape from the joints and changes of material you list.","Separates internal plaster from external render, since the mixes and thicknesses differ.","Reports a missing thickness as an input rather than applying a typical coat."],"worked":"A wall of thirty square metres in a fifteen millimetre cement render is zero point four five cubic metres of mortar, which in a one to four mix is about a tenth of a cubic metre of cement, roughly a hundred and forty kilogrammes, or three bags, and a third of a cubic metre of sand. The same wall in a three millimetre gypsum skim is four and a half square metres of a bagged product at a small coverage per bag, which is a very different order. Beads at the door reveals and the external corners come off the lengths you enter, not off the area.","advantages":["Thickness is an input, so a two coat specification shows its material cost.","Internal plaster and external render are kept apart, with their own mixes.","Beads and scrim are counted from the details rather than a rate per square metre.","Cement is expressed in the bag size sold where you are working.","A missing thickness is reported instead of assuming a coat."],"limits":["It does not assess the substrate, which decides whether a bonding agent or a key is needed.","It does not design the mix or specify admixtures or fibres.","It does not include floating, dubbing out or patch repairs to the wall.","It does not include scaffolding or access equipment.","It does not include decoration over the finish."]}$a$, $s${"title":"Plastering and Rendering","description":"Cement and sand for plaster and render, by area and by the thickness you build. Plastering is a thickness business wearing an area costume.","keywords":"plastering and rendering, plastering and rendering, finishing materials, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 836, 'longform'),
  ('reinforcement', 'Reinforcement and Bar Weight', '/reinforcement', 'structure', 5, $q$[{"q":"What does the reinforcement tool need from me?","a":"A bar schedule. For each bar mark the tool needs a diameter, a length and a number of bars, which is exactly what a bending schedule already states. From those three it calculates the weight using the unit mass of that bar size, sums the marks by diameter, and returns a total in kilogrammes. If you have a drawing without a schedule, the schedule has to be made first, because the weight cannot be inferred from the concrete."},{"q":"How is the weight calculated?","a":"Diameter gives the unit mass, and the mass multiplied by the length gives the weight of one bar, and that multiplied by the count gives the bar mark's total. A sixteen millimetre bar is about one point five eight kilogrammes for every metre, so a seven metre bar is eleven kilogrammes. The unit masses are physical properties of the bar, not market prices, so the arithmetic is the same wherever the steel is being bought."},{"q":"Which diameters are supported?","a":"The common diameters from six millimetres to thirty two, which covers most building work. Ranges beyond that depend on the supplier, and where a bar size is not in the list it can still be entered by its unit mass. Grade matters for strength but not for weight, so a schedule in a higher grade weighs the same as one in a lower grade, which is why the tool asks for diameter rather than grade."},{"q":"Is binding wire included?","a":"Binding wire is not included, and neither are spacers, chairs or tying labour. They are real costs and they are usually priced per tonne of reinforcement or as a separate sundries line. The estimate covers the bar weight from the schedule, which is what the fabricator quotes and what arrives on the lorry. Adding a wire percentage would be inventing a figure whose basis nobody could check later."},{"q":"Does it design the reinforcement?","a":"No. It measures the bars you specify. How much steel an element needs, where laps fall, how bars are anchored and curtailed are design decisions that come from the structural engineer's calculations. The tool's value is that it turns a finished schedule into a weight, a cost and an order, and it is deliberately incapable of deciding the schedule itself."}]$q$, $a${"summary":"A bar schedule turned into tonnage, with laps and binding wire priced.","description":"Reinforcement is measured in weight, and weight comes from three facts about each bar: its diameter, how many there are and how long each one is. A bar schedule already contains those, which is why the tool asks for the schedule rather than for a percentage of concrete volume.\n\nThat distinction matters commercially. A rate per cubic metre of concrete for reinforcement is a guess that hides the design, and it is wrong in both directions on different jobs. Counting actual bars tells you what to buy, what to cut and what to bend, and the total in kilogrammes is the figure a fabricator quotes from. Where a bar is entered without a length, the tool reports it rather than assuming an overlap.","functions":["Calculates bar weight from diameter, length and count, using the unit mass of each bar size.","Summarises the schedule by diameter, which is how steel is ordered and how a bending schedule is grouped.","Handles multiple bar marks, so a slab, a beam and a column can be scheduled together.","Applies a cutting and lapping allowance only as a percentage you set, with its size visible.","Converts weight to length where a fabricator quotes by the metre instead of the tonne.","Reports a bar mark without a length or a count as incomplete."],"worked":"Twenty five bars of sixteen millimetre at seven metres weigh sixteen millimetre bar at about one point five eight kilogrammes per metre, so eleven kilogrammes each, and two hundred and seventy six in total. Thirty bars of twelve millimetre at five metres come to about four point four four kilogrammes each, so a hundred and thirty three. Together the schedule is just over four hundred kilogrammes, and with a five percent lap allowance about four hundred and twenty. Nothing in that total came from the concrete volume, which is why it can be checked bar by bar.","advantages":["Weight follows the schedule, so the order matches what will be cut.","The summary is by diameter, which is how steel is sold.","Lapping is an allowance you control rather than a hidden loading.","Weight converts to length for fabricators who quote by the metre.","An incomplete bar mark is reported rather than closed with an assumption."],"limits":["It does not design reinforcement, laps, anchorage or curtailment.","It does not check bar spacing against the element's dimensions.","It does not include binding wire, spacers or chairs beyond what you add.","It does not include cutting, bending, delivery or fixing labour.","It does not replace the designer's bar bending schedule."]}$a$, $s${"title":"Rebar calculator: bar length and weight","description":"Reinforcement is measured in weight, and weight comes from three facts about each bar: its diameter, how many there are and how long each one is.","keywords":"reinforcement and bar weight, rebar calculator: bar length and weight, structural materials, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 815, 'longform'),
  ('waterproofing', 'Waterproofing Materials', '/waterproofing', 'finishes', 5, $q$[{"q":"Which waterproofing does it cover?","a":"Liquid applied coatings, sheet membranes and cementitious systems, each with its own coverage and detailing. The one you choose follows from the substrate, the water pressure and what will be laid over it, and that is a specification decision. The calculator asks which family you are using, because a sheet membrane is ordered in square metres with laps and a liquid is ordered in kilogrammes per coat."},{"q":"How are coats and coverage handled?","a":"Coverage per coat from the product, multiplied by the area, then multiplied by the number of coats you enter. Both figures are shown, because the per coat number is what tells you whether a tin is enough for one pass and the total is what you order. Coats are never assumed: a two coat system specified by a manufacturer and applied as one coat is the most common way a waterproofing job fails."},{"q":"What about membranes and tape?","a":"Both are counted from the details you list rather than from the area. Tape goes at the floor to wall junctions, the internal and external corners and the pipe penetrations, which means a small bathroom can need more tape than its area suggests. Sheet membranes also need their joints taped. Reinforcement fabric goes where movement is expected, and the calculator counts it from the runs you describe."},{"q":"What happens if I leave an area blank?","a":"A blank area is reported as missing and left out of the total, so an incomplete scope is visible rather than invisible. Treating a blank as zero is how a tanking estimate comes to look complete while missing a wall. The same applies to a detail with no length, which is reported rather than assumed to be a metre."},{"q":"Does it guarantee the detail is watertight?","a":"No. It calculates materials for a system you have specified. Whether the detail is watertight depends on the substrate, the preparation, the number of coats actually applied, the laps and the workmanship, and none of those can be verified from a quantity. What the estimate does is make sure the material to do the job properly is on site, which is the part that can be arranged in advance."}]$q$, $a${"summary":"DPC, membrane, coatings and tape for the areas you actually identify.","description":"Waterproofing is bought by area, by coat and by detail. A tanking membrane, a cementitious coating and a liquid applied system all cover a stated area per unit, all need more than one coat, and all need tape and reinforcement at the corners and junctions where water actually gets in.\n\nThe calculator handles those three separately because they fail separately. The area gives the bulk material, the coats multiply it, and the details are counted from the junctions you list. Where the area of a detail is not measured, it is reported, because a waterproofing estimate with an unmeasured wet room corner is an estimate that has left the hardest part out.","functions":["Calculates material from the treated area and the coverage the product states, per coat.","Multiplies by the number of coats you specify, showing the per coat and total quantities separately.","Counts tape and reinforcement from the junctions, corners and pipe penetrations you list.","Separates liquid applied, sheet membrane and cementitious systems, since their coverage and detailing differ.","Applies the waste allowance you set to the sheet materials, where cutting produces offcuts.","Reports an area left blank as missing rather than treating it as zero."],"worked":"A bathroom with twelve square metres of floor and eighteen of wall to be tanked is thirty square metres of treated area. A liquid system at one point five kilogrammes per square metre per coat, in two coats, needs forty five kilogrammes per coat and ninety in total. Tape for the floor to wall junction runs the room perimeter, fourteen metres, plus the internal corners, plus two pipe collars. A sheet membrane instead needs the same area in square metres of membrane with laps, and its tape only at the joints. The same room, two systems, two different orders, and both from the same measured area.","advantages":["Coats are applied explicitly, so a two coat system is not priced as one.","Details are counted from junctions, which is where failures happen.","Systems are kept apart, so coverage is not carried across products.","Sheet waste is a stated percentage for the cuts at corners and upstands.","A blank area is treated as missing, not as nothing to do."],"limits":["It does not guarantee the detail is watertight, which depends on workmanship and preparation.","It does not design the system or select a product for the substrate.","It does not include drainage falls, screeds or protection boards.","It does not include testing, and it does not cover remedial work.","It does not assess the structure or the movement the detail has to accommodate."]}$a$, $s${"title":"Waterproofing Materials","description":"DPC, membrane, coatings and tape for the areas you actually identify. Waterproofing is bought by area, by coat and by detail.","keywords":"waterproofing materials, waterproofing materials, finishing materials, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 802, 'longform'),
  ('painting-estimator', 'Painting Estimator', '/painting-estimator', 'finishes', 5, $q$[{"q":"What makes this different from the paint calculator?","a":"Scope and cost rather than a single quantity. The paint calculator gives litres for a room. The estimator covers walls, ceilings, trim, doors and preparation separately, each measured by its own rule, and shows theoretical against practical quantities so the losses that site work produces are visible. It is the same arithmetic underneath, applied to a whole job instead of one surface."},{"q":"Why does it show theoretical and practical quantities separately?","a":"Because theoretical coverage assumes a perfect substrate and a perfect applicator. The product states a spread rate on a prepared, sealed surface, and a real wall takes more: porous plaster absorbs, cutting in uses paint that never reaches the wall, and a roller holds a litre that never leaves it. Practical quantity applies the loss percentage you set to the theoretical figure, and showing both means the difference can be argued about rather than discovered."},{"q":"How is the ceiling treated?","a":"As its own surface, with its own area and often its own product. A ceiling takes a matt emulsion in most specifications, and it may need a different preparation from the walls. Measuring it separately means the ceiling quantity can be ordered and priced on its own, which matters on a job where ceilings and walls are being decorated at different times or by different people."},{"q":"Do colour and surface condition change the quantity?","a":"Colour does not change the quantity in the arithmetic, and surface condition does, through the coats you specify and the preparation you list. A sharp colour change usually needs an extra coat, which is a decision you make and enter. A porous or patched wall needs sealer or primer, which is a separate product with its own coverage. The tool does not decide either; it prices what you decide."},{"q":"Where does coverage come from?","a":"From the product record for the paint you select, not from an assumed spread rate. Where a product has no stated coverage, the page asks for the figure rather than substituting a typical one, because coverage varies widely between a premium emulsion and a contractor grade product in the same tin size. That is also why the estimate is honest about the gap between the stated coverage and the practical one."}]$q$, $a${"summary":"Room by room painting quantities from real product data, with warnings instead of hidden percentages.","description":"The paint calculator answers how much paint a room needs. The painting estimator answers what the job costs, which is a different question with more lines: preparation, ceilings, trim, the difference between theoretical coverage on paper and what a painter actually gets out of a tin.\n\nThat difference is why the page shows two quantities. Theoretical coverage is the product's stated spread rate multiplied by the area and the coats. Practical quantity adds the losses that real work has: roller retention, cutting in, porous surfaces and the second pass over a patch that did not cover. Showing both is what stops a job being ordered at the theoretical figure and running out two thirds of the way through.","functions":["Calculates paint from the area, the coats and the product's stated coverage, showing the theoretical and practical quantities separately.","Treats ceilings as their own surface, with their own product and their own area.","Counts trim, doors and frames as their own items, since they are measured by length or by unit rather than by area.","Adds preparation products, such as filler, primer and sanding, where you specify them.","Applies the practical loss percentage you set, so the gap between theory and site is visible.","Reports a surface entered without dimensions as incomplete."],"worked":"A flat with a hundred and eighty square metres of wall and sixty of ceiling, in two coats at twelve square metres per litre, is theoretically thirty litres of wall paint and ten of ceiling paint. Add a practical loss of ten percent and the order becomes thirty three and eleven, which is the difference between finishing with a part tin and going back for more. Trim at forty metres of skirting and twelve doors is priced by length and unit, not by area, and two of the doors need a primer coat because they are bare timber.","advantages":["Theoretical and practical quantities are both shown, so the loss is visible and adjustable.","Ceilings, walls and trim are measured by their own rules.","Preparation products are priced as lines rather than absorbed into a trowel rate.","Doors and frames are counted rather than converted to an area.","An unfinished surface is reported as incomplete."],"limits":["It does not assess the condition of the surface or specify a coating system.","It does not include labour, access equipment or masking.","It does not judge colour coverage, which is a product property.","It does not include exterior systems with different products and exposure.","It does not include decoration of specialist substrates."]}$a$, $s${"title":"Painting Estimator","description":"Room by room painting quantities from real product data, with warnings instead of hidden percentages. The paint calculator answers how much paint a room","keywords":"painting estimator, painting estimator, finishing materials, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 809, 'longform'),
  ('structural-calculator', 'Concrete and Structural Takeoff', '/structural-calculator', 'structure', 5, $q$[{"q":"What does the structural takeoff measure?","a":"It measures concrete and reinforcement for the elements you describe. Each slab, beam, column, footing or wall is entered with its own dimensions, and the quantities roll up by material. Reinforcement is counted by bar diameter, length and number, then converted to mass using the unit weight of that bar size, which is how a steel order is placed. What it does not do is decide the dimensions: those come from the structural design, and the schedule assumes they are already fixed."},{"q":"Where do the dimensions come from?","a":"From you, and from the drawing you are reading. The length, breadth and depth of each element are entered as they appear on the design, and the bar schedule supplies the diameters and lengths for reinforcement. The tool does not scale a drawing or infer a section from a span, because a takeoff built on inference is a takeoff that cannot be checked. Where a dimension is missing, it is reported as missing so the gap is closed on the drawing before anything is ordered."},{"q":"Is this a structural design?","a":"No. It is a material schedule, which is a different document from a design. Sizing members, calculating loads, checking deflection and detailing reinforcement are engineering work, and the tool assumes that work is done. The value it adds is turning a finished design into quantities and an order that can be placed, checked and audited, which is where most of the arithmetic and nearly all of the clerical error live."},{"q":"How are the concrete ingredients split?","a":"From the mix you specify, in proportions by volume, converted to the bag size sold in your market. A one to one and a half to three mix and a one to two to four mix give noticeably different cement content for the same concrete volume, so the mix is an input rather than a default. Sand and aggregate are then expressed by volume or by tonne, and cement by bag, because that is how each is bought at a merchant in most markets."},{"q":"Can I mix slabs, beams, columns and footings?","a":"Yes, and they should be, because a frame is placed and poured in sequence rather than in one operation. Each element keeps its own line with its own dimensions and quantity, and the materials roll up across the whole set. That way a slab can be ordered for one pour and columns for another, while the totals still tell you what the whole frame needs. Mixing everything into a single volume loses the sequence and makes a partial pour impossible to price."}]$q$, $a${"summary":"Concrete volumes and reinforcement quantities for the structural elements you survey.","description":"A structural takeoff is a schedule, not a design. Slabs, beams, columns, footings and walls are each measured from their own dimensions, and the totals roll up by material so the steel order and the concrete order are separate documents. The tool holds that shape because a concrete frame is bought as materials, not as elements.\n\nWhat it will not do is decide the size of anything. A beam is measured at the depth it was designed to, a slab at its designed thickness, and the reinforcement counted in the diameters and lengths on the bar schedule. Those are the inputs. The output is the concrete volume, the formwork area where you ask for it, and the reinforcement weight by diameter, which is what a supplier and a fixer both work from.","functions":["Measures each element type from its own dimensions: length, breadth and depth for a slab, section and length for a beam or column.","Rolls the totals up by material, so all the concrete is one figure and all the reinforcement is another, while each element keeps its own line.","Calculates reinforcement weight from bar diameter, length and count, using the unit mass of the bar size.","Converts concrete volume into cement, sand and coarse aggregate from the mix you specify.","Expresses cement in the bag size sold in your market, and keeps sand and aggregate by volume or by tonne as you prefer.","Reports an element with a missing dimension as incomplete, instead of closing it with a typical value."],"worked":"A slab ten metres by eight at a hundred and fifty millimetres is twelve cubic metres. Two beams six metres long at three hundred by six hundred add two and two tenths cubic metres. Six columns three metres high at three hundred by three hundred add one and six tenths. The total is close to sixteen cubic metres of concrete, and at a one to one and a half to three mix that is roughly five cubic metres of cement, seven and a half of sand and fifteen of aggregate, in bags and tonnes for your market. Reinforcement comes separately: twenty five bars of sixteen millimetre at seven metres, plus thirty of twelve millimetre at five metres, converted to kilogrammes by bar mass and summed by diameter, so the steel order is a schedule a fabricator can cut from.","advantages":["Elements stay separate and materials roll up, which is the shape both a checking engineer and a supplier need.","Reinforcement is summarised by diameter, so the bar order matches how steel is sold.","Concrete splits into ingredients from the mix you set, instead of a single volume nobody can order.","Missing dimensions are reported rather than filled, which prevents an incomplete drawing becoming an incomplete pour.","Cement follows the market's bag size, so the same schedule works in different countries."],"limits":["It does not size members, calculate loads or check deflection.","It does not design reinforcement, laps or anchorage, and it measures the bars you specify.","It does not include formwork unless you ask for it, and it does not design the falsework.","It does not replace a bar bending schedule from the designer.","It does not include labour, pumping, testing or curing."]}$a$, $s${"title":"Concrete and rebar takeoff: volumes and bars","description":"Concrete volumes and reinforcement quantities for the structural elements you survey. A structural takeoff is a schedule, not a design.","keywords":"concrete and structural takeoff, concrete and rebar takeoff: volumes and bars, structural materials, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 978, 'longform'),
  ('concrete-takeoff-calculator', 'Concrete Slab Takeoff', '/concrete-takeoff-calculator', 'structure', 5, $q$[{"q":"How is slab concrete calculated?","a":"Area multiplied by thickness, plus any thickenings and poured edges you describe, plus a waste allowance. The takeoff does that from the dimensions you enter and shows the volume before and after waste, because a checking engineer wants to see both. The volume then converts into cement, sand and aggregate at the mix you select, in the units your market sells, so the order is in bags and tonnes rather than cubic metres of concrete that nobody delivers."},{"q":"Why does the thickness matter so much?","a":"Because volume is area times depth, so the depth multiplies the entire order rather than adding to it. Going from a hundred to a hundred and fifty millimetres on the same eighty square metre slab adds four cubic metres of concrete, and with it a tonne and a half of cement and several tonnes of aggregate. That is why a slab depth is a design decision with a material consequence, and why the page will not assume one for you."},{"q":"Does it allow for a poured edge or beam thickening?","a":"Yes, where you enter them. A thickening under a load bearing wall or a poured edge at the perimeter is a run with a width and a depth, and the takeoff adds its volume to the slab rather than ignoring it. Most slab estimates that come out short are short on exactly these details, because the area was measured and the edges were not."},{"q":"Is reinforcement included?","a":"No. Reinforcement is measured from a bar schedule, by diameter, length and count, which is a different calculation with a different unit. A percentage of concrete volume is a rule of thumb that produces a figure nobody can check against the design. The takeoff says plainly that the steel is separate, and the reinforcement tool measures it properly."},{"q":"Does it check the slab structurally?","a":"No. It measures materials for a slab whose thickness and reinforcement have been designed. Span to depth ratios, loading, restraint and crack control all belong to a structural engineer, and a slab that is under designed does not fail politely. The takeoff's job is to turn a decided design into concrete, sand and aggregate that can be ordered and poured."}]$q$, $a${"summary":"A slab volume, its ingredients and the bags behind them, from three dimensions.","description":"A slab takeoff is a volume with a waste allowance and a mix, and the arithmetic is trivial until the thickness matters. Thickness is the input that moves everything: a slab at a hundred and fifty millimetres is half the concrete of one at three hundred on the same plan, and every tonne of sand and aggregate follows it.\n\nThe takeoff measures the slab you describe, including thickenings under load bearing walls where you enter them, and converts the volume into cement, sand and aggregate at the mix you specify. Reinforcement is not included, because it is measured from a bar schedule rather than from a slab area, and the tool says so rather than adding a percentage of steel that nobody could check.","functions":["Calculates slab concrete from the area and the thickness you enter, with a waste allowance as its own line.","Adds beam thickenings and poured edges from the runs and sections you describe.","Converts the volume into cement, sand and coarse aggregate at the mix you select.","Expresses cement in the bag size sold in your market, with sand and aggregate by volume or tonne.","Separates slabs from footings and columns, so a pour can be ordered in stages.","Reports a slab without a thickness as incomplete rather than assuming a depth."],"worked":"A slab of eighty square metres at a hundred and fifty millimetres is twelve cubic metres. Two thickenings of nine metres at three hundred wide by four hundred deep add two point one six, so fourteen point one six in total, and fifteen with waste. At a one to two to four mix that is roughly four and a third cubic metres of cement, eight point two of sand and sixteen of aggregate, converted to bags and tonnes for the market you are building in. The reinforcement for that slab is a separate schedule, and the takeoff does not attempt it.","advantages":["Thickness is an input, so a deeper slab shows its full material cost.","Thickenings and poured edges are measured rather than absorbed into the area.","Concrete splits into ingredients from the mix you specify.","Pours can be ordered in stages because elements stay on separate lines.","An incomplete slab is reported instead of being given a typical depth."],"limits":["It does not design the slab, its thickness or its reinforcement.","It does not include reinforcement, which is measured from a bar schedule.","It does not include formwork, membrane, hardcore or insulation.","It does not include pumping, placing, finishing or curing.","It does not determine tax or levies, which appear only where configured."]}$a$, $s${"title":"Concrete Slab Takeoff","description":"A slab takeoff is a volume with a waste allowance and a mix, and the arithmetic is trivial until the thickness matters.","keywords":"concrete slab takeoff, concrete slab takeoff, structural materials, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 811, 'longform'),
  ('earthworks-cut-fill', 'Earthworks Cut and Fill', '/earthworks-cut-fill', 'structure', 5, $q$[{"q":"How are cut and fill volumes calculated?","a":"Area multiplied by depth for each excavation and each area to be raised, then adjusted for how soil behaves when it is moved. The calculator takes each area and depth you enter, sums the cut and the fill separately, and applies bulking to the former and compaction to the latter. What it will not do is assume a factor: both are inputs, because they vary with the soil and the method."},{"q":"Why separate cut from fill?","a":"Because excavated soil occupies more space than it did in the ground, and compacted fill occupies less. Adding the two raw volumes and subtracting one from the other produces a balance that no lorry can achieve. Keeping them separate lets each be adjusted by its own factor, and the difference between them becomes a real quantity of soil to import or remove, which is the number the haulage is priced on."},{"q":"What are the bulking and compaction factors for?","a":"Bulking accounts for the increase in volume when soil is disturbed, which is why a cubic metre of cut becomes more than a cubic metre in a lorry. Compaction accounts for the reduction when fill is placed in layers and rolled, which is why a cubic metre of fill needs more than a cubic metre of loose material to achieve it. Both are properties of the soil and the method, so both are yours to enter rather than defaults the tool invents."},{"q":"Can I price the haulage?","a":"Haulage is calculated from the volume to be moved and the capacity of the vehicle you enter, in loads. What is not included is the distance, the rate per load or the time, because those are commercial terms rather than quantities. You get the number of loads, which is the figure a haulier quotes against, and the surplus or deficit that decides whether they are taking soil away or bringing it in."},{"q":"Is this geotechnical advice?","a":"No. It is a volume calculation for a site whose levels have been designed. Soil classification, bearing capacity, slope stability, groundwater and contamination are geotechnical questions, and the factors you enter are assumptions that a geotechnical assessment would confirm or correct. Use the takeoff to price the movement you have designed, and use a geotechnical engineer to decide what can be moved and where it can go."}]$q$, $a${"summary":"Cut and fill volumes kept apart, with the bulking that decides how many trips leave site.","description":"Cut and fill is the discipline of moving soil from where there is too much to where there is too little. The two volumes are calculated separately, because they behave separately: soil dug out of the ground gains volume, and soil placed and compacted loses it, so a site that balances on paper rarely balances in a lorry.\n\nThe calculator computes cut from the areas and depths you enter and fill from the areas and depths you need, then applies bulking to the cut and compaction to the fill so the two can be compared honestly. Where they do not balance, the difference is a quantity of soil that has to be imported or removed, and that is the number the earthworks budget actually turns on.","functions":["Calculates cut volume from the areas and depths of each excavation you describe.","Calculates fill volume from the areas and depths of each area to be raised.","Applies a bulking factor to cut material, since excavated soil occupies more space than it did in the ground.","Applies a compaction factor to fill, since placed soil occupies less.","Reports the balance between cut and fill, as a surplus to remove or a deficit to import.","Calculates haulage from the volume and the capacity of the vehicle you specify."],"worked":"A site with a hundred and twenty cubic metres of cut and ninety of fill does not have thirty cubic metres spare. At a bulking factor of one point two five the cut is a hundred and fifty loose, and at a compaction factor of zero point nine the fill needs a hundred in its placed state, so the surplus is fifty cubic metres to remove rather than thirty. At eight cubic metres a lorry that is seven loads, not four. The two factors are what turn a balanced site into a haulage order.","advantages":["Cut and fill are kept apart, so the balance is a real comparison rather than a subtraction of raw numbers.","Bulking and compaction are explicit, so their effect can be seen and adjusted.","The surplus or deficit is reported in loose volume, which is how it is moved.","Haulage is calculated from the vehicle capacity you specify.","Depths are inputs, so a change of formation level shows its cost immediately."],"limits":["It is not geotechnical advice, and it does not assess soil class or bearing capacity.","It does not design levels, slopes, retaining or drainage.","It does not include compaction plant, testing or layer thicknesses.","It does not include disposal charges, permits or contaminated soil handling.","It does not verify the survey the areas came from."]}$a$, $s${"title":"Earthworks Cut and Fill","description":"Cut and fill is the discipline of moving soil from where there is too much to where there is too little.","keywords":"earthworks cut and fill, earthworks cut and fill, structural materials, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 840, 'longform'),
  ('roof-framing-calculator', 'Roof Framing and Board Feet', '/roof-framing-calculator', 'structure', 5, $q$[{"q":"What does the roof framing tool measure?","a":"Members by length and by volume: rafters, ridge, hips, valleys, purlins and battens, each from the pitch, the span and the spacing you enter. Board feet and linear metres are both returned because merchants price timber differently across markets. What it does not measure is the covering, the fixings or the trusses, since those follow their own rules and their own schedules."},{"q":"How does pitch change the quantity?","a":"Through the slope. A roof at thirty degrees has a sloped area of the plan divided by the cosine of the pitch, so a hundred square metres of plan becomes about a hundred and fifteen of roof. Rafters get longer as the pitch rises for the same span, and their count per unit of plan area rises with the slope. Both effects are in the arithmetic, which is why pitch is the first input rather than a detail."},{"q":"Why board feet as well as linear length?","a":"Because timber is sold and priced both ways. A merchant may quote a length and a rate per linear metre, while a mill or a specification may price by board feet, which is a volume measure of the nominal section. Returning both from one schedule means the order does not have to be converted by hand, and a conversion done at the counter is where the two figures usually drift apart."},{"q":"Does it size the members?","a":"No. Member sizing follows from the span, the load, the spacing and the grade of timber, and it comes from span tables or an engineer's design. The takeoff measures the members a design calls for, at the sections you specify. Where a span exceeds the tables, that is a design question with a real answer, and it is not one a quantity tool should be inventing."},{"q":"Are roof coverings included?","a":"No. The covering is measured by the roofing tool, which converts the sloped area into sheets or tiles at their cover width and lap. The framing takeoff covers the structure that carries the covering. Keeping them apart matters because a change of covering changes the battens and the spacing but not the rafters, and a single blended estimate would obscure that."}]$q$, $a${"summary":"Rafters, purlins and board feet from the span, pitch and spacing you set.","description":"A roof is measured on its slope, and its slope is longer than its plan. That single fact is why roof quantities differ from floor quantities of the same building, and why the framing takeoff starts from the pitch rather than from the footprint.\n\nThe tool returns members by length and by volume. Length is what you order from a timber merchant and what you cut; board feet is what a mill or a merchant prices in some markets, and a schedule that gives one without the other leaves you converting at the counter. Pitch changes both, because a steeper roof has longer rafters, more of them per unit of plan area, and more material in the same footprint.","functions":["Calculates the sloped roof area from the plan area and the pitch you specify.","Counts rafters from the span, the spacing and the pitch, with ridge, hips and valleys as their own runs.","Calculates purlins and battens from the area and the spacing you set.","Returns member lengths in linear metres and volumes in board feet, so both pricing conventions are covered.","Applies the waste percentage you set to cover cutting, which is higher on hips and valleys.","Reports a roof entered without a pitch as incomplete, since the area cannot be derived from the plan alone."],"worked":"A plan of a hundred square metres at thirty degrees has a sloped area of about a hundred and fifteen square metres, which is the plan divided by the cosine of the pitch. At six hundred millimetre rafter spacing over a nine metre span, with rafters at two point six metres of slope each side, the count is about thirty two. Boards at the sizes you specify then convert to board feet, so the same schedule prices in linear metres for one merchant and in board feet for another. Twenty degrees instead of thirty would shorten the rafters and cut the sloped area to a hundred and six, which is a real reduction in both timber and covering.","advantages":["Pitch drives the area, so a steeper roof is priced as larger rather than the same.","Rafters, ridges, hips and valleys are separate runs, which is how they are cut.","Both linear and board feet outputs are given, so either pricing convention works.","Spacing is an input, because it follows from the covering and the span.","A missing pitch is reported rather than assumed at a common value."],"limits":["It does not size the members, check span tables or design the structure.","It does not include the roof covering, which is measured by the roofing tool.","It does not include trusses, engineered joists or their design.","It does not include fixings, straps, hangers or bracing beyond what you add.","It does not include access, edge protection or labour."]}$a$, $s${"title":"Roof Framing and Board Feet","description":"Rafters, purlins and board feet from the span, pitch and spacing you set. A roof is measured on its slope, and its slope is longer than its plan.","keywords":"roof framing and board feet, roof framing and board feet, structural materials, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 842, 'longform'),
  ('temporary-works-calculator', 'Formwork and Temporary Works', '/temporary-works-calculator', 'structure', 5, $q$[{"q":"What does the temporary works tool take off?","a":"Contact area, and then the materials that area implies: ply in sheets, primary and secondary bearers, props and fittings, with a reuse allowance. It measures the surfaces the concrete touches, because that is what formwork is. Where an element has a void, a chamfer or a rebate, those are extra runs you describe, since they add contact area the main dimensions do not capture."},{"q":"How are reuse cycles treated?","a":"As a divisor on the purchased material. Ply used for one pour is consumed by that pour; ply used six times spreads its cost across six. The takeoff divides the area by the cycles you enter so the cost per pour is visible, and it leaves the cycles to you because they depend on the care taken striking, the surface finish required and how many identical pours there are."},{"q":"Why measure contact area instead of volume?","a":"Because formwork is a surface and concrete is a volume. The formwork that a beam needs is its soffit and its sides, which are areas, not its cubic metres. Measuring by volume would give the wrong order in both directions: a deep narrow beam and a shallow wide one of the same volume have very different contact areas."},{"q":"Does it check the falsework?","a":"No. Prop loads, bearer sizes, the grid, the foundation under the props and the striking sequence are design decisions, and falsework failures are among the most serious on site. The takeoff measures the materials for a falsework design that has been made. It does not check whether the design holds, and it does not replace the temporary works coordinator."},{"q":"Are scaffold and access included?","a":"No. Scaffolding, edge protection, ladders and access platforms are separate systems with their own hire and their own design. The takeoff covers formwork and falsework materials, which is the part that is consumed or amortised by the concrete. Access is usually hired by duration and priced separately, and mixing the two produces a figure that answers neither question."}]$q$, $a${"summary":"Formwork areas and the props behind them, reduced by the reuse cycles you plan.","description":"Temporary works are bought by area, not by volume, because formwork and falsework are surfaces and supports rather than substances. A slab soffit needs a contact area of ply, a beam needs its sides and its soffit, and a column needs four faces, and each of those is measured flat while the concrete is measured solid.\n\nThe takeoff returns contact area, the ply in sheets, the primary and secondary bearers, the props to a stated height, and the reuse cycles you expect. Reuse is the input that decides the real cost, since ply bought for one pour and ply used six times are different propositions on the same area. Where reuse is not stated, the tool asks.","functions":["Calculates contact area for each element type: slabs by soffit, beams by soffit and sides, columns by four faces.","Converts area into ply sheets at the sheet size you specify, with a cutting allowance.","Counts primary and secondary bearers from the prop grid you enter.","Counts props and fittings from the grid and the height you specify.","Divides the purchased area by the reuse cycles you set, so the cost per pour is visible.","Reports an element without its contact dimensions as incomplete."],"worked":"A slab of eighty square metres with two beams of nine metres at three hundred wide and four hundred deep: the soffit is eighty, the beams add nine metres by zero point three of soffit and two faces of four hundred deep, so about nineteen square metres of contact area in total, which is a fifth of the slab area again on two modest beams. At sheets of one point two by two point four that is seven sheets before cutting, eight with the allowance. Props at a grid of one point two metres give fifty six for the slab. With six reuse cycles, the ply cost per pour is one sixth of the purchase, and the props are hired by duration rather than consumed.","advantages":["Contact area is measured per element, which is how formwork is actually bought.","Reuse cycles make the difference between buying and amortising visible.","Bearer and prop counts follow the grid you set rather than an allowance.","Cutting allowance is stated, since formwork produces offcuts by nature.","An element without contact dimensions is reported."],"limits":["It does not design formwork or falsework, and it does not check prop loads.","It does not assess ground conditions under the props.","It does not include striking times, curing or a temporary works register.","It does not include scaffolding, edge protection, access or the temporary works register a site is required to keep.","It does not include labour, hire rates, transport or the design of the falsework it measures."]}$a$, $s${"title":"Formwork and Temporary Works","description":"Temporary works are bought by area, not by volume, because formwork and falsework are surfaces and supports rather than substances.","keywords":"formwork and temporary works, formwork and temporary works, structural materials, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 800, 'longform'),
  ('foundation-designer', 'Foundation Designer', '/foundation-calculator', 'structure', 5, $q$[{"q":"What does the foundation designer produce?","a":"A suggested footing width with its calculation, the bearing pressure that width imposes, and the concrete and blockwork for the resulting dimensions. It also accepts a width you specify, in which case it measures rather than suggests. What it does not produce is a design certificate: the output is a material quantity attached to a sizing calculation that an engineer can check or replace."},{"q":"Where does the bearing capacity come from?","a":"From you, ideally from a soil report. Bearing capacity is a property of the ground, and presumptive values exist for known soils at known depths, but the honest source is a investigation. The tool will not invent one, because a footing sized on an assumed capacity is a footing whose safety depends on an assumption nobody has tested. Where the value is unknown, the calculation stops."},{"q":"Is the sizing certified?","a":"No. What it produces is a sizing calculation with a material quantity attached, which an engineer can check and either accept or replace. Certification involves the ground investigation, the structural design, the reinforcement and the professional's judgement about the specific site. Treat the output as a check on a proposal or a starting point for a conversation, not as a document that satisfies a building authority."},{"q":"How does it differ from the foundation calculator?","a":"The foundation calculator measures materials for dimensions you already have. The designer starts one step earlier, from a load and a bearing capacity, and proposes dimensions before measuring them. Both end in concrete and blockwork quantities, and both state that reinforcement, excavation and design sit outside them. Use the designer when the footing size is still open, and the calculator when it is fixed."},{"q":"Can I override the suggested size?","a":"Yes, and it is the intended path for anything serious. Enter the width an engineer has specified and the suggestion steps aside, with the quantities following your figure. That is what makes the tool useful alongside a design rather than in place of one: it takes the decision as an input and returns the material order that decision implies."}]$q$, $a${"summary":"Preliminary strip, pad and raft sizing from the soil capacity you supply.","description":"A footing size is the product of a load and a ground condition, and both have to come from somewhere. This tool takes the load you enter, the bearing capacity you supply and the dimensions of the structure, and returns a footing size with the arithmetic shown, so the suggestion can be checked rather than believed.\n\nWhat it is not is a certified design. Bearing capacity comes from a soil report or a presumptive value for a known soil, and the value of that number is the whole value of the footing. Where it is unknown, the tool asks for it and stops. Where an engineer has specified a size, you enter it and the tool measures materials for that size instead.","functions":["Calculates a suggested footing width from the load and the bearing capacity you enter, and shows the calculation.","Accepts an override, so an engineer's specified width replaces the suggestion and drives the quantities.","Produces the concrete and blockwork for the footing and the wall above it at the resulting dimensions.","Reports the bearing pressure the footing actually imposes, so the assumption can be checked.","Flags a footing that falls below a practical minimum as needing attention rather than returning a thin pad.","Reports missing bearing capacity as a blocker rather than substituting a typical value."],"worked":"A wall carrying ninety kilonewtons per metre on ground with a bearing capacity of a hundred kilonewtons per square metre needs nine tenths of a square metre of ground of footing for every metre of wall, so a width of nine hundred millimetres. At that width and two hundred and fifty deep, the footing is two point two five cubic metres of concrete over ten metres, before waste. Enter a bearing capacity of fifty instead and the width doubles, and the concrete with it. The same wall, the same load, half the ground capacity, twice the concrete, which is why the number cannot be assumed.","advantages":["The calculation is shown, so the suggested width can be checked line by line.","An engineer's specified size overrides the suggestion and drives the quantities.","Bearing pressure is reported, which is the check that matters most.","A missing bearing capacity blocks the calculation rather than being invented.","The output is materials for a decided size, which is what a site needs."],"limits":["It is not a certified design, and its output is not a substitute for an engineer's.","It does not perform a soil investigation or derive bearing capacity.","It does not check settlement, sliding, uplift or reinforcement.","It does not include excavation, hardcore, blinding or dewatering.","It does not include labour, plant, testing or the inspection a building authority will ask for."]}$a$, $s${"title":"Foundation Designer","description":"A footing size is the product of a load and a ground condition, and both have to come from somewhere.","keywords":"foundation designer, foundation designer, structural materials, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 806, 'longform'),
  ('septic-sizing-calculator', 'Septic and Soakaway Worksheet', '/septic-sizing-calculator', 'services', 5, $q$[{"q":"What decides the septic tank size?","a":"The daily flow and the retention period, and the sludge and scum storage the standard requires on top of that. Flow follows the occupancy and the fixtures, and it is the number that matters, because a tank sized by bedroom count is sized by a proxy for people who may not be there. Enter the flow, choose the retention, and the working volume follows, with the materials for it."},{"q":"Why do I have to enter the flow rate myself?","a":"Because a flow rate derived from a bedroom count is an assumption about occupancy, and the consequences of getting it wrong are unpleasant and expensive to fix. A house with six occupants and a house of the same size with two produce very different loads, and a guest house is different again. Since you know the intended use and the tool does not, the flow is your input, and the calculation refuses to proceed without it."},{"q":"How is the soakaway sized?","a":"From the daily flow and the infiltration rate of the ground, which comes from a percolation test. The soakaway has to absorb what the tank discharges, so its area follows the flow divided by the rate at which the ground accepts it, and a clay soil needs many times the area of a sandy one for the same house. The materials then follow the area: pipe, granular fill and geotextile for the trench or the pit you describe."},{"q":"Does it issue a permit or environmental approval?","a":"No. It sizes a system and counts its materials. Permits, discharge consent, setback distances, groundwater protection and the treatment standard are administered locally, and the numbers here are inputs to that process rather than a substitute for it. Where a site is sensitive, the design may need to be different from the standard solution the calculator assumes."},{"q":"Can I work in gallons and feet?","a":"Yes. Enter volumes in litres or gallons and dimensions in metres or feet, and the calculation stays in the unit you chose rather than converting mid way. That matters for a tank specified in gallons by a supplier and a soakaway area measured in square metres on site, which is a common combination and a common source of mistakes when the conversion happens twice."}]$q$, $a${"summary":"Tank and soakaway volumes from your occupancy, flow and soil figures.","description":"A septic tank is sized by the volume of sewage it receives and the time the sewage needs to settle, and both of those come from occupancy and flow rather than from the size of the house. That is why the tool asks for the flow rate and refuses to infer it, and why the soakaway is sized from the same flow against the ground's capacity to absorb it.\n\nThe output is a volume, a soakaway area and the materials for both. What it is not is an environmental approval. Discharge, setbacks, percolation testing and the treatment standard are regulated locally, and the numbers here are the inputs to that process rather than a substitute for it.","functions":["Calculates tank volume from the daily flow and the retention period you specify.","Sizes the soakaway from the flow and the infiltration rate of the ground you enter.","Counts the materials for both: tank or chamber units, pipe, granular fill and geotextile.","Converts between metric and imperial volumes and dimensions where you select them.","Reports a missing flow rate as a blocker instead of deriving one from bedroom count.","Separates the tank from the soakaway, since the two are sized from different rules."],"worked":"A household of six at a hundred and fifty litres a day each produces nine hundred litres a day. At a retention of two days the tank needs eighteen hundred litres of working volume, plus the sludge and scum space the standard requires, so a tank of around two thousand seven hundred litres for a household of six. A soakaway at an infiltration rate of thirty litres per square metre per day for nine hundred litres a day needs thirty square metres of base area, which at a metre wide trench is thirty metres of trench. Both numbers came from the same flow, and both change together when the occupancy changes.","advantages":["Tank and soakaway are sized from the flow, which is the input that actually governs.","A missing flow rate is a blocker rather than a bedroom count guess.","Materials for both are counted, so the order covers the whole system.","Metric and imperial are both handled.","The tool states that approval sits outside it."],"limits":["It does not issue a permit or an environmental approval.","It does not perform or interpret a percolation test.","It does not design treatment beyond a septic system.","It does not cover setbacks, discharge consent or groundwater protection.","It does not include excavation, backfill, labour, desludging or the cost of an approval application."]}$a$, $s${"title":"Septic and Soakaway Worksheet","description":"A septic tank is sized by the volume of sewage it receives and the time the sewage needs to settle, and both of those come from occupancy and flow rather","keywords":"septic and soakaway worksheet, septic and soakaway worksheet, building services, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 809, 'longform'),
  ('insulation-calculator', 'Insulation Takeoff', '/insulation-calculator', 'finishes', 5, $q$[{"q":"What does the insulation takeoff measure?","a":"Insulation area by element, converted into packs at the product's coverage, plus vapour barriers, membranes and fixings. It handles more than one layer, because a specification often calls for two: one between the studs and one across them. What it does not do is judge the specification, since the thickness and the product follow from a thermal calculation rather than from a quantity takeoff."},{"q":"Does it calculate thermal performance?","a":"No. Thermal performance comes from the whole build up: the insulation, the structure, the cavity, the surface resistances and the thermal bridges, and it is calculated with those in front of you. The takeoff measures material. Reporting a U value from an insulation area alone would produce a figure that looks authoritative and ignores the timber studs every six hundred millimetres, which is where most of the heat actually goes."},{"q":"How do layers affect the order?","a":"Each layer is counted as its own material with its own coverage, so a hundred millimetre layer between the studs and a second layer across them are two orders rather than one doubled figure. That matters because the second layer is frequently a different product at a different thickness, and because the fixings and the tapes change when a layer is added."},{"q":"Is pack rounding applied?","a":"Yes. Rolls and packs cover a stated area at a stated thickness, so the takeoff divides and rounds up to whole packs, which is what a merchant sells. Where the coverage differs by thickness, as it does with mineral wool, the coverage for the thickness you selected is used rather than a figure for a different product."},{"q":"What about vapour barriers and fixings?","a":"Vapour barriers, membranes, tapes and fixings are counted where the specification calls for them, each at its own coverage. A vapour barrier is measured over the area it covers with the laps you allow, and fixings follow the spacing you enter. They are small items that decide whether the insulation performs as designed, which is why they are lines rather than an allowance."}]$q$, $a${"summary":"Insulation by pack from the area, layers and thickness you are fitting.","description":"Insulation is bought in packs covering a stated area at a stated thickness, which makes the order simple and the layers the tricky part. A wall with two layers has twice the material of a wall with one, and the second layer is often a different product at a different thickness and a different coverage.\n\nThe takeoff measures insulation area by element, converts it into packs at the coverage the product states, and counts the vapour barrier and the fixings the specification calls for. It does not calculate thermal performance: U values belong to a thermal calculation with the full build up, including the studs, the cavity and the surface resistances, and a quantity tool that reported one would be reporting a number it cannot support. What it does report is exactly what the specification asks for in material, so the thermal calculation can be priced without re measuring the building.","functions":["Calculates insulation area by element: roof, wall, floor, and any other surface you describe.","Converts the area into packs at the coverage each product states, at the thickness you select.","Handles multiple layers, counting each layer's material separately.","Counts vapour barriers and membranes from the area, at their own coverage and lap.","Counts fixings and tapes from the area and the spacing you set.","Reports an element without dimensions as incomplete."],"worked":"A loft of ninety square metres at two hundred millimetres, in rolls covering eight square metres at that thickness, is twelve rolls, and a cross layer of a hundred millimetres on top adds another six. A wall of a hundred and forty square metres in a hundred millimetre boards covering two point eight eight square metres each is forty nine boards. Vapour barrier at the wall and ceiling areas, with laps, comes to about two hundred and sixty square metres of membrane. The second layer doubled the loft material and changed nothing on the wall, which is why layers are counted one at a time.","advantages":["Layers are counted separately, which is the part a single area figure hides.","Packs follow the product's stated coverage at the thickness chosen.","Vapour barriers and fixings are counted, not left to site.","Elements are measured by their own dimensions rather than a rate per floor area.","The tool declines to report thermal performance it cannot calculate."],"limits":["It does not calculate U values, condensation risk or thermal bridging.","It does not assess the building's compliance with an energy standard.","It does not include airtightness tapes beyond the quantity you specify, nor the sealing of service penetrations that decides the result.","It does not include the structure the insulation sits within.","It does not include labour, access, removal of existing material or disposal of what comes out.","It does not check that the specified thickness fits the depth available in the structure you are insulating."]}$a$, $s${"title":"Insulation Takeoff","description":"Insulation is bought in packs covering a stated area at a stated thickness, which makes the order simple and the layers the tricky part.","keywords":"insulation takeoff, insulation takeoff, finishing materials, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 826, 'longform'),
  ('solar-pv-estimator', 'Solar PV Estimator', '/solar-pv-estimator', 'services', 5, $q$[{"q":"How does the solar estimator work?","a":"As a component takeoff. You describe the array size and the equipment, and it returns panels, inverters, isolators, mounting, cable and protection at the quantities that configuration needs, priced from the market book or from figures you supply. It does not decide the size of the system, because that follows from the load and the roof, and it does not forecast production, because that follows from the site."},{"q":"Where do panel and component figures come from?","a":"Panel and inverter counts follow from the array size and the equipment you specify, mounting follows the panel count and the rail system, and cable follows the measured runs. Every one of those is arithmetic once the design is fixed. Where a component's coverage is a property of the product, such as how many clamps a rail system needs per panel, that comes from the product record rather than from a guess."},{"q":"What if a component has no price?","a":"It is reported as a gap. A component carried at zero would make the quote look complete and would produce a total that cannot be delivered, and on a solar job the unpriced item is often the battery or the mounting system, which is not a rounding error. The page shows the gap so it can be closed with a real figure before the quote goes out."},{"q":"Does it design the array?","a":"No. Array size, string length, inverter matching, protection and earthing are design decisions that follow from the load profile, the roof and the regulations where you are building. What the tool does is take a decided design and return the components and their quantities, which is the part that can be counted and priced before anything is ordered."},{"q":"Are sun hours and losses assumed?","a":"No. Sun hours, tilt, azimuth, shading and system losses are all site specific, and a default figure would produce a yield estimate that looks precise and is wrong for most locations. Where you supply a figure, the page uses it and the assumption is visible. Where you do not, the estimate covers materials and leaves production to a proper yield calculation."}]$q$, $a${"summary":"Panels, inverter and mounting from either the roof area you have or the energy you need.","description":"A solar estimate is a list of components at the quantities a design calls for. Panels, an inverter, mounting, cable, isolators and a battery if one is specified, each with its own count, and each with a price that comes from a price book or from you. The tool does not decide the array, because the array follows from the load and the roof.\n\nWhat it refuses to do is invent the sunny hours. Yield depends on the location, the tilt, the shading and the losses, and those are site facts rather than constants. Where a figure is not supplied, the page asks, so a yield number in the estimate can be traced to an assumption someone made deliberately rather than one the tool made quietly.","functions":["Counts panels from the array size and the panel rating you specify, then rounds to whole panels.","Counts inverters, isolators, meters and protection from the array and the configuration you describe.","Calculates mounting from the panel count and the rail system's coverage per panel.","Calculates cable from the measured runs and the sizes you assign, including the DC and AC sides separately.","Prices each component from the market price book, or asks for a figure where none exists.","Reports a component with no price as a gap rather than carrying it at zero."],"worked":"A five kilowatt array in four hundred and fifty watt panels is twelve panels, not eleven and a bit, therefore twelve. Mounting at two rails of two and a half metres per panel gives sixty metres of rail with the clamps the system needs. A five kilowatt inverter with a DC isolator, an AC isolator and a generation meter completes the component list. Cable from the measured DC run of eighteen metres and the AC run of nine metres, and prices from the book or from your supplier. The yield figure, if you enter one, is yours, and it is the only number on the page that depends on the weather.","advantages":["Components are counted rather than quoted as a package, so a quote can be checked line by line.","Panels round to whole units, which is what ships.","Cable follows measured runs, which is where packaged quotes are usually light.","Missing prices appear as gaps instead of zeros.","Yield is an explicit input rather than a hidden assumption."],"limits":["It does not design the array, the string configuration or the protection.","It does not calculate yield, shading or payback.","It does not assess the roof structure or its waterproofing.","It does not include installation, scaffolding or commissioning.","It does not cover grid connection, metering arrangements or permits."]}$a$, $s${"title":"Solar PV Estimator","description":"Panels, inverter and mounting from either the roof area you have or the energy you need. A solar estimate is a list of components at the quantities a design","keywords":"solar pv estimator, solar pv estimator, building services, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 809, 'longform'),
  ('generator', 'Backup Power and Generator', '/generator', 'services', 5, $q$[{"q":"Does the tool size my generator?","a":"No. Generator sizing follows from the connected load, the starting current of the largest motor, the diversity you expect and whether the set takes the whole building or a protected subset, and it is calculated by an electrical engineer rather than by a quantity tool. The tool takes a size you have decided and returns the equipment and connections that size requires, which is the part a supplier and an installer both need."},{"q":"What does it actually take off?","a":"The set, the changeover, the protection, the cable by size, the earthing materials, the fuel storage and any containment for the runs. Each is counted from your specification and your measured routes rather than from a rule per kilowatt. That matters because two installations of the same capacity can differ by a hundred metres of cable depending on where the set sits and where it connects."},{"q":"Why is a blank cable run reported as missing?","a":"Because a generator is often the furthest thing from the board that it feeds, so its cable run is the longest on the site and the easiest to underestimate. A per metre allowance would be wrong in both directions, and the error lands on the most expensive cable in the building. Measuring the route and entering it keeps the order tied to the actual layout."},{"q":"Are fuel and consumption covered?","a":"Fuel is not included as a cost. The tool counts storage capacity, which is a capital item, but consumption depends on the load profile and the set's specific consumption, and running cost depends on the fuel price where you are. Those are operating figures that belong in a different calculation from an installation takeoff."},{"q":"Is the installation checked?","a":"No. Protection coordination, earthing design, changeover arrangements and the enclosure are all installation design, and the local wiring regulations govern them. The takeoff counts what the design calls for, so the installation can be priced and the materials ordered. Certification of the completed installation is a separate act by a competent person, and no quantity tool can stand in for it."}]$q$, $a${"summary":"Materials around a generator you have sized, with the cable run measured, not guessed.","description":"A backup power takeoff covers the equipment and the connections, not the sizing. Generator size follows from the load, the starting currents and whether the set has to run the whole building or a protected subset, and that is an electrical design question rather than a quantity.\n\nWhat the tool does is count the components a decided installation needs: the set itself, the changeover, the protection, the cable and the earthing, at the capacities you specify. Where a cable run has not been measured, it says so, because the run to a generator is often the longest cable on the site and the one most often priced from a guess.","functions":["Counts the generator, changeover switch and protection at the capacities you specify.","Calculates cable from the measured runs, by size, on the generator side and the distribution side.","Counts earthing materials from the electrode arrangement you describe.","Calculates fuel storage from the tank capacity and the number of tanks you need, with the bund and the pipework those tanks require.","Counts containment, tray or conduit for the runs you describe, since a generator feed is rarely a cable in free air.","Reports an unmeasured run as missing rather than applying a per metre allowance."],"worked":"A sixty kilovolt ampere set with a changeover rated for the same current, a distribution board for the protected circuits, and a cable run of twenty two metres from the set to the changeover. Two earth electrodes at the set and one at the building, with the conductor between them. A thousand litre tank, or two of five hundred if that is what the site can take, each on a bund with a fill point and a vent. The set and the changeover were specified before the tool was opened, which is the only order that produces a defensible installation.","advantages":["Equipment and connections are counted separately, so a quote can be compared item by item.","Cable follows the measured run, which is where packaged quotes fall short.","Earthing is counted, which is the item most often left out of a backup power quote.","Fuel storage follows the capacity you specify.","An unmeasured run is reported rather than assumed."],"limits":["It does not size the generator for a load.","It does not design the changeover, protection or earthing arrangement.","It does not include fuel consumption, running cost or servicing.","It does not include enclosures, acoustic treatment, exhaust routing or the slab and bund the set stands on.","It does not include installation labour, commissioning, load testing or the fuel to run the set during commissioning.","It does not include a service contract, spares holding or the maintenance schedule the set will need."]}$a$, $s${"title":"Backup Power and Generator","description":"Materials around a generator you have sized, with the cable run measured, not guessed. A backup power takeoff covers the equipment and the connections, not","keywords":"backup power and generator, backup power and generator, building services, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 807, 'longform'),
  ('heat-comfort', 'Heat and Comfort', '/heat-comfort', 'services', 5, $q$[{"q":"What does the heat and comfort tool compare?","a":"Two surface specifications. Each is described by its solar reflectance, its emittance and the product it came from, and the tool reports what those properties mean for the heat absorbed over the area you enter. It is a like for like comparison, so the value is in showing a client or a specifier the measured difference between a dark finish and a reflective one on the same building."},{"q":"Where do reflectance figures come from?","a":"From the product data, and the page shows where each figure came from so it can be checked. Reflectance and emittance are measured properties with standard test methods, and manufacturers publish them. Where a product has no published value, the tool reports the gap rather than assigning a typical figure, because a comparison built on an assumed property proves nothing."},{"q":"Does it predict indoor temperature?","a":"No. Indoor temperature depends on the whole building: the walls, the glazing, the shading, the ventilation, the thermal mass and how people use it. A surface comparison isolates one variable, which is what makes it useful and what makes it insufficient on its own. If you need a temperature prediction, that is a building simulation with the whole envelope in it."},{"q":"Why compare two surfaces instead of one?","a":"Because a single surface tells you nothing. The point of the tool is the difference between two options on the same building, which is the decision actually being made when a roof colour or a coating is chosen. Comparing one surface with nothing would produce a number without a reference point, and the specification decision would still be made on impression."},{"q":"Does it qualify for any green certification?","a":"No. Certification and rating schemes assess the whole building against a published standard, with modelling, verification and a assessor involved. A property comparison supports a specification choice, and it may be one input into a submission, but it does not qualify anything by itself. Claiming otherwise would be claiming a credential the tool cannot produce."}]$q$, $a${"summary":"How two finish choices change the solar energy a surface absorbs, side by side.","description":"Two roofs of identical construction can behave differently in the sun, and the difference is usually the surface. This tool compares surfaces: their reflectance, their emittance and the effect those properties have on how much heat a building absorbs, so a specification choice has a number attached to it rather than an adjective.\n\nIt is a comparison tool, not a simulation. It does not predict an indoor temperature, because that depends on the whole building, the ventilation and the occupancy. What it does is put two surface specifications side by side with their published properties, so the case for a lighter roof or a different coating can be made on evidence rather than on a habit.","functions":["Compares two surfaces on their solar reflectance and thermal emittance, using published product values.","Reports the difference in absorbed heat implied by those properties, on the area you enter.","Keeps the comparison on like terms, so a roof is compared with a roof and a wall with a wall.","Shows the source of each property, so a figure can be traced to the product it describes.","Reports an unspecified property as missing rather than assuming a value.","Keeps the comparison separate from the quantity, since the two surfaces are usually the same area.","Reports the absorbed load difference in watts over the area you enter, so the effect is physical rather than descriptive.","Keeps the surface properties and the quantity on separate pages of reasoning, so a specification change can be assessed before it is priced."],"worked":"A dark roof at a reflectance of zero point one absorbs nine tenths of the sun falling on it, and a white coating at zero point eight absorbs a fifth. On a hundred square metres at a peak irradiance of a thousand watts per square metre, the difference in absorbed load is about seven hundred watts per degree of exposure, which is a real number in a hot climate even before the building's own thermal mass is considered. The tool puts those two figures side by side; it does not tell you what the indoor temperature will be, because that needs the rest of the building.","advantages":["Surfaces are compared on published properties rather than on description.","The difference in absorbed heat is quantified on your area.","Each property is traceable to the product it came from.","The comparison is kept separate from the quantity, which rarely changes.","A missing property is reported, not assumed."],"limits":["It does not predict indoor temperature, energy use or comfort.","It does not run a thermal simulation or model ventilation.","It does not qualify a building for any certification or rating.","It does not account for dirt, ageing, weathering or the maintenance a reflective surface needs to keep its properties.","It does not assess the structure, waterproofing or detailing."]}$a$, $s${"title":"Heat and Comfort","description":"Two roofs of identical construction can behave differently in the sun, and the difference is usually the surface.","keywords":"heat and comfort, heat and comfort, building services, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 817, 'longform'),
  ('labour-estimator', 'Labour and Crew Productivity', '/labour-estimator', 'project', 5, $q$[{"q":"How are worker days calculated?","a":"By dividing each measured quantity by the output rate for that operation, then adjusting for the efficiency factor you set. Six hundred square metres of blockwork at twelve square metres per worker day is fifty days of work, and at an efficiency of zero point eight five it is fifty nine. The tool does that for each operation, sums by trade, and shows the crew size implied by the duration you want."},{"q":"Where does the site efficiency loss sit?","a":"As a multiplier on the calculated days, applied explicitly so it can be seen and changed. Site conditions, access, weather and the learning curve all reduce output, and the factor is where that reduction lives. A factor of one assumes a textbook site, which few are. The value sits in the open rather than inside a rate, so a project manager can disagree with it specifically instead of arguing about the whole labour line."},{"q":"Why are durations whole days?","a":"Because a crew is booked for days, not for fractions of one. Rounding at the operation level rather than at the total is deliberate: three operations of two and a half days are three crews for three days each in practice, not seven and a half days that can be squeezed. Rounding also makes the labour line slightly conservative, which is the right direction for an estimate that has to be delivered against."},{"q":"What if a productivity rate is missing?","a":"It is reported as missing and left out of the total, so the labour estimate shows where its own coverage stops. A default rate would produce a duration with nothing behind it, and labour durations feed directly into a programme that other trades are booked against. Where you do not know a rate, the honest move is to measure it on a similar job or to ask a foreman, and then to enter it."},{"q":"Does it produce a full programme?","a":"No. It converts quantities into worker days and shows the crew implied. A programme needs logic: which operations precede which, how many crews can work at once, what the critical path is and where the float sits. That is a separate exercise with its own tool, and the labour hours from this page are one of its inputs rather than its output."}]$q$, $a${"summary":"Worker days and crew duration per task, with the efficiency loss shown separately.","description":"Labour is the largest line in most construction estimates and the one most often carried as a percentage. This tool converts measured quantities into worker days, using the productivity rates you set, so the labour line has the same traceability as the material lines beside it.\n\nThe conversion is quantity divided by output per worker day, adjusted by the efficiency factor you enter. That efficiency factor is where the honesty lives: a gang working at scaffold height, in a heat wave or on a restricted site does not produce the textbook output, and pretending otherwise produces a programme that is optimistic and a labour cost that is short.","functions":["Converts each measured quantity into worker days at the productivity rate you enter for that operation.","Applies the site efficiency factor you set, as a visible multiplier rather than a hidden loading.","Rounds durations to whole days, since a gang cannot be booked for a fraction of one.","Summarises labour by trade, which is how crews are assembled and paid.","Totals worker days against the calendar duration you specify, so the crew size implied is visible.","Reports an operation with no productivity rate as missing rather than defaulting one."],"worked":"Six hundred square metres of blockwork at twelve square metres per worker day is fifty days of one person's work. With an efficiency factor of zero point eight five, which accounts for a site where the scaffold has to be moved, that becomes about fifty nine days. Against a programme allowance of twenty working days, the crew implied is three masons, which is the number that decides the labour cost and the sequence. If the rate were entered at eighteen square metres, the same wall would look like thirty three days, and the crew would be two, and the programme would slip.","advantages":["Labour comes from measured quantities rather than a percentage of the material cost.","The efficiency factor is visible, so its effect on duration can be argued about.","Durations are whole days, which matches how crews are booked.","Trade summaries show the crew each operation implies.","A missing rate is reported rather than defaulted."],"limits":["It does not produce a programme, a sequence or a critical path.","It does not account for weather, access restrictions or industrial relations.","It does not price labour, only the time it takes.","It does not include supervision, plant operators or non productive time.","It does not replace measured experience of a particular gang."]}$a$, $s${"title":"Labour and Crew Productivity","description":"Labour is the largest line in most construction estimates and the one most often carried as a percentage.","keywords":"labour and crew productivity, labour and crew productivity, labour, programme and cash flow, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 804, 'longform'),
  ('margin-calculator', 'Margin and Markup Calculator', '/margin-calculator', 'project', 5, $q$[{"q":"What is the difference between margin and markup?","a":"Markup is a percentage added to cost. Margin is a percentage of the selling price. On a cost of a hundred, a twenty percent markup gives a price of a hundred and twenty and a margin of sixteen point seven percent, because the profit is twenty on a price of a hundred and twenty. The calculator shows both from one input, so the number being quoted is unambiguous."},{"q":"Why does the basis matter so much?","a":"Because the two bases produce different prices from the same intention. A contractor who says they want twenty percent and applies it as markup is pricing at sixteen point seven percent of the price, which may be below the margin the business needs once overheads are recovered. Getting the basis wrong on a large job moves the price by thousands, and it is invisible unless both figures are shown."},{"q":"Is tax added automatically?","a":"No. Tax is reported as its own line where a rule applies to your market, and as undetermined where none does. Folding an assumed percentage into a selling price produces a figure that looks final, is wrong for the jurisdiction and is very hard to unpick once quoted. Where you need to show tax, add the rate that applies to you and it is carried as your figure."},{"q":"Can I work backwards from a target price?","a":"Yes. Enter a target margin and the calculator returns the price that achieves it, which is the direction most pricing decisions actually take. It is the same arithmetic rearranged, and it is more useful than forward pricing when a business knows the margin it needs to survive and is deciding whether a job is worth taking at all."},{"q":"Does it include overheads?","a":"Overheads are kept separate from profit. Recovery is a different calculation, usually a rate per unit of turnover or per project, and mixing it into a margin hides whether the business is covering its fixed costs. The calculator shows cost, overhead recovery, profit and price as distinct lines, so a job that looks profitable at the margin line can still be seen to be thin once overheads are counted."}]$q$, $a${"summary":"Client price, profit and tax with the margin or markup basis stated every time.","description":"Margin and markup are different numbers computed from different bases, and confusing them is the most common way a profitable job is priced at a loss. Markup is a percentage of cost. Margin is a percentage of the selling price. A twenty percent markup is a sixteen point seven percent margin, and the gap widens as the numbers rise.\n\nThe calculator does both, on the base you choose, and shows the selling price, the profit and the resulting margin together. Where a target margin is set it works backwards to the price, which is the direction most pricing decisions actually travel. Tax stays outside the arithmetic unless a configured rule applies, and it is reported as its own line when it does.","functions":["Calculates selling price from cost and either a markup or a margin, on the basis you select.","Shows the resulting margin and markup side by side, so the difference between them is visible.","Works backwards from a target margin to the price that achieves it.","Keeps overhead recovery separate from profit, since they are different lines.","Reports tax as its own line where a rule applies, and as undetermined where none does.","Reports a missing cost as a gap rather than treating it as zero, which would understate the price and the margin together."],"worked":"A job costing a hundred thousand, priced at a twenty percent markup, sells at a hundred and twenty thousand and carries a margin of sixteen point seven percent. To achieve a twenty percent margin instead, the price is a hundred and twenty five thousand, because the profit has to be a fifth of the price rather than a fifth of the cost. Five thousand of difference on one job, and on a year of jobs it is the difference between a business that grows and one that works for its clients without ever quite getting ahead.","advantages":["Margin and markup are shown together, with the base stated.","Backwards pricing from a target margin is supported, which matches how quotes are set.","Overheads stay separate from profit, so recovery can be checked.","Tax is a line, not an assumption folded into the price.","A missing cost is visible rather than being treated as nothing."],"limits":["It does not decide the margin a business should target.","It does not allocate overheads across jobs, which needs a recovery basis.","It does not determine tax, and it will not assume a rate.","It does not include cash flow, retention or financing cost.","It does not account for risk, contingency, retention or the cost of financing a job while it runs."]}$a$, $s${"title":"Margin and Markup Calculator","description":"Margin and markup are different numbers computed from different bases, and confusing them is the most common way a profitable job is priced at a loss.","keywords":"margin and markup calculator, margin and markup calculator, labour, programme and cash flow, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 807, 'longform'),
  ('cash-flow-timeline', 'Cash-Flow Timeline', '/cash-flow-timeline', 'project', 5, $q$[{"q":"How are payment stages built?","a":"From the percentages you set against milestones or dates in the programme, applied to the contract value. Each stage becomes a payment due in a period, and its value follows from the percentage. Where a stage is tied to an event, such as roof level, its date comes from the programme rather than from a guess, which is why the two tools belong together."},{"q":"What happens if the percentages do not total one hundred?","a":"It reports the remainder. A schedule of twenty, thirty and forty leaves ten percent unallocated, and the tool shows that as a gap rather than quietly scaling the others up. On a hundred and twenty thousand contract that gap is twelve thousand, which is the kind of money that turns into a dispute at the end of a job, so it is worth seeing while the contract is still being drafted."},{"q":"Can I model a retention?","a":"Yes, as a percentage held from each payment and released at the point you specify. It shows the cumulative amount held through the job and the amount released at the end, which matters because retention is money earned, invoiced and unavailable for months. A job that looks profitable on the margin line can still fail on the cash it has tied up in retention."},{"q":"Does it track actual payments?","a":"No. Actual payments are a ledger, and this is a forecast. What it shows is what should be due when, based on the stages you have agreed. Reconciling that with what has actually arrived is bookkeeping, and a forecast that pretends to be a ledger is worse than either on its own."},{"q":"Why phase payments at all?","a":"Because a single payment at the end means the contractor funds the whole job. Staging moves money closer to the work, which reduces the funding requirement and spreads the risk. The tool shows what each staging arrangement does to that requirement, so a negotiation about payment terms can be had with numbers rather than with instinct."}]$q$, $a${"summary":"A phased payment schedule from the contract value, with stages that must add to one hundred.","description":"A job is paid for over its life, and its costs are paid out over the same life at a different rhythm. Materials are bought before they are fixed, labour is paid weekly, and the client pays in stages that may lag both. The cash flow view exists to show that mismatch before it becomes an overdraft.\n\nIt is built from the payment stages you define, applied to the contract value, mapped onto the programme's dates. What it does not do is track money received, because that is a ledger rather than a forecast. It shows what should be due when, and with a retention applied, what will actually be released and when.","functions":["Builds payment stages from the percentages you enter against milestones or dates in the programme.","Checks that the stages total a hundred percent and reports any remainder rather than allowing a silent gap.","Applies retention as a percentage held per stage and released at the point you specify.","Maps the stages onto the programme dates, so each payment has a period rather than a position in a list.","Shows the cumulative value due against the cumulative cost, which is the line that reveals a funding gap.","Reports a stage with no date as unplaced rather than assuming it falls at the end.","Keeps currencies separate where a job spans more than one."],"worked":"A contract of a hundred and twenty thousand in four stages: twenty percent on start, thirty on roof level, forty on practical completion and ten on the defects period ending. Retention at five percent held from each stage leaves six thousand withheld through the job and released after the defects period. Costs run at roughly nine thousand a month for six months, so the second month is where the gap appears: costs of eighteen thousand against receipts of twenty four thousand that clear thirty days later. That gap is what the view exists to show, and it is the reason a profitable job can still stop.","advantages":["Payment stages and their dates sit on one page, so the mismatch is visible.","A stage schedule that does not total a hundred percent is reported, not absorbed.","Retention is modelled with its release point, which is money deferred rather than lost.","Cumulative value against cumulative cost shows the funding requirement.","Currencies stay separate, which keeps a cross border job honest."],"limits":["It does not track actual receipts, invoices or bank balances.","It does not calculate interest or financing cost.","It does not account for the lag between invoice and payment unless you build it into the dates.","It does not include variations, which change the value they are added to.","It does not forecast the cost side from quantities, only from the figures you enter."]}$a$, $s${"title":"Cash-Flow Timeline","description":"A job is paid for over its life, and its costs are paid out over the same life at a different rhythm.","keywords":"cash-flow timeline, cash-flow timeline, labour, programme and cash flow, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 809, 'longform'),
  ('boq-generator', 'BOQ and Quote Generator', '/boq-generator', 'commercial', 5, $q$[{"q":"Where do the BOQ lines come from?","a":"From the calculators. Each line records what was measured, in the unit that trade is measured in, at the quantity the calculation produced. The descriptions come from the measurement rather than from a template, which is what makes a line defensible when a client queries it. Nothing appears in the bill that was not measured somewhere in the system."},{"q":"Are contingency and tax added automatically?","a":"Contingency is a line you add, and tax is reported as undetermined unless a rule applies to your market. Neither is applied silently, because a bill is a document a client prices against and a client is entitled to see what is in it. A contingency folded into rates is invisible, and an assumed tax rate is wrong in most jurisdictions it is applied to."},{"q":"Can I defend a line to a client?","a":"Yes, and that is the point of generating rather than typing. The line carries the quantity, the unit and the description that produced it, so a query about the blockwork can be answered with a wall length, a height, an opening schedule and a block size. A bill that cannot be defended line by line is a negotiation rather than an estimate."},{"q":"Does it replace a quantity surveyor?","a":"No. A quantity surveyor measures, prices risk, structures contracts and takes responsibility for the figures. The generator presents measured work as a bill, which removes the transcription step and the errors that come with it. It does not replace the judgement about what to measure, how to price the risk or how to structure the contract."},{"q":"What if an estimate changes after the quote?","a":"The lines regenerate. A changed measurement produces a changed line, and the rates you set stay where they are, so the bill reflects the new quantity at the price you had agreed with yourself. Where a change was agreed with the client, that is a variation rather than a regeneration, and it needs its own record so the original bill remains visible."}]$q$, $a${"summary":"Saved estimates assembled into a bill of quantities, with every line traceable.","description":"A bill of quantities is a list of measured work with descriptions, units and rates, and its value is that every line can be traced. This generator builds those lines from the quantities the calculators produce, so a bill is a presentation of measured work rather than a document typed out beside it.\n\nThe consequence is that a line can be defended. When a client asks why the blockwork is a particular figure, the answer is a wall, a set of openings and a block size, and the bill can show it. Where an estimate changes, the bill changes with it, because the lines are generated rather than transcribed. What the generator does not do is measure the job, price the risk or sign off the total as a quantity surveyor would.","functions":["Builds bill lines from measured quantities, with the unit following the trade: square metres of wall, cubic metres of concrete, metres of pipe.","Carries the description from the measurement, so a line names what it measures rather than a generic trade heading.","Applies the rate you set per line, and shows the line total and the bill total from those.","Keeps contingency as an explicit line you add, not a percentage hidden in the rates.","Reports tax only where a configured rule applies, and as undetermined where none does.","Regenerates the affected lines when a measured quantity changes, leaving the rates you set intact.","Reports a line without a rate as unpriced rather than carrying it at zero."],"worked":"A bill of eleven lines for a small extension: excavation, concrete, blockwork, roof structure, covering, plaster, screed, doors, windows, electrical and plumbing. Blockwork of fifty nine square metres at a rate you set, concrete of fifteen cubic metres at yours, and each other line following its own measurement. Add five percent contingency as a line, leave tax undetermined where no rule applies, and the total is the sum of eleven traceable lines. Change the wall height and the blockwork line and everything downstream of it move, because it was generated rather than typed.","advantages":["Lines are generated from measurements, so each one can be traced back.","Units follow the trade rather than one unit applied across the bill.","Contingency is an explicit line, so its size is visible to the client.","A measured change flows into the bill instead of being remembered.","An unpriced line is visible rather than silent."],"limits":["It does not measure anything itself, and it does not check the measurements.","It does not price risk, preliminaries or programme related costs.","It does not determine tax, and it will not apply a rate.","It does not replace a quantity surveyor's professional judgement or a contract.","It does not include rates negotiated after the bill is issued."]}$a$, $s${"title":"BOQ and Quote Generator","description":"A bill of quantities is a list of measured work with descriptions, units and rates, and its value is that every line can be traced.","keywords":"boq and quote generator, boq and quote generator, quoting, records and reference, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 808, 'longform'),
  ('project-timeline', 'Project Timeline', '/project-timeline', 'project', 5, $q$[{"q":"What does the timeline build from?","a":"Operations, their durations and their dependencies. Durations come from quantities divided by productivity, or from figures you enter where you know better. Dependencies encode what must follow what, which is the part that turns a list into a programme. The output is a sequence with a critical path and float on the operations that have any."},{"q":"Where do durations come from?","a":"From the quantities and the productivity rates, so a programme is built on measurement rather than optimism. Where you supply a duration directly, it is used and the derivation is not needed. Where neither exists, the operation is reported as unplaced, because a bar on a chart with no basis is why programmes slip on the first week and are quietly abandoned by the fourth."},{"q":"Can I see the critical path?","a":"Yes, on the operations that carry no float. The critical path is the chain whose duration equals the project duration, so a delay anywhere on it moves completion. The tool identifies that chain and shows the float on everything else, which is the information needed to decide whether a delay matters or can be absorbed."},{"q":"Does it track progress?","a":"No. Tracking progress means recording what has actually been done, against when, and recalculating from there, and that is a different exercise from building a programme. The timeline is a plan: it says what should happen in what order and how long it should take. Comparing that with reality is how a project is managed, and the tool does not pretend to do it."},{"q":"What about weather and access?","a":"They are allowances you enter. Weather, access restrictions and non working days vary by site, season and locality, and a default would be wrong somewhere. The tool applies the allowances you set to the operations affected, so a rainy season extension is visible in the completion date instead of emerging as a surprise in month three."}]$q$, $a${"summary":"A task schedule with dependencies, float and a visible critical path.","description":"A programme is a set of operations with durations and relationships, and the useful part is not the bar chart but the relationships between them. This timeline builds from the operations, their durations and their dependencies, and identifies the chain that decides the completion date.\n\nDurations come from quantities and productivity, which is why the labour estimator feeds it. Weather and access are yours to enter as allowances, because they are site facts rather than constants. What the tool does not do is track progress: a programme that is not updated against what actually happened is a drawing of an intention, and updating it is a separate discipline.","functions":["Builds a sequence of operations with durations, from the quantities and productivity rates you supply or enter directly.","Applies dependencies between operations, so an order that cannot be broken is respected.","Identifies the critical path, which is the chain of operations whose delay moves completion.","Shows float on the operations that are not critical, which is where recovery time lives.","Applies calendar allowances for weather and non working days as explicit inputs.","Reports an operation with no duration as unplaced rather than dropping it from the programme.","Shows the crew size implied by a duration against a quantity, so an impossible programme is visible before it is published to a client."],"worked":"A small building with twelve operations: excavation at four days, footings at five, blockwork at eighteen, roof structure at six, covering at four, and the rest following. Blockwork at eighteen days sits on the critical path, so a week lost there moves completion by a week, while the four days of covering has two days of float. Weather allowances of one day in five on the external operations extend the completion date instead of being absorbed into a hopeful assumption, and the crew implied by eighteen days of blockwork is three masons, which is the number that has to be available on the day.","advantages":["Durations come from quantities, so the programme and the estimate agree.","The critical path is identified, which is where attention belongs.","Float is visible, which shows which delays can be absorbed.","Weather allowances are explicit rather than absorbed into optimism.","An operation without a duration is reported, not silently dropped."],"limits":["It does not track progress, record actuals or forecast completion from them.","It does not level resources across overlapping operations.","It does not account for access constraints, permits or inspections in detail.","It does not calculate costs per period, although its dates are what a cash flow forecast is built against.","It does not resolve conflicts between trades beyond the dependencies you enter, and it does not allocate shared access or lifting plant.","It does not model the effect of a change order on the remaining programme, which is a re plan rather than an edit."]}$a$, $s${"title":"Project Timeline","description":"A programme is a set of operations with durations and relationships, and the useful part is not the bar chart but the relationships between them.","keywords":"project timeline, project timeline, labour, programme and cash flow, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 802, 'longform'),
  ('construction-sequence', 'Construction Sequence', '/construction-sequence', 'project', 5, $q$[{"q":"What is the construction sequence for?","a":"It sets out the order work has to happen in and which operations can overlap. A sequence is what a programme is built on: without it, a bar chart is a wish. It also makes hold points explicit, which matters because concrete poured over an uninspected footing cannot be checked afterwards. The value is in the dependencies being stated rather than remembered by whoever has been on site longest."},{"q":"Is the sequence fixed?","a":"The structural dependencies are fixed: you cannot build a wall before its footing, or a ceiling before the roof is covered. The overlaps are not fixed, and they depend on the building, the access and how many crews you have. The tool marks which is which, so a decision to overlap is a decision rather than a drift."},{"q":"How does it relate to the timeline?","a":"The sequence is the logic and the timeline is the calendar. The sequence says what must follow what; the timeline turns that into durations and dates, and identifies the critical path. Building a programme from a sequence is straightforward, while building one without a sequence produces dates that cannot be delivered because the order is wrong."},{"q":"Does it include inspections?","a":"Inspections and hold points are in the sequence at the points where work gets covered: footings before concrete, first fix before plaster, drainage before backfill. They are not an afterthought, because an inspection that cannot be done is a defect that cannot be seen. What the tool does not do is decide which inspections your authority requires, which is a local question."},{"q":"Who uses it?","a":"Site managers, foremen and anyone pricing work from a programme. A subcontractor can see where their operation sits and what has to be finished before they can start, which is the conversation that otherwise happens on the morning they arrive. A client can see what stage their money is buying, which is why sequence and payment stages are usually read together."}]$q$, $a${"summary":"The order trades follow, with the hold points that stop work being covered too early.","description":"A sequence is the order in which work has to happen, and most of it is not negotiable. Foundations before walls, walls before roofs, roofs before ceilings. Where the sequence is negotiable is in the overlaps, and getting those wrong is how a site ends up with three trades in one room.\n\nThe tool sets out the sequence for the work you describe, with the dependencies that make it valid and the overlaps that are possible. It is a reference rather than a programme: it tells you what must follow what and what can run alongside, and the dates come from the timeline. Where an operation has no place in the sequence, that is usually a sign that a stage is missing rather than that the operation is optional.","functions":["Orders operations by their structural and service dependencies, from groundworks to finishes.","Marks which operations can overlap and which cannot, with the reason stated.","Flags a sequence where an operation appears before its prerequisite.","Groups the sequence by stage, so site work, structure, envelope and finishes are distinct.","Links each operation to the calculators that measure it, so a stage can be priced from the sequence.","Reports an operation that fits no stage as a gap in the plan.","Keeps inspections and hold points in the order, since work that is covered cannot be inspected later."],"worked":"Groundworks, then footings, then blockwork to eaves, then roof structure and covering. Services first fix runs inside the walls while the roof is being covered, because the building is dry enough and the walls are open. Plaster follows first fix, then screed, then second fix and finishes. Held inspections sit at the points where work gets covered: the footing before concrete, the services before plaster. Move plastering ahead of first fix and the sequence is wrong in a way that costs a wall and a rewire, because the cables are now behind a finished surface that has to come off before anything can be connected.","advantages":["Dependencies are stated rather than assumed, so a plan can be checked.","Overlaps are identified, which is where a programme gains time safely.","Hold points are in the order, which prevents work being covered before inspection.","Stages are grouped, which is how a site is actually run and paid for.","An operation with no place in the sequence shows as a gap."],"limits":["It does not produce dates, durations or a programme.","It does not account for a specific site's access, phasing or occupied areas.","It does not replace a method statement or a safe system of work.","It does not include temporary works design or lifting plans.","It does not cover commissioning, handover, defects work, the sequence of a phased occupation or the order in which snags are cleared."]}$a$, $s${"title":"Construction Sequence","description":"The order trades follow, with the hold points that stop work being covered too early. A sequence is the order in which work has to happen, and most of it is","keywords":"construction sequence, construction sequence, labour, programme and cash flow, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 804, 'longform'),
  ('maintenance-planner', 'Maintenance Planner', '/maintenance-planner', 'project', 5, $q$[{"q":"Where do service lives come from?","a":"From published service lives attached to the components you list, and each is editable because exposure changes it. A roof covering has a nominal life, a paint system has a shorter one, a serviceable plant item has an interval rather than a life. The figures are starting points with a source, not predictions about a particular building."},{"q":"What does the planner produce?","a":"A schedule of tasks by year, with their costs, the annual total across the horizon, and the peaks where work coincides. It is what a sinking fund is calculated from and what a building owner needs to know before a lease is signed. The output is a plan, so the work can be budgeted and procured rather than discovered."},{"q":"Can I change an interval?","a":"Yes, and often you should. A coastal location shortens the life of external coatings, a harsh sun shortens the life of sealants, and a sheltered interior lengthens both. The interval you enter is the one the plan uses, and the effect of a change is immediate, which makes the assumption behind a maintenance budget visible instead of buried."},{"q":"Is this a condition survey?","a":"No. A condition survey inspects what is actually there and grades its state, which is how a real maintenance plan is built for an existing building. This planner works from specification and service life, which suits a new building or a budget. The two are complementary: the survey tells you where you are, and the planner tells you what the next twenty years look like from there."},{"q":"Why plan maintenance at all?","a":"Because maintenance is a cost that arrives whether or not it was planned for, and an unplanned one is paid for at the worst moment. Distributing it across years, and knowing which years are heavy, allows a fund to be built rather than a crisis to be met. It also changes design decisions: a component with a short life and difficult access can be replaced before construction by one that is cheaper over twenty years."}]$q$, $a${"summary":"Inspections and renewals across a building's life, from sourced service life data.","description":"A building starts to need work the day it is finished, and the cost of that work is predictable in aggregate even when it is unpredictable in detail. This planner turns service lives and intervals into a schedule of tasks and costs, so the money a building will need over ten or twenty years can be seen while it is still being designed.\n\nThe service lives are published figures attached to components, not guesses, and each carries the interval it implies. What the planner does not do is a condition survey: it assumes components are installed as specified and maintained as scheduled, and it reports the years in which cost falls rather than forecasting a failure. Where an interval is uncertain, that is an input to change rather than a fact to trust.","functions":["Builds a schedule of maintenance tasks from the components you list and their service lives.","Places each task in the year it falls due, so cost is distributed rather than averaged.","Calculates the annual cost per year across the horizon you set, showing the peaks.","Accepts an interval you change, since a harsh environment shortens one and a sheltered one lengthens it.","Reports a component without a service life as unscheduled rather than omitting it.","Keeps planned replacement separate from inspection and servicing, since the two cost differently.","Shows the effect of deferring a task, which is a cost moved rather than removed."],"worked":"A roof covering with a twenty year life, external paint at seven years, internal paint at ten, and a boiler service annually. Over a twenty year horizon the roof falls once at year twenty, the external paint at years seven and fourteen, the internal paint at year ten, and the service every year. The annual average is small and the peaks are not, which is the reason a sinking fund is calculated from the peaks rather than from the average. Bring the external paint to five years in a coastal location and the plan gains a third and fourth repaint inside the same horizon.","advantages":["Costs fall in the years they occur rather than being averaged into invisibility.","Service lives are attached to components, so an interval can be traced and changed.","Intervals are editable, since exposure changes them.","An unscheduled component is reported instead of quietly dropped.","Deferral is shown as a moved cost, which is what it is."],"limits":["It is not a condition survey and does not assess the current state of anything.","It does not forecast failures or their consequences.","It does not include reactive repairs or damage.","It does not price the work beyond the figures you supply.","It does not account for warranties or their effect on who pays."]}$a$, $s${"title":"Maintenance Planner","description":"A building starts to need work the day it is finished, and the cost of that work is predictable in aggregate even when it is unpredictable in detail.","keywords":"maintenance planner, maintenance planner, labour, programme and cash flow, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 803, 'longform'),
  ('carbon-footprint', 'Embodied Carbon Estimator', '/carbon-footprint', 'commercial', 5, $q$[{"q":"How is embodied carbon calculated?","a":"Quantity multiplied by emissions factor, per material, then summed. The quantity comes from the calculators, so a bill and a carbon figure share the same measurement. The factor comes from a published dataset and is stated per material and per unit, which means the result can be checked line by line by anyone with the same dataset."},{"q":"What happens to a line with no factor?","a":"It is reported as uncounted and left out of the total, with the gap shown. Applying a generic factor to a material with no published value would produce a number that looks authoritative and cannot be defended, and carbon figures increasingly end up in planning documents where being wrong matters."},{"q":"Which stages are covered?","a":"Material supply, transport to site and the construction activity itself, kept apart so each can be seen. Operational energy over the building's life is not included, and neither is end of life demolition and disposal unless they are added. That boundary is stated rather than implied, because a carbon figure without a boundary means very little."},{"q":"Can I compare two specifications?","a":"Yes, and that is the main use. The same quantities are priced against two specifications, so the difference between a standard mix and a blended one, or between two insulation products, is a number rather than a claim. Because the quantities are identical in both runs, the difference is attributable to the substitution."},{"q":"Is this a certification?","a":"No. It is an estimate for comparison and early design, not a certified assessment. Certification involves verification, a defined methodology, an assessor and a declared boundary, and the figures here are one input to that process rather than a substitute for it. Used that way it is genuinely useful, because most of the reduction available on a project is decided long before an assessor is appointed, at the point where the frame and the envelope are chosen."}]$q$, $a${"summary":"Kilograms of carbon dioxide equivalent per estimate line, from sourced factors.","description":"Embodied carbon is the emissions that come with making and moving a material, before the building is used at all. It is calculated by multiplying a quantity by an emissions factor, which is why this tool starts from measured quantities rather than from a floor area and a benchmark.\n\nThe consequence is that a carbon figure is only as good as its factors, and factors come from published datasets that differ by region and by production route. Where a material has no factor, the tool reports the gap rather than applying a generic one, because a made up factor produces a number that looks like an assessment and is not. Two specifications can then be compared on the same basis, which is where most of the value sits.","functions":["Calculates emissions from the measured quantity of each material and its emissions factor.","Groups the total by stage, separating the material supply from transport and from construction activity.","Reports a line with no factor as uncounted rather than applying a default.","Compares two specifications on the same quantities, so a substitution shows its difference.","Expresses the total in kilogrammes or tonnes of carbon dioxide equivalent, with the unit stated.","Shows which material contributes most, which is where a reduction usually comes from.","Keeps the quantity and the factor as separate columns, so a factor update can be applied without re measuring.","Reports the total for each element of the building, so a frame can be compared with a roof rather than only material with material.","States the dataset and the version behind each factor, which is what makes a figure defensible in a planning document."],"worked":"Fifteen cubic metres of concrete at a factor of about three hundred kilogrammes per cubic metre is four and a half tonnes, and twenty tonnes of reinforcement at roughly one and a half kilogrammes per kilogramme is thirty tonnes, which is usually the surprise. Change the concrete to a blend with a lower cement content and its line falls by a third while the steel stays where it is. The comparison shows that the steel dominates, which is not where most people look first.","advantages":["The figure comes from measured quantities, so it can be traced to a bill.","Stages are separated, so transport and supply can be seen apart.","Two specifications are compared on identical quantities.","A missing factor is reported rather than assumed.","The largest contributor is visible, which is where reduction effort belongs."],"limits":["It is not a certification or a verified assessment.","It does not include operational energy, which is a separate calculation.","It does not include end of life emissions unless you append them.","It does not validate the factors, which come from published datasets.","It does not account for sequestration in bio based materials beyond the factor used, or for the timing of emissions over the building life."]}$a$, $s${"title":"Embodied Carbon Estimator","description":"Embodied carbon is the emissions that come with making and moving a material, before the building is used at all.","keywords":"embodied carbon estimator, embodied carbon estimator, quoting, records and reference, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 805, 'longform'),
  ('circular-reuse', 'Demolition Recovery', '/circular-reuse', 'commercial', 5, $q$[{"q":"What does the recovery tool calculate?","a":"The materials present, the recovery rate for each, and the resulting split between recovered and disposed tonnage. It also derives a diversion rate from those figures and shows which stream contributes most to what is lost. Re use is kept separate from recycling, since a reclaimed beam and crushed concrete are different outcomes with different claims. The tonnage split is reported alongside, because a diversion percentage on its own can look excellent while a small, awkward stream is going to landfill in its entirety."},{"q":"Where do recovery rates come from?","a":"From published practice for each material stream, and they are rates rather than facts about a particular site. Steel is recovered at a high rate almost everywhere because its scrap value is real; concrete is recovered as aggregate where a crusher is available; gypsum recovery is limited by processing infrastructure. The rate you apply is an input, so a site with better arrangements can show it."},{"q":"Why does the split matter?","a":"Because a single percentage hides where the loss is. A building that is mostly concrete and steel will show a high diversion rate and still lose every piece of its gypsum and most of its timber. Reporting recovered and disposed tonnage separately, per material, means the plan can target the stream that actually needs attention rather than celebrating the one that was never at risk."},{"q":"Can I show a client the diversion rate?","a":"Yes, as a derived figure with its basis shown. That matters because diversion rates are increasingly asked for in planning and in client sustainability reporting, and a figure presented without its material split and its rates cannot be checked. Presenting the split alongside the percentage is what makes the claim defensible."},{"q":"Does it handle hazardous material?","a":"No. Hazardous materials are flagged and excluded from the recovery calculation, because their handling is a separate regulated process. Asbestos, contaminated soil and certain finishes cannot be counted as recoverable, and including them in a diversion rate would misrepresent both the outcome and the risk."}]$q$, $a${"summary":"Reused, recycled and landfilled quantities with the diversion rate they produce.","description":"Demolition produces material that is either recovered or lost, and the difference between those outcomes is decided before the building comes down. This tool counts what is there, applies recovery rates to each material stream, and reports the split between what can come back into use and what goes to disposal.\n\nThe split is the useful output. A single diversion percentage hides the fact that steel is nearly always recovered and gypsum is almost never, so a building's recovery rate follows from its material mix rather than from good intentions. Where a material is hazardous, the tool does not rate it for recovery, because that is a different process entirely.","functions":["Counts the materials in the building being taken down, by type and quantity.","Applies a recovery rate per material stream, drawn from published practice rather than from an assumption.","Reports recovered and disposed tonnages separately, with the diversion rate derived from them.","Flags hazardous materials and excludes them from the recovery calculation.","Shows which stream contributes most to what is lost, which is where a recovery plan should start.","Keeps re use separate from recycling, since the two are different outcomes.","Reports a material with no recovery rate as unassessed rather than assuming one.","Shows the volume as well as the weight, since bulky low density materials fill skips while barely moving the tonnage.","Keeps a record of the rates applied, so a diversion figure can be presented with its basis rather than on its own."],"worked":"A building with four hundred tonnes of concrete, sixty of steel, thirty of timber and twenty of gypsum. At published rates, steel recovers almost entirely, concrete largely as aggregate, timber at a moderate rate depending on treatment, and gypsum rarely. The diversion rate works out high because the concrete and steel dominate by weight, which is exactly why a percentage alone can mislead a client or an assessor: the material that is lost is small by weight and large by volume and cost.","advantages":["Recovery is calculated per material rather than as a single target.","Hazardous materials are excluded rather than counted as recoverable.","Re use and recycling stay distinct, because they are different outcomes.","The dominant stream is visible, which directs the recovery plan.","An unassessed material is reported rather than assumed."],"limits":["It does not survey the building or verify what is actually there.","It does not test for contamination or hazardous content.","It does not guarantee a market for recovered material, and a rate assumes somewhere for it to go within reach of the site.","It does not include the cost of recovery, transport, processing or the gate fees that decide whether recovery is worth doing.","It does not certify a diversion rate to a standard, and it does not verify that recovery actually happened."]}$a$, $s${"title":"Demolition Recovery","description":"Demolition produces material that is either recovered or lost, and the difference between those outcomes is decided before the building comes down.","keywords":"demolition recovery, demolition recovery, quoting, records and reference, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 814, 'longform'),
  ('warranty-certificate', 'Warranty Certificate', '/warranty-certificate', 'commercial', 5, $q$[{"q":"What does a warranty certificate contain?","a":"The specification, the products and quantities, the parties, the completion date, the warranty period and its start, and a hash of that frozen set. It is a record of what was agreed and measured at handover, which is the moment when all of it is knowable. What it deliberately does not contain is an opinion, since opinions do not survive contact with a dispute. It is a short document by design: the facts that a claim turns on are few, and a record that runs to thirty pages is one nobody reads at the moment it matters."},{"q":"Why freeze the configuration?","a":"Because a specification that can still be edited is not evidence. The value of a certificate is that it records a state at a date and can be shown not to have changed since. Freezing the configuration is what allows the hash to mean anything: a hash of something revisable proves only that the revision happened."},{"q":"What does the hash prove?","a":"That the recorded configuration is the one that was issued, unchanged. It is a check on the record, not on the building. If a specification is altered after issue, the hash no longer matches and the alteration is visible. What it cannot tell you is whether the work on site followed the specification, which requires inspection records."},{"q":"Is this a legal warranty?","a":"No. It is a record, and a record is what a warranty claim is argued with rather than what creates the warranty. The warranty itself comes from the contract, the guarantee or the statute. The certificate's job is to make the facts of the work available years later, in a form that can be trusted, which is often the difference between a claim that proceeds and one that stalls."},{"q":"When should one be issued?","a":"At practical completion, or at the completion of the element it covers. Issuing it later means reconstructing the specification from memory and photographs, which is exactly the situation the certificate exists to avoid. Where an element is completed early, such as a roof before the interior is finished, that element can be certified on its own date."}]$q$, $a${"summary":"A frozen, hashed snapshot of an estimate that a claim can be replayed against.","description":"A warranty certificate records what was built, by whom, with which materials, and it does so at a moment when all of that is still known. Years later, when a defect appears, the difference between a certificate and a memory is the difference between a claim and an argument.\n\nThe certificate freezes the configuration: the specification, the quantities, the products and the date. That freeze is the point, because a specification that can still be edited is not evidence of anything. A hash of the frozen configuration is stored with it, so the record can be shown to be unchanged since issue rather than merely asserted to be, which is what separates evidence from a claim.","functions":["Records the specification, the products and the quantities as issued, with the date of issue.","Freezes the configuration so a later edit cannot rewrite the record.","Calculates a hash of the frozen configuration, so tampering is detectable.","Records who issued it, for whom, and against which contract or address.","Keeps warranty periods and their start dates with the certificate.","Reports a certificate with a missing period or date as incomplete rather than issuing it.","Links the certificate to the measured quantities it covers, so the scope is unambiguous.","Records the maintenance the warranty depends on, since most warranties are conditional on it being done.","Allows a certificate to be reissued with a new hash when a variation is agreed, so the history of the record is kept."],"worked":"A roof replacement with a ten year workmanship warranty: the certificate records the specification, the sheeting, the fixings, the underlay, the quantities and the completion date, then hashes the frozen set. Two years later a leak appears and the question is whether the fixings specified were the fixings used. The certificate says what was specified and that the record has not changed since. It does not prove what was installed, which is what photographs and inspection records are for.","advantages":["The record is made when the facts are known rather than reconstructed later.","A frozen configuration cannot be edited into something more convenient.","The hash makes a change detectable rather than deniable.","Periods and dates sit with the scope they cover.","An incomplete certificate is reported rather than issued."],"limits":["It is not a legal warranty and it does not create contractual rights.","It does not prove that what was specified was installed.","It does not inspect, test or certify the work, and it does not record what was actually installed.","It does not decide liability or adjudicate a claim.","It does not replace insurance backed guarantees, statutory protection or the terms of the contract it sits beside."]}$a$, $s${"title":"Warranty Certificate","description":"A warranty certificate records what was built, by whom, with which materials, and it does so at a moment when all of that is still known.","keywords":"warranty certificate, warranty certificate, quoting, records and reference, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 814, 'longform'),
  ('contractor-credit', 'Contractor Credit Check', '/contractor-credit', 'commercial', 5, $q$[{"q":"How is the credit score calculated?","a":"From recorded evidence: payment history, completed work and verified references, each with a stated weight. The weights are visible, so a score can be interrogated rather than accepted, and the evidence sits beside it. Where the evidence is thin, the tool declines to score rather than producing a number that would look like knowledge it does not have."},{"q":"What if a contractor has no history?","a":"It reports them as unscored with the reason stated. A contractor with three completed jobs and no references is an unknown, and the honest treatment of an unknown is to say so. Scoring them low would wrongly imply a negative record, and scoring them high would be inventing one."},{"q":"Where do the statistics come from?","a":"From the records you hold and the references that have been checked. The tool does not access credit files or public registers, so the quality of a score depends on the quality of the evidence behind it. That is a limitation worth stating plainly, because a score that appears authoritative invites a decision that the evidence may not support."},{"q":"Who uses the score?","a":"Contractors assessing a subcontractor, clients assessing a main contractor, and suppliers assessing a trade account. In each case the score is one input to a decision that also involves the size of the commitment, the payment terms and the security available. It is most useful as a structured way to look at evidence that would otherwise be assembled by impression, and as a record that the evidence was considered before the commitment was made."},{"q":"Does a low score mean avoid?","a":"No. A low score means the evidence is thin or the record is patchy, and that calls for a different arrangement rather than an automatic refusal: staged payments, a guarantee, a smaller first package. The score is information, and treating it as a verdict would be using it for something it cannot support. A subcontractor with a patchy record on a small package may be a perfectly sound choice, and one with a clean record may be over committed elsewhere."}]$q$, $a${"summary":"A score out of one hundred from verified job history, refused when there is no history to score.","description":"A credit score is an inference about whether someone will pay, and any honest version of it has to say what it is built from. This tool builds one from payment history, references and the record of work completed, and it refuses to produce a score when there is not enough history to support one.\n\nThat refusal is the design. A contractor with no record is not a bad risk, they are an unknown one, and a score of zero would say otherwise. The tool reports the missing history as missing, so a decision to extend credit or award a subcontract rests on evidence rather than on a number that was invented to fill a gap.","functions":["Calculates a score from payment history, completed work and reference checks you record.","Weights each factor explicitly, so the contribution of each can be seen.","Reports insufficient history as unscored rather than as a low score.","Shows which factors would most improve a score, which is useful feedback to a subcontractor.","Keeps the underlying evidence visible beside the score, so it can be examined.","Records the date of each reference and payment record, since ageing evidence is weaker evidence.","Separates the score from the decision, which remains a commercial judgement.","Records the size of the commitments involved, since a score for a small package and a large one carry different weight.","Keeps a history of scores over time, so an improving or deteriorating record is visible rather than a single reading."],"worked":"A subcontractor with eight completed jobs, six paid on time and two late, and two verified references, scores in a middle band with the late payments as the main deduction. A second subcontractor with three jobs and no references is not scored at all, because there is not enough history to place them. The first can improve by settling on time and by having references verified; the second needs a longer record before any inference is fair.","advantages":["Weights are visible, so a score can be interrogated rather than trusted.","Insufficient history is reported as such, not as a failure.","The evidence sits beside the score, so a decision can be made on the record.","Ageing of evidence is recorded, which matters in a volatile market.","The score informs a decision without making it."],"limits":["It is not a credit bureau score and it does not access credit files.","It does not verify that references are genuine beyond what you record.","It does not predict insolvency or default, and it cannot see commitments held elsewhere.","It does not account for market conditions, sector risk or the state of the contractor's own order book.","It does not replace due diligence, guarantees, staged payments or a properly drafted subcontract."]}$a$, $s${"title":"Contractor Credit Check","description":"A credit score is an inference about whether someone will pay, and any honest version of it has to say what it is built from.","keywords":"contractor credit check, contractor credit check, quoting, records and reference, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 819, 'longform'),
  ('measurement-converter', 'Measurement Converter', '/unit-converter', 'commercial', 5, $q$[{"q":"Which units does the converter handle?","a":"Length, area, volume, weight and temperature, between metric and imperial, with feet and inches accepted as a combined input. Volume conversions cover the cases that actually come up on a site, including cubic metres to cubic yards and litres to gallons. What it does not handle is a conversion from one material to another, which is a specification question rather than a unit one."},{"q":"Why does area conversion go wrong so often?","a":"Because area and volume do not scale linearly. A metre is three point two eight feet, but a square metre is ten point seven six square feet and a cubic metre is thirty five point three one cubic feet, because each dimension carries the factor. Converting an area with the length factor gives an answer that looks plausible and is wrong by a factor of three, which is the single most common conversion error in estimating."},{"q":"Can I convert a material quantity?","a":"Where the relationship is a physical property rather than a unit definition, yes: a bag count per cubic metre can become a bag count per cubic yard once the density is known, and a tonne can become a cubic metre of a named aggregate. Where the density is not supplied, the conversion stays unresolved rather than using a typical value that may be wrong for the material."},{"q":"Does it round the answer?","a":"Yes, at a precision that suits the input. A dimension entered to the nearest centimetre does not become accurate to four decimal places by being converted, so the result is rounded to a sensible figure and the rounding is visible. That matters in an estimate, where a converted quantity is multiplied by a price and an over precise figure suggests a certainty the original measurement never had."},{"q":"Where is it most useful?","a":"At the boundary between a drawing and a supplier, which is where units change hands. A plan drawn in metres quoted by a merchant in imperial sections, a specification in square feet priced in square metres, a tank specified in gallons fitted into a space measured in metres. Each of those is a place where a small error becomes a returned order or a short delivery."}]$q$, $a${"summary":"Metric and imperial conversion for construction measurements, with cross-dimension assumptions stated.","description":"Construction is measured in two systems at once, and the failures happen at the boundaries: a supplier quoting in imperial sections for a building drawn in millimetres, a specification in square feet and a quantity in square metres, a plan in feet and inches with a site working in metres. The converter exists to make those boundaries explicit rather than approximate.\n\nIt converts length, area, volume, weight and temperature, and it returns the precision the input deserves rather than a string of digits that implies accuracy nobody has. What it will not do is convert a material quantity into another material, because that is a specification question rather than a unit question. Where a conversion is used in an estimate, the tool keeps the unit visible so the result can be read back.","functions":["Converts length, area, volume, weight and temperature between metric and imperial units.","Converts derived units properly, so a square metre becomes square feet rather than a length scaled twice.","Returns the result at a sensible precision, with the rounding stated rather than hidden in a decimal tail.","Converts material quantities such as bags per cubic metre into bags per cubic yard where the density is known.","Keeps the source unit visible, so a converted figure can be checked against what was entered.","Handles feet and inches as a combined input, which is how dimensions are often actually given.","Reports a conversion that depends on a density as unresolved until the density is supplied."],"worked":"A room of twelve feet six inches by ten feet eight inches is three point eight one metres by three point two five, and twelve point four square metres. Convert only the lengths and multiply in imperial and the area comes to a hundred and thirty three square feet, which converts to twelve point four square metres as well, which is the check that the conversion was done on the right dimension. Converting the area with the length factor instead gives a figure three quarters of the right answer, which is the classic error.","advantages":["Derived units convert correctly, which is where most conversion errors happen.","Feet and inches are accepted together, as they are spoken.","Rounding is stated, so a figure does not pretend to more accuracy than the input.","The source unit stays visible, so a result can be read back.","A density dependent conversion is reported rather than assumed."],"limits":["It does not convert between materials or specifications.","It does not know the density of a specific product unless you supply it.","It does not adjust quantities for waste or coverage.","It does not validate that the unit you chose is the right one for the measurement.","It does not replace a measured survey."]}$a$, $s${"title":"Measurement Converter","description":"Construction is measured in two systems at once, and the failures happen at the boundaries: a supplier quoting in imperial sections for a building drawn in","keywords":"measurement converter, measurement converter, quoting, records and reference, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 832, 'longform'),
  ('paint-comparison', 'Paint Comparison', '/paint-comparison', 'finishes', 5, $q$[{"q":"What does the paint comparison show?","a":"Cost per square metre for each product, at its stated coverage and your coat count, alongside the coverage itself so the basis is visible. It also shows what an area you enter would cost, which turns a comparison into an order. Which paint to buy also depends on the substrate, the exposure, the colour, the sheen, the drying time and how it will look in three years, and none of those are in a coverage figure. The comparison gives you the part that can be calculated and leaves the part that cannot to you."},{"q":"Why compare cost per square metre?","a":"Because a tin is not a unit of work. Coverage varies by a factor of two between products in the same tin size, so the shelf price tells you what a can costs and not what a wall costs. Cost per square metre combines price, coverage and coats into the figure that actually decides a painting budget, and it is the only basis on which two products can be compared at all."},{"q":"Where do the product figures come from?","a":"From the product record, which carries the manufacturer's stated coverage per litre and the tin sizes it is sold in. Where a product has no stated coverage, the comparison reports it as incomparable rather than using a typical figure, because a comparison built on an assumed coverage is a comparison of two guesses."},{"q":"Does it tell me which paint to buy?","a":"No. It tells you what each costs per square metre on the basis you set, which is a fact about price and coverage. Which paint to buy also depends on the substrate, the exposure, the colour, the sheen, the smell, the drying time and how it will look in three years, and none of those are in a coverage figure."},{"q":"Do prices include tax?","a":"Prices are shown as recorded, without tax, unless a configured rule applies to your market, in which case the basis is stated on the page. That matters when comparing a trade counter price that includes tax with a supplier quote that does not, which is a comparison that produces the wrong answer if the basis is not stated."}]$q$, $a${"summary":"Two or more paints compared on coverage and cost per square metre, not tin price.","description":"Paint is sold in tins of different sizes at different prices with different coverage, which makes the shelf price a poor guide to the cost of a wall. The comparison puts products on one basis: cost per square metre at the coverage the tin states and the number of coats the system needs.\n\nThat basis is what makes two products genuinely comparable. A cheap tin covering six square metres a litre is not cheaper than an expensive one covering twelve, and the difference compounds over a building. Where a product has no stated coverage, the comparison reports the gap rather than assuming a figure, because an assumed coverage is what makes the arithmetic look decisive while being wrong.","functions":["Calculates cost per square metre for each product, from tin price, tin size, stated coverage and coat count.","Normalises across tin sizes, so a five litre and a twenty litre pack are compared on the same basis.","Shows the coverage each product states, so the basis of the comparison is visible.","Reports a product with no stated coverage as incomparable rather than filling the gap.","Calculates the quantity needed for an area you enter, so a comparison can be checked against a real job.","Keeps primer and undercoat on their own lines, since a system is more than a topcoat.","Reports prices exclusive of tax unless you add a rate, in which case the basis is stated.","Shows the tin count a comparison implies for an area, since a part tin at the end of a job is a cost that a per square metre figure hides.","Keeps the tins of each product side by side, so a difference in pack size does not distort the comparison."],"worked":"Two emulsions. One costs a certain amount for five litres and covers six square metres per litre, so thirty square metres per tin. The other costs more for five litres and covers twelve, so sixty square metres. Per square metre the second is cheaper even though the tin costs more, and on a hundred and eighty square metres in two coats the difference is the price of a second tin of the cheap product. Neither figure required knowing the area in advance, which is why cost per square metre is the right basis.","advantages":["Products are compared on cost per square metre rather than shelf price.","Coverage is shown, so the basis of the comparison can be checked.","Coat count is part of the arithmetic, since a system is not one coat.","A missing coverage is reported rather than assumed.","Primer and undercoat are separate, which keeps a system honest."],"limits":["It does not judge colour, durability or finish quality.","It does not predict how many coats a particular substrate will need.","It does not validate the coverage a manufacturer states.","It does not include labour, which often dominates the cost.","It does not include the cost of preparation, masking, protection or the time a room is out of use."]}$a$, $s${"title":"Paint Comparison","description":"Paint is sold in tins of different sizes at different prices with different coverage, which makes the shelf price a poor guide to the cost of a wall.","keywords":"paint comparison, paint comparison, finishing materials, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 876, 'longform'),
  ('finish-estimator', 'Finish Comparison', '/finish-estimator', 'finishes', 5, $q$[{"q":"What is being compared here?","a":"Two finishes on the same area, with their material, their preparation and their renewal interval, and the cost of each over the horizon you set. That is a narrower claim than it sounds: it compares what can be measured, and it says so. Where a finish has no stated interval, the comparison reports that it cannot be put on a life basis rather than choosing one."},{"q":"Why compare finishes at all?","a":"Because the cheapest finish to buy is often not the cheapest to keep, and the difference shows up years after the decision was made by someone else. Comparing two options on one application hides that entirely. On a rental property or a commercial wall, the finishing cost over ten years can be several times the first application, and that is a design decision rather than a maintenance one."},{"q":"Are preparation and labour included?","a":"Material and preparation are included, and labour is optional at a rate you enter. Leaving labour out is deliberate: rates vary so widely between trades and markets that including a default would make the comparison a comparison of labour assumptions. Where you have a rate you trust, enter it and the comparison carries it. That is usually enough to settle a substitution argument, because the labour rarely differs enough between two similar finishes to overturn a material difference that compounds over fifteen years."},{"q":"Does it pick a finish for me?","a":"No. It compares the options you give it and shows the arithmetic. Which finish suits a wall depends on the substrate, the exposure, the room's use, the appearance wanted and who is paying for maintenance. The tool's job is to make sure the cost consequence of that decision is visible rather than discovered later."},{"q":"Can I compare a partial area?","a":"Yes. The comparison works on any measured area, so a single wall in a problematic corner can be assessed on its own, which is often where the decision actually needs making. The quantities are calculated from the area you enter, so a partial area is a partial comparison rather than a scaled down whole building."}]$q$, $a${"summary":"Paint, screed, tile and POP priced from one wall area so a client can choose.","description":"Two finishes can cover the same wall and cost very different amounts over their lives. This comparison sets them side by side on the same area: material, preparation and the interval at which each has to be redone, so a cheaper first coat that fails in five years is shown as the more expensive choice.\n\nThe comparison is deliberately narrow. It does not judge appearance, and it does not include labour unless you enter a rate, because labour rates vary by trade and by market in a way that would swamp the comparison. What it does well is make the arithmetic of a substitution visible before the specification is fixed, which is when the decision is still free.","functions":["Compares two finishes on the same measured area, with material quantities calculated for each.","Includes the preparation each finish requires, since a finish applied to a bad substrate is wasted.","Applies the service interval you enter, so the number of applications over a horizon is comparable.","Calculates the cost over that horizon, so a short lived finish is not compared on one application.","Accepts a labour rate per square metre where you want it in the comparison, and leaves it out otherwise.","Reports a finish without a service interval as incomparable on a life basis.","Keeps the two finishes on separate lines, so the difference is attributable.","Shows the number of renewals over the horizon rather than only the total, so the disruption is visible as well as the cost.","Handles a third option where a specification is being narrowed down, by running the comparison twice on the same area."],"worked":"A hundred square metres of wall, once in a decorative coating at one price, against a cheaper coating at a shorter interval. Over fifteen years the cheaper one is renewed three times and the dearer one twice, and the preparation before each renewal is the same. The comparison adds three applications against two and the difference reverses. Neither finish changed; the horizon did, which is why the interval is an input.","advantages":["Material and preparation are both counted, which a product comparison alone misses.","Service intervals make a life cycle comparison possible on one screen.","Labour can be included at your rate or left out, and the choice is visible.","The two options stay on separate lines, so the difference is attributable.","A missing interval is reported rather than assumed."],"limits":["It does not judge appearance, texture or suitability for a room.","It does not include access equipment or scaffolding.","It does not predict failure, only the interval you specify.","It does not account for patching or damage between renewals.","It does not include the cost of the building being out of use, the disruption of access or the risk a finish fails early."]}$a$, $s${"title":"Finish Comparison","description":"Paint, screed, tile and POP priced from one wall area so a client can choose. Two finishes can cover the same wall and cost very different amounts over their","keywords":"finish comparison, finish comparison, finishing materials, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 829, 'longform'),
  ('increte-flooring-calculator', 'Decorative Concrete Flooring', '/increte-flooring-calculator', 'finishes', 5, $q$[{"q":"What does the decorative concrete tool measure?","a":"The topping by area and thickness, the pigment or aggregate it carries, the border and pattern work by length, the sealer by area and coat, and the preparation products you specify. It does not measure the slab beneath, which has its own takeoff. Keeping them apart matters because a decorative topping is a separate trade, a separate order and a separate failure mode."},{"q":"Why measure topping separately from concrete?","a":"Because a topping is a thin layer of a specified material over a substrate, and a slab is a structural element of a different mix with a different design. Their quantities barely relate: ten millimetres of topping over a hundred square metres is one cubic metre, while the slab under it might be fifteen. Measuring one from the other is how a decorative floor estimate ends up either wildly over or missing the finish entirely."},{"q":"How is a border handled?","a":"By length, with its width, and as its own material line. A border is usually a contrasting mix, sometimes a different aggregate, and it needs its own quantity rather than being absorbed into the main area. Saw cut patterns are lengths as well, and each metre of cut is a metre of joint that has to be filled and finished."},{"q":"Is the substrate included?","a":"The substrate is not included, and the preparation of it is only included where you enter it. A topping needs a sound, clean, correctly prepared substrate, and the preparation is a real cost that varies enormously with what is there. The tool asks for the preparation you specify rather than assuming a clean new slab, because the assumption is what turns a quote into a loss. A substrate that has been down for years will need grinding, filling or a primer, and each of those has a coverage and a cost that belongs in the order."},{"q":"Does it allow for waste?","a":"Yes, as a percentage you set. Decorative work produces waste for a reason ordinary flooring does not: colour consistency comes from the same batch, and a border that does not meet cleanly is a return visit. The percentage is a line rather than a hidden loading, so its size can be seen and agreed before the job starts."}]$q$, $a${"summary":"Topping and sealer quantities for a decorative concrete floor, with borders as their own band.","description":"Decorative concrete flooring is a topping, not a slab, and the distinction decides the whole estimate. The topping is a thin, highly specified layer over a substrate that has already been built and cured, and it is measured separately because it is a different material applied for a different reason.\n\nThe takeoff measures the topping by area and thickness, counts the border or pattern work by length, and adds the sealing and the preparation the finish requires. The structural slab is not included, since it has its own design and its own takeoff. Where the substrate condition is unknown, the tool asks rather than assuming a prepared surface, because a topping over a bad substrate fails at the bond and takes the finish with it.","functions":["Calculates topping volume from the area and the thickness you specify.","Adds the pigment, aggregate or additive at the rate the product states, per unit of topping.","Counts border and pattern work by length, with the additional material and labour the detail implies.","Calculates sealer from the area and its stated coverage, per coat.","Adds surface preparation products where you specify them, at their coverage.","Reports an area without a thickness as incomplete rather than assuming a topping depth.","Keeps the topping separate from the slab, so a slab estimate is not double counted.","Counts saw cut joints and patterns by length, because each metre of joint is a metre that has to be filled and finished.","Reports the yield the product states per bag, so the bag count matches what a supplier will deliver."],"worked":"A hundred and twenty square metres of topping at ten millimetres is one point two cubic metres of material, which is a bagged product at its stated yield rather than a site mix. A border of forty metres at three hundred wide is a further twelve square metres of a contrasting mix. Sealer at two coats over the whole area, at its stated coverage, is the third line. The slab underneath is not in this estimate at all, which is why the two must be measured separately rather than one derived from the other.","advantages":["Topping is measured by area and thickness, which is how it is bought and laid.","Borders and patterns are counted by length, which is where estimates go light.","Sealer and preparation are priced as lines, at their own coverage.","The slab stays separate, so nothing is double counted.","A missing thickness is reported rather than assumed."],"limits":["It does not assess the substrate or its preparation needs.","It does not design the topping mix or its reinforcement.","It does not include the structural slab or its finish.","It does not include grinding, polishing or burnishing labour.","It does not guarantee colour or finish consistency, which depends on batches, timing and the applicator."]}$a$, $s${"title":"Decorative Concrete Flooring","description":"Decorative concrete flooring is a topping, not a slab, and the distinction decides the whole estimate.","keywords":"decorative concrete flooring, decorative concrete flooring, finishing materials, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 859, 'longform'),
  ('wall-finish-estimator', 'Wall Finish Estimator', '/wall-finish-estimator', 'finishes', 5, $q$[{"q":"What does the wall finish estimator cover?","a":"Plaster and render by area and thickness, ceilings on their own line, beads and reveals by length, and the preparation products you specify. Screed and the bagged alternatives are handled at their own stated yields. What it does not do is decide which finish a wall needs, because that follows from the substrate, the room and the standard required."},{"q":"Why is thickness an input?","a":"Because material follows volume, and volume is area multiplied by thickness. Doubling the thickness doubles the sand and cement on the same wall, and the difference between a ten and an eighteen millimetre render is a lorry load rather than a rounding. Thickness also decides whether a single coat will do, which changes the labour as well as the material, and it is the first thing a specification changes when a standard is raised."},{"q":"Are ceilings included?","a":"Yes, as their own surface with their own finish. A ceiling is usually a different mix from a wall, applied by a different technique, and it may be a different trade. Measuring it separately means its quantity can be ordered and priced on its own, and it also means a change to the ceiling specification does not disturb the walls."},{"q":"Does it account for openings?","a":"Yes, by dimension, before the volume is calculated. A door or a window is an area removed from the wall, and the deduction happens at the area stage so the thickness is applied to what is actually covered. What is not deducted is the bead or reveal around the opening, which is counted as a length instead, since that is the detail the opening creates."},{"q":"What about corner beads and reveals?","a":"Corner beads and reveals are counted by length from the details you list, and priced as their own line. They are the part of a plastering estimate most often left out, because they are small items that follow from the geometry rather than from the area. A room with eight external corners needs eight times the bead of a room with one, and the area does not show it."}]$q$, $a${"summary":"Screed, skim and texture quantities from the wall areas you identify, at the thickness you set.","description":"A wall finish is a thickness applied to an area, and the estimator measures both. Plaster, render, screed and the bagged alternatives all have a stated yield per millimetre, so the area alone does not tell you what to order until the thickness is fixed.\n\nThe estimator separates the surfaces by type and treats ceilings as their own surface, since a ceiling is a different mix, a different technique and often a different trade. Openings are deducted, beads and reveals are counted, and the preparation the finish requires is priced where you specify it. Where a thickness is left blank, the tool reports it rather than applying a standard coat.","functions":["Calculates finish volume from the wall area and the thickness you enter, per surface type.","Deducts openings by dimension, so doors and windows come out of the area rather than being ignored.","Treats ceilings as their own surface, with their own quantity and mix.","Counts corner beads and reveals by length, from the details you list.","Calculates the sand and cement, or the bags of a bagged product, at the yield stated for the thickness.","Adds preparation products at their coverage where you specify them.","Reports a surface without a thickness as incomplete rather than assuming one.","Keeps internal and external surfaces apart, since render and plaster take different mixes and different thicknesses.","Shows the volume each surface produces, so a specification change can be traced to material before it is ordered."],"worked":"A room with forty two square metres of wall and fourteen of ceiling, walls at twelve millimetres and the ceiling at three, gives half a cubic metre of wall mortar and a small quantity of a bagged ceiling finish. Deduct a door and two windows from the wall area before the volume is calculated, and add twelve metres of bead at the external corner and the reveals. The two surfaces produced two different orders at two different yields, which is the reason they are measured apart.","advantages":["Thickness is an input, so a two coat specification shows its material cost.","Ceilings are measured as their own surface with their own mix.","Openings are deducted by dimension before the volume is calculated.","Beads and reveals follow the details rather than a rate per square metre.","A missing thickness is reported instead of assumed."],"limits":["It does not assess the substrate or its suction and key.","It does not design the mix or specify admixtures.","It does not include floating, dubbing out or patch repairs.","It does not include scaffolding or access.","It does not include decoration over the finish, or the cost of protecting the finish once it is applied."]}$a$, $s${"title":"Wall Finish Estimator","description":"Screed, skim and texture quantities from the wall areas you identify, at the thickness you set. A wall finish is a thickness applied to an area, and the","keywords":"wall finish estimator, wall finish estimator, finishing materials, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 808, 'longform'),
  ('blueprint-takeoff', 'Blueprint and Plan Takeoff', '/blueprint-takeoff', 'commercial', 5, $q$[{"q":"How does the plan takeoff work?","a":"You read the dimensions from the drawing and enter them by element; the tool organises them, calculates the quantities they imply and keeps the source dimension beside each result. That is a takeoff in the traditional sense, with the arithmetic done by the same engine as the standalone calculators. The judgement about what the drawing shows stays with the person reading it."},{"q":"Can it read a PDF for me?","a":"It can read a drawing as a document, and it will not measure it. Automatic measurement requires interpreting line weights, scales and layers, and the failures are silent: a wall taken from the wrong layer, a door counted twice at a revision cloud, a dimension string that was superseded. A figure entered by someone who looked at the drawing can be argued with, which is worth more than speed on the numbers that decide a price."},{"q":"Why not measure the drawing automatically?","a":"Because a wrong quantity that looks precise is worse than a right one entered slowly. A takeoff is a set of judgements about what a drawing shows, and those judgements are exactly what a person is qualified to make and a model is not. The tool takes the result of that judgement and removes the arithmetic errors, which is where most takeoff mistakes actually come from."},{"q":"Which quantities does it produce?","a":"Quantities by element: wall areas and the units they require, concrete volumes, roof areas, openings as a schedule, and the lengths that trim and services are measured in. Each is calculated from the dimensions entered, and each carries that dimension, so an element can be recomputed by hand if a figure is disputed."},{"q":"Is the drawing stored?","a":"No. The drawing stays where it is. What the tool stores is the dimensions you read and the quantities they produced, which is the takeoff. That matters for a client's confidentiality and for a practice's own record: a takeoff that can be shown without the drawing beside it is often what a subcontractor is given, and a takeoff that carries the drawing is a document that cannot be sent anywhere."}]$q$, $a${"summary":"Dimensions taken off a plan, converted into quantities with every figure traceable.","description":"Reading a plan for quantities is a human skill that software assists rather than replaces. This tool takes the dimensions you read from a drawing, in the order a takeoff follows, and turns them into the measured quantities the calculators need, with each figure traceable to the dimension it came from.\n\nThe reading stays with you on purpose. Automatic measurement of a PDF drawing is possible and unreliable: a wall drawn in two lines, a dimension that was superseded by a revision, a scaled drawing that was printed at the wrong size. Where a dimension is entered by a person who looked at the drawing, the number can be questioned and corrected. Where it is inferred by a model, the error is invisible until it reaches a site.","functions":["Takes dimensions you read from a plan and organises them by element, in takeoff order.","Calculates the quantities each element implies, using the same calculators as the standalone tools.","Keeps the source dimension beside every quantity, so a figure can be traced back to the drawing.","Flags a dimension that is missing for an element, so an incomplete takeoff is visible as incomplete.","Organises by floor or by zone where a drawing covers more than one, so quantities do not run together.","Produces a takeoff sheet that can be checked line by line against the drawing.","Reports a revision change as a new takeoff rather than editing the old one, so the previous figure survives."],"worked":"A ground floor plan with external walls of fourteen metres by nine, internal partitions totalling thirty one metres, six doors and nine windows. Entered as dimensions rather than as a finished quantity, the takeoff produces blockwork for the external walls less the openings, partitions in their own measurement, and the openings as a schedule with sizes. Each element shows the dimension it came from, so a query about the blockwork is answered by pointing at a wall rather than at a total.","advantages":["Every quantity carries the dimension it was derived from.","Dimensions are read by a person, so an error is visible and correctable.","The same calculators run underneath, so a plan takeoff and a tool estimate agree.","Missing dimensions are flagged rather than filled with a guess.","A revision produces a new takeoff, leaving the previous one intact."],"limits":["It does not measure a drawing automatically or read dimensions from a PDF.","It does not verify that the drawing is the current revision.","It does not check the scale of a printed drawing.","It does not design anything or check the drawing's compliance.","It does not replace a measured survey of an existing building, where the dimensions have to be measured rather than read."]}$a$, $s${"title":"Blueprint and Plan Takeoff","description":"Reading a plan for quantities is a human skill that software assists rather than replaces.","keywords":"blueprint and plan takeoff, blueprint and plan takeoff, quoting, records and reference, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 814, 'longform'),
  ('global-site-safety-estimator', 'Global Site Safety & PPE Estimator', '/global-site-safety-estimator', 'sitework', 5, $q$[{"q":"Does this estimator certify that my site complies with OSHA, HSE or ISO requirements?","a":"No. The page multiplies your inputs by ratios you can see and prints the framework references that describe the relevant duty. A risk assessment, a method statement, a training record and an emergency plan are separate documents produced by people who know the site, and none of them can be generated from a perimeter length. Treat the export as a procurement schedule that starts a conversation with your safety adviser."},{"q":"Why doesn't the tool automatically use a 6 ft or 2 m fall threshold?","a":"Because the trigger height depends on jurisdiction, task and exposure, and treating one figure as universal produces confident nonsense. The estimator asks you to mark where work at height happens and how many workers need protection, then counts equipment for that number. Where local rules set a threshold, your safety professional applies it when deciding how many workers to enter. The tool stays out of that judgement on purpose."},{"q":"How are perimeter signs calculated?","a":"Boundary length divided by your spacing assumption, rounded up. A one hundred and twenty metre boundary at ten metre spacing gives twelve signs, and at fifteen metres it gives eight. The count is a purchasing figure. Sight lines, gates, corners, pedestrian routes and local sign rules decide where those signs actually stand, and a competent person should walk the boundary before any are fixed."},{"q":"Are first-aid kit ratios regulatory requirements?","a":"No universal ratio is claimed, and none is invented. You enter the planning allowance you work to and the quantity follows. First-aid cover depends on workforce size, shift patterns, distance from medical care, the hazards present and the training of nominated responders, all of which sit outside anything a calculator can see. The line exists so the item is not forgotten when the order is placed."},{"q":"What does ISO 7010 contribute?","a":"It defines the registered symbols used on safety signs, which helps you specify the right family of sign for each message. Adoption and enforcement come from local law and client requirements, not from the standard by itself. The estimator names the framework beside the sign line so the specification can be checked, and it does not reproduce or approve artwork, since sign graphics have to match the edition of the standard in force where the site sits."}]$q$, $a${"summary":"A transparent, adjustable inventory for construction-site PPE and safety logistics, with regulatory references kept separate from site-specific judgement.","description":"Safety quantities on a construction site are usually bought against habit: a box of gloves for the gang, signs along the hoarding, an extinguisher by the gate. This estimator turns that habit into a schedule that states its own assumptions, so the crew size, perimeter length and site conditions you enter produce quantities that can be checked line by line before anything is ordered.\n\nTwo things that are often muddled are kept apart here. A framework reference such as OSHA construction, UK HSE/CDM or ISO 7010 describes the shape of a duty. The quantity on the page is a planning figure made from your inputs. Keeping those separate means a printed list never reads as a certificate, and a number that came from a spacing assumption you chose is never mistaken for a statutory minimum.","functions":["Counts perimeter safety signs from the boundary length and the sign spacing you enter.","Plans basic PPE quantities from the active crew and the reserve allocation you select.","Adds fall-control equipment only where work at height is marked on the job, using the worker count you enter.","Adds excavation barriers and warning signs where excavation is selected, from the length you enter.","Adds hot-work extinguisher quantities where a hot-work task is selected.","Names the framework reference beside each line so the specification can be checked.","Exports the schedule to CSV for the procurement file or the site safety folder."],"worked":"A refurbishment of a small retail unit has a hoarding of one hundred and twenty metres, a crew of nine, one area of work at height and one hot-work task. At a sign spacing of ten metres the perimeter count is twelve signs; at fifteen metres it falls to eight. PPE for nine people with a reserve of one fifth gives eleven sets of gloves, eleven hard hats and eleven vests. Four workers marked as needing fall protection add four harnesses and four lanyards. One hot-work task adds one extinguisher. Change the crew to fourteen and the PPE rises to seventeen sets. Nothing in that arithmetic moves when the jurisdiction reference changes, because the reference changes the note beside the line, not the multiplication.","advantages":["Every figure traces back to an input that is visible on the page.","Framework references stay apart from quantities, so a planning list cannot be read as certification.","Optional hazards appear only when you select them, which keeps the schedule to the work you actually have.","The export goes straight into a procurement file without retyping.","Assumptions such as sign spacing and reserve allocation are printed with the result."],"limits":["It does not assess hazards or decide which controls a task requires.","It does not design fall arrest, scaffold, edge protection or excavation support.","It does not verify training, competence, first-aid cover or emergency arrangements.","It does not interpret local legislation, state-plan rules or CDM duties for a project.","It does not replace a competent safety professional's review before procurement."]}$a$, $s${"title":"Global Site Safety & PPE Estimator","description":"Safety quantities on a construction site are usually bought against habit: a box of gloves for the gang, signs along the hoarding, an extinguisher by the","keywords":"global site safety & ppe estimator, global site safety & ppe estimator, groundwork and site clearance, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 895, 'longform'),
  ('material-price-index', 'Live Material Price Index', '/material-price-index', 'commercial', 5, $q$[{"q":"What does the price index show?","a":"The recorded price for each material, the date it was recorded, the market it applies to and the movement since the previous figure. It is a record with dates rather than a live feed, which is why the age of a figure is shown as prominently as its value. A price without a date is a number, and a price with one is evidence. Where a material has never been recorded, the page says so, which is more useful than a figure someone will later assume was recent."},{"q":"Where do the prices come from?","a":"From the market price book for the selected market, with each figure carrying the date it was recorded. Where a material has no recorded price, the index says so rather than showing an old figure as if it were current. That distinction matters more than it sounds: an old price presented as current is the most common way an estimate becomes quietly wrong."},{"q":"Can I use it to price a job?","a":"With care, and with the date in view. A price from six weeks ago may still be accurate and may be worthless, depending on the material and the market. The index is designed to be used alongside an estimate rather than instead of one: you see the figure, you see its age, and you decide whether to use it or replace it with a supplier quote."},{"q":"Why does the index matter to a contractor?","a":"Because materials are the part of an estimate that moves fastest and is least under the contractor's control. A tender priced on cement from last year is a tender that loses money silently, and a client asking why a reissued quote is higher deserves a dated explanation rather than a shrug. An index turns both of those into a record. It also settles the internal argument, which is usually the harder one: two people pricing the same job from memory will disagree, and both will be confident."},{"q":"Does it cover every material?","a":"No. It covers the materials in the price book for the markets the system serves, which is a useful core and not a complete catalogue. Anything outside it is priced by you, and the tool is explicit about that rather than filling the gap with a typical figure that would look authoritative."}]$q$, $a${"summary":"How material prices have moved by market, from sourced and dated records.","description":"Material prices move, and an estimate that uses last quarter's figure without saying so is an estimate that will be wrong in a way nobody can see. The price index shows what the system holds for each material, when it was recorded, and how it has moved, so a rate in a quote can be traced to a figure and a date.\n\nIt is a record rather than a market feed. Prices come from the market price book for the market you select, with their dates, and they are only as good as the recording behind them. What the index adds is visibility: a contractor can see whether cement has moved since the last job, and a client can be shown why a reissued quote differs from the one they held.","functions":["Shows the recorded price for each material, with the date it was recorded and the market it applies to.","Shows the movement since the previous recorded figure, in currency and in percentage.","Groups materials by trade, so a movement in one category can be seen without reading every line.","Reports a material with no recorded price as unpriced rather than showing an old figure as current.","Keeps each market separate, so a price in one country is never presented as a price in another.","Links each figure to the estimates that used it, so a rate in a quote can be traced back to its source.","Shows the age of each figure, which is often more useful than the movement.","Shows which estimates were priced on a figure that has since moved, so a live quote can be reviewed before it is accepted.","Keeps the recording history rather than only the latest value, so a trend can be seen without an external source."],"worked":"Cement recorded at one figure in March and a higher one in June is a movement of a few percent, which on a job using three hundred bags is a real sum. The index shows both dates, the difference, and which estimates used the March figure. A quote issued in April can therefore be explained without anyone having to remember what happened, and a client querying a reissued price gets a dated answer rather than an impression.","advantages":["Every price carries a date, so its age is visible.","Movement is shown in currency and percentage, which answers different questions.","Markets are kept separate, which prevents a cross border figure being reused.","A missing price is reported rather than backfilled with an old one.","Estimates can be traced to the prices they used."],"limits":["It does not guarantee a price, and it is not a quotation.","It does not fetch live market data by itself.","It does not cover every material, only those recorded.","It does not account for transport, handling or supplier terms.","It does not convert between currencies, and it does not account for a supplier's own delivery charges."]}$a$, $s${"title":"Live Material Price Index","description":"Material prices move, and an estimate that uses last quarter's figure without saying so is an estimate that will be wrong in a way nobody can see.","keywords":"live material price index, live material price index, quoting, records and reference, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 883, 'longform'),
  ('code-reference', 'International Code Reference', '/code-reference', 'commercial', 5, $q$[{"q":"What does the code reference contain?","a":"References to the standards relevant to each discipline, with the jurisdiction they apply to and the body that publishes them. It is a map of where the requirements live rather than a copy of them. It also states where a design decision depends on a local code, which is often the most useful thing it does."},{"q":"Is this the standard itself?","a":"No, and it does not attempt to. Standards are copyrighted, revised on their own cycles and adopted by jurisdictions at different times, so reproducing one would produce a document that is out of date somewhere and unenforceable everywhere. The reference points you at the source, which is where the current requirements actually are."},{"q":"Why does jurisdiction matter so much?","a":"Because a requirement that is mandatory in one country is guidance in another and unknown in a third, and a quantity tool that ignored that would be making a legal claim by accident. Naming the jurisdiction for each reference keeps that visible, so a design decision made in one market is not imported into another along with its assumptions. That is a common and expensive mistake on projects where the designer, the contractor and the building are in three different places."},{"q":"Does the calculator check compliance?","a":"No. A calculator checks arithmetic and a code checks a design, and the two are different claims. The reference tells you which standard governs a question. Whether a particular design complies is a judgement that requires the standard's text, the design, and someone qualified to read both. The reference's contribution is to get the right text in front of the right person."},{"q":"How current is it?","a":"It is as current as the reference list it holds, and each entry names the body that publishes the standard so the edition in force can be confirmed there. Standards change, and a jurisdiction may adopt an edition years after publication, so the confirmation is a local act rather than something a page can do for you."}]$q$, $a${"summary":"Reference notes on the standards behind each method, with jurisdiction and edition stated.","description":"A construction code is a legal document that changes by jurisdiction, and a calculator that assumed one would be wrong almost everywhere. This reference exists to point at the right standard rather than to substitute for it, and to make clear which questions are answered locally.\n\nIt covers the areas that come up in estimating: material standards, structural design bases, electrical and plumbing requirements, fire, thermal and drainage. Each entry names the standard and the jurisdiction it applies to, with the caveat that the edition in force is a local matter. What the reference will not do is tell you a wall is compliant, because compliance is a judgement about a specific design against a specific edition.","functions":["Lists the standards relevant to each construction discipline, with the jurisdiction each applies to.","Names the body that publishes each standard, so the current edition can be confirmed at source.","Flags where a design decision depends on a local code rather than on a calculation.","Keeps jurisdiction explicit, so a standard is never presented as universal.","Links each reference to the calculators it affects, so a design input can be traced to its basis.","Reports a discipline with no reference held as a gap rather than an absence of requirements.","States that the edition in force is confirmed locally, since standards are revised and adopted on different dates.","Groups references by the design decision they govern, so the standard behind a specific input can be found quickly.","Keeps a note of where a local requirement replaces a regional one, since that is where imported assumptions fail."],"worked":"A query about the minimum thickness of a structural slab returns the design standards that govern it and the note that the edition in force depends on where the building is. The reference does not return a thickness, because the thickness comes from a design against that standard. What it does is make sure the designer is looking at the right document rather than at a figure from a calculator that assumed a code the project is not built under. That single check prevents a class of error that no amount of arithmetic care can catch.","advantages":["Jurisdiction is explicit for every reference.","The publishing body is named, so the current edition can be checked.","Design inputs are traced to the standard they depend on.","A discipline without a reference is reported rather than implied to have none.","The distinction between a reference and a compliance check is stated."],"limits":["It is not the standard itself and does not reproduce its text.","It does not certify compliance or interpret a clause.","It does not track which edition is in force in your area.","It does not cover every discipline or every country, and it does not resolve a conflict between two documents.","It does not replace a professional's obligations under local law or the authority having jurisdiction."]}$a$, $s${"title":"International Code Reference","description":"A construction code is a legal document that changes by jurisdiction, and a calculator that assumed one would be wrong almost everywhere.","keywords":"international code reference, international code reference, quoting, records and reference, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 826, 'longform'),
  ('material-advisor', 'Climate Material Advisor', '/material-advisor', 'commercial', 5, $q$[{"q":"What does the material advisor do?","a":"It takes the conditions you describe and returns materials that suit them, with the reasoning stated for each and the unsuitable ones flagged. It is a narrowing tool: it reduces a specification choice to a shortlist with reasons, which is where a specifier's time is best spent. A shortlist of three with reasons can be argued with, priced and specified; a catalogue of forty cannot. It does not produce a design, a fixing detail or a price."},{"q":"What does it base the advice on?","a":"On the conditions you enter: climate, exposure, position in the building, use of the space and the maintenance the owner is prepared to accept. Each of those changes the answer, and changing one on the page changes the shortlist, which is the quickest way to see whether a recommendation actually rests on the condition you think it does."},{"q":"Does it price anything?","a":"No. It names materials and their suitability. Pricing comes from the market price book or from figures you enter, and a material that suits a condition may be unavailable or uneconomic locally. Keeping suitability and cost apart is deliberate, because a shortlist that has already been filtered by price hides the options that would have been right. Price it afterwards, when the list is short enough to price properly."},{"q":"Is this engineering advice?","a":"No. It is guidance on selection. Engineering advice involves loads, movement, fixings, substrate and the specific detail, and it carries responsibility that a selection tool cannot. Use the advisor to narrow a list and an engineer or a specifier to design with it. The two are complements, and the handover between them is much cheaper than a redesign after a failure."},{"q":"What about availability locally?","a":"It flags availability as a separate consideration rather than modelling it, because local stock, lead times and merchant coverage change weekly and by location. Where availability decides a specification, the answer comes from a merchant rather than from a page, and the advisor says so instead of presenting a material that cannot be bought."}]$q$, $a${"summary":"Material choices narrowed by climate and exposure, with the reasoning shown.","description":"Choosing a material is a set of trade offs: exposure, maintenance, availability, cost and how it behaves over time. This advisor takes the conditions you describe, such as climate, position, use and maintenance appetite, and returns materials that suit them with the reasoning stated rather than a recommendation without a basis.\n\nIt is guidance, not engineering. The advice follows from the conditions entered, and those conditions are incomplete by nature: nobody enters the substrate, the detail and the workmanship, and those decide most failures. What the advisor is good at is narrowing a list before specification, and naming the reason each option is on it. That naming is what makes the guidance useful: a shortlist without reasons is a menu, and a menu is what a specifier already has.","functions":["Takes the conditions you describe: climate, exposure, position, use and maintenance expectation.","Returns materials suited to those conditions, with the reason each one fits stated.","Flags materials that are unsuitable for a condition rather than omitting them silently.","Names the standards or properties that make a material appropriate, so the choice can be checked.","Keeps cost and availability as separate considerations from suitability.","Reports an incomplete condition set as a gap, so the advice is not presented as conclusive on thin input.","Does not price anything, since price comes from the market book or from you.","Keeps the shortlist short, because a list of ten materials is a list nobody specifies from.","Records the conditions the advice was given on, so a recommendation can be reviewed when the brief changes."],"worked":"A coastal wall exposed to salt and driving rain, with a low maintenance expectation, returns materials for the exposure and the maintenance position, flags timber that would need regular recoating, and names the property that makes each suggestion suitable. What it does not do is design the wall, the fixing or the detail, because those decide whether the material performs, and they are a specification exercise rather than a selection one.","advantages":["Recommendations state why, which makes them arguable.","Unsuitable materials are flagged rather than quietly dropped.","Conditions are explicit inputs, so the advice can be tested by changing one.","Suitability is kept separate from price and availability.","Thin input is reported rather than used as a basis for confident advice."],"limits":["It is not engineering advice and does not design a detail.","It does not account for substrate, workmanship, fixing or the detail that decides whether a material performs.","It does not verify local availability or lead times.","It does not price materials, and it does not tell you what a merchant holds or how long a delivery takes.","It does not warrant performance or durability, and it cannot see how the material will be installed."]}$a$, $s${"title":"Climate Material Advisor","description":"Choosing a material is a set of trade offs: exposure, maintenance, availability, cost and how it behaves over time.","keywords":"climate material advisor, climate material advisor, quoting, records and reference, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 809, 'longform'),
  ('regional-cost-index', 'Regional Cost Index', '/regional-cost-index', 'commercial', 5, $q$[{"q":"What does the regional index do?","a":"A relative factor, by region and by trade, applied to a measured estimate. Labour and material factors are separate because they move for different reasons, so a labour heavy job adjusts differently from a material heavy one. The base and the adjusted figures stay side by side, which means the adjustment can be seen rather than absorbed."},{"q":"Where do the indexes come from?","a":"From recorded regional differentials, which are relative rather than absolute prices. That matters because a factor survives a change in the base estimate, while a set of local prices would have to be replaced every time a quantity changed. The date of the factors is recorded, since a differential narrows or widens over time."},{"q":"Does it convert currency too?","a":"No, and deliberately not. A currency conversion and a regional cost difference are different adjustments, and applying both through one factor produces a number that mixes two movements. The regional index adjusts for where the work is, and a currency conversion is applied afterwards at a stated rate, so each change can be seen and questioned on its own."},{"q":"Why not just use one national price?","a":"Because a national figure is a fiction that is convenient for a spreadsheet. Labour in one region can differ from another by a third, and haulage and local levies add further variation. A contractor pricing a job a long way from home needs to know what the local cost base is, and a client comparing two locations needs the same. The regional index gives both a way to have that conversation with a number in front of them rather than a hunch about the other side of the country."},{"q":"Can I apply it to a saved estimate?","a":"Yes, where the estimate is held and the region is known. The factor is applied to the measured quantities rather than to the total, so a change of region produces a re priced estimate rather than a scaled number. That keeps the traceability of the original lines and makes the regional adjustment one more visible step rather than a mystery. Where a client queries the difference between two locations, the answer is a factor and a date rather than an apology."}]$q$, $a${"summary":"How costs differ by location, from recorded regional factors.","description":"The same building costs different amounts in two cities, and the difference is not the design. Labour rates, material haulage, local levies and the depth of the subcontractor market all move the number, and a national average hides all of it. The regional index applies those differences to a measured estimate.\n\nThe index is a set of relative factors per region and per trade, applied to a base estimate rather than replacing it. What it will not do is convert currency, because a currency conversion and a regional cost difference are two different adjustments, and combining them produces a figure that answers neither question. Where a region has no factor, the tool reports it rather than applying the national figure as if it were local.","functions":["Applies a regional factor to a measured estimate, by trade where the factors are available.","Shows the base estimate and the adjusted estimate side by side, so the adjustment is visible.","Keeps labour and material factors separate, since they move for different reasons.","Reports a region with no recorded factor as unadjusted rather than applying a national average.","Accepts a factor you enter where you have local knowledge the index does not hold.","Keeps currencies separate, so a regional adjustment never doubles as a currency conversion.","Records the date of the factors, since a regional differential changes over time.","Shows how much of the adjusted total came from the regional factor, so its effect is not mistaken for a change in quantity.","Keeps an unadjusted copy of the estimate, so a comparison across two regions starts from the same measured base."],"worked":"An estimate of a hundred thousand at base, moved to a region with a labour factor of one point one five and a material factor of one point zero five, is adjusted trade by trade rather than as a single multiplier. A labour heavy job therefore moves more than a material heavy one, which is the point of keeping the factors apart. If the same job is being priced in another currency, that is a separate conversion applied afterwards, at a rate that is stated.","advantages":["The base estimate and the adjusted figure are shown together.","Labour and material factors are separate, so a trade mix is reflected.","Regions without factors are reported rather than averaged.","A local factor can be entered where you know better.","Currency and region are kept as distinct adjustments."],"limits":["It does not convert currency.","It does not hold a factor for every region or every trade.","It does not account for site specific conditions such as access or ground.","It does not forecast future movement in a region.","It does not verify the factors against a survey of local prices, and it does not hold a factor for every trade in every region."]}$a$, $s${"title":"Regional Cost Index","description":"The same building costs different amounts in two cities, and the difference is not the design.","keywords":"regional cost index, regional cost index, quoting, records and reference, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 844, 'longform'),
  ('defect-diagnosis', 'Defect Diagnosis', '/defect-diagnosis', 'commercial', 5, $q$[{"q":"What does the defect diagnosis do?","a":"It takes a described symptom and returns the causes that could produce it, the observations that would distinguish them and the checks that would settle it. It is a structured starting point for an investigation rather than an answer. The value is in not committing to the first explanation that comes to mind, which is usually the one that was seen most recently on another job."},{"q":"Does it tell me what is wrong?","a":"No, and it is deliberately built not to. A diagnosis from a description is a guess with confidence attached, and building defects are exactly the area where a wrong guess is expensive: a damp proof course injected where the problem was a leaking downpipe costs money and does not fix anything. What the tool gives you is the shortest list of plausible causes and the tests that separate them."},{"q":"Why give several causes?","a":"Because one symptom usually has several. Damp at a skirting can be rising damp, a bridged course, a leak, condensation or a cold bridge, and each has a different remedy and a different cost. Giving one cause would be a coin toss presented as an answer. Giving four with the observation that separates them turns the problem into something that can be investigated in an afternoon."},{"q":"Does it price the repair?","a":"No. It diagnoses the cause, or rather it narrows the causes. Repair pricing needs the extent, the access and the method, which are known after an inspection. A repair price given before the cause is confirmed is a number that will change, and quoting one is how a small job becomes a dispute."},{"q":"Where does the knowledge come from?","a":"From the documented causes and failure modes of common construction details, and from the observations that distinguish them. It is a knowledge base rather than a model's opinion, and it is deliberately conservative: where the description does not distinguish between causes, it says what further information would, instead of choosing."}]$q$, $a${"summary":"Symptoms mapped to likely causes, with the check that tells them apart.","description":"A defect is a symptom, and the symptom is rarely where the cause is. Cracking in a wall may be a foundation, a lintel, a thermal movement or a tree; damp at the skirting may be a leak three floors up. This tool takes the symptom you describe and returns the plausible causes, the observations that would distinguish them, and the checks that would settle the question.\n\nIt gives several causes on purpose. Single answer diagnosis from a description is how a repair is done on the wrong element, and the cost of that is paid twice. What the tool does not do is diagnose: a photograph and a sentence are not an investigation, and every cause it returns comes with the observation that would confirm or exclude it, so the next step is a site visit rather than a purchase order.","functions":["Takes a described symptom and returns the plausible causes that match it, each with its reasoning.","Names the observations that would distinguish one cause from another, so a site visit has a purpose.","Flags causes that are structurally significant, so the ones that matter are not lost among the cosmetic ones.","Groups causes by element, so a symptom that could be the roof or the wall is not merged.","States the checks that would settle the question, in the order that costs least first.","Reports a description too general to work with as insufficient rather than returning a generic list.","Keeps the diagnosis separate from the repair, which is priced and specified elsewhere."],"worked":"Damp at the base of a ground floor wall, on the inside, in one corner. The tool returns rising damp, a bridged damp proof course, a leak from above following a cold bridge, and external ground levels above the course, each with the observation that separates them: the height of the tide mark, whether it appears after rain, whether the external ground is above the course, whether there is a downpipe nearby. None of those can be answered from a description, and the tool says so rather than picking rising damp because it is the most familiar.","advantages":["Several causes are given, which is honest and prevents a wrong repair.","Each cause carries the observation that would confirm it.","Structurally significant causes are flagged above cosmetic ones.","The checks are ordered from cheapest, which is how an investigation should run.","A vague description is reported rather than answered with a generic list."],"limits":["It does not diagnose, and it does not examine the building.","It does not replace a site inspection or a specialist report.","It does not price or specify the repair.","It does not account for the building's history, alterations or previous repairs.","It does not assess structural safety, which is an engineer's judgement."]}$a$, $s${"title":"Defect Diagnosis","description":"Symptoms mapped to likely causes, with the check that tells them apart. A defect is a symptom, and the symptom is rarely where the cause is.","keywords":"defect diagnosis, defect diagnosis, quoting, records and reference, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 803, 'longform'),
  ('bim-ifc-import', 'BIM and IFC Import', '/bim-ifc-import', 'commercial', 5, $q$[{"q":"What does the IFC import do?","a":"It reads the file, recognises the element types it understands, maps them to the categories the calculators use, and extracts the quantities the geometry supports. Elements it cannot map are listed with their type rather than discarded. The output is a takeoff by element that can be traced back to the model, which is the point of importing rather than re measuring. On a coordinated model that saves a week; on an uncoordinated one it tells you what has to be fixed before it can be used at all."},{"q":"What happens to elements it cannot map?","a":"They are listed as unmapped with their type, so the reason is visible. Usually it is a modelling decision: an element extruded as a generic form, a wall without a classification, a family that has no equivalent. Those are fixable in the authoring tool, and reporting them converts a silent gap in a takeoff into a task for the modeller."},{"q":"Are the model quantities trusted directly?","a":"No. The model's quantities are shown beside the extracted ones so a difference can be seen, but the takeoff is calculated from the geometry by the same engine as the standalone calculators. A model can carry a quantity that was typed rather than derived, and trusting it would import someone else's arithmetic error into an estimate that otherwise has none."},{"q":"Which quantities come through?","a":"Wall areas and the thicknesses behind them, slab and footing volumes, roof areas at the modelled pitch, run lengths for pipe and conduit, and openings as a schedule with sizes. Those are the quantities the geometry supports reliably. Anything that depends on a specification, such as a block size or a mix, comes from the properties where they exist and is reported as missing where they do not."},{"q":"Does it validate the model?","a":"No. Validation is a separate discipline: coordination, clashes, model completeness and standards compliance are checks against a brief, and a quantity import does none of them. What the import does is tell you which elements it could not use, which is a partial and useful signal about model quality rather than an assessment of it."}]$q$, $a${"summary":"Model element quantities mapped to trade engines, with unmapped elements listed.","description":"An IFC file is a model exchanged between authoring tools, and it carries geometry, properties and a classification. This import reads the elements it recognises, maps them to the categories the calculators use, and hands the quantities to the deterministic engine rather than trusting the model's own totals.\n\nThe mapping is where the work is. A wall in one tool is an IfcWall with a thickness and a height; in another it is an extrusion with a material layer set. Elements that cannot be mapped are reported rather than guessed at, and the quantities that come through are the ones the geometry supports: areas, volumes and lengths. A model with no material assignments produces geometry with no specification, and the tool says which of the two it is working from.","functions":["Reads an IFC file and lists the elements it recognises, grouped by the category they map to.","Maps recognised elements to the calculator categories: walls, slabs, roofs, openings and services.","Extracts quantities from geometry, such as wall area, slab volume and run lengths.","Reports elements it cannot map as unmapped, with their type, rather than dropping them silently.","Reports elements with no material or property set, so a geometric quantity is not mistaken for a specified one.","Keeps the model's own quantities beside the extracted ones, so a difference can be seen.","Produces a takeoff by element, traceable to the model it came from.","Reports a file that fails to parse as unreadable rather than producing a partial takeoff."],"worked":"A model with two hundred walls, forty slabs and ninety openings maps to wall area, slab volume and an opening schedule. Twelve elements come back unmapped because they are modelled as generic extrusions with no classification, and four walls carry no material layer set so their thickness is geometric rather than specified. The takeoff shows two hundred walls with quantities and twelve elements with no category, which is a fixable model rather than a failed import.","advantages":["Elements are mapped to the calculator categories rather than dumped as a list.","Unmapped elements are reported with their type, which points at the modelling fix.","Geometric quantities are distinguished from specified ones.","The model's totals and the extracted quantities are shown together.","A parse failure is reported rather than producing a partial takeoff."],"limits":["It does not validate the model, its coordination or its clashes.","It does not infer materials or specifications that are not in the file.","It does not design anything or correct modelling errors.","It does not guarantee that a mapped element is modelled correctly.","It does not replace a quantity surveyor's judgement about what to measure, or a modeller's judgement about how to model it."]}$a$, $s${"title":"BIM and IFC Import","description":"An IFC file is a model exchanged between authoring tools, and it carries geometry, properties and a classification.","keywords":"bim and ifc import, bim and ifc import, quoting, records and reference, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 815, 'longform'),
  ('field-sync', 'Field Sync', '/field-sync', 'commercial', 5, $q$[{"q":"What does field sync do?","a":"It brings a measurement taken on site into the estimate or takeoff it belongs to, recording where it came from and when. Where the figure differs from what is stored, it reports the conflict rather than choosing. The result is an estimate that reflects site reality and a history that shows how it got there."},{"q":"What happens if a sync clashes with a stored figure?","a":"It reports both and asks. The stored figure has a source, usually a drawing or an earlier measurement, and the synced one has a source too. Choosing automatically would discard one of them without a record, and the discarded one is often the evidence someone later needs. The resolution is a person's decision, recorded with its reason."},{"q":"Does it work offline?","a":"It queues the change and sends it when a connection returns, which is how a site actually works: basements and new builds have no signal. A queued record shows as pending rather than as sent, so nobody assumes a figure is in the office when it is still on a phone. That distinction is small and it is the difference between an estimate that is current and one that is quietly stale. A pending record is visible, so somebody can chase it; a silently lost one becomes a phone call from a site that has already ordered the wrong quantity."},{"q":"Is it a project management tool?","a":"No. It moves measurements between a site and an estimate, which is one specific flow of data. Scheduling, task assignment, progress tracking and document control are a project management system, and this is not one. Use it for the dimensions that decide quantities, and use the right tool for the rest."},{"q":"Who can see a synced record?","a":"The people on the job it belongs to, and the record keeps its source. A synced measurement is part of an estimate, so it is visible to whoever can see that estimate, which is the scope that makes sense: a site measurement is not public data, and it is not private to a phone either."}]$q$, $a${"summary":"Site measurements and notes returned to the estimate, with conflicts shown instead of overwritten.","description":"Measurements taken on site and estimates held in the office are the same numbers at different moments, and this is the mechanism that brings them together. A dimension recorded on a phone in a room syncs to the estimate it belongs to, with the direction of the change recorded rather than overwritten silently.\n\nThe conflict rule is the part that matters. Where a synced figure disagrees with what is stored, the tool does not pick one. It shows both, with their sources and times, and the person decides. That is slower than automatic merging and it is the only approach that leaves a record of what happened, which is what a client query or a cost dispute eventually depends on.","functions":["Syncs measurements recorded on site to the estimate or takeoff they belong to.","Records each synced value with its source, its time and the person who entered it.","Reports a conflict between a synced figure and a stored one instead of overwriting either.","Shows both values with their provenance, so the resolution is a decision rather than a guess.","Keeps a history of changes to a measured value, so the sequence is recoverable.","Works with a queue when a device has no connection, and sends when it next has one.","Reports a record that failed to sync as pending rather than as sent.","Keeps a synced record scoped to the job it belongs to, so site data does not leak across projects."],"worked":"A wall measured on site at two point six five metres is entered against an estimate that holds two point seven from the drawing. The sync does not replace either. It shows the drawing value and the site value, with times and sources, and the person chooses the site measurement and the reason is recorded. The blockwork quantity recalculates from the chosen figure, and the estimate's history shows that the change happened, when, and on what basis.","advantages":["Conflicts are surfaced with both values rather than resolved silently.","Every figure carries its source and time, which makes a change explainable.","The history of a measurement survives, which is what a dispute turns on.","Offline work queues and sends later instead of being lost.","A failed sync is visible as pending rather than assumed sent."],"limits":["It is not a project management tool and does not schedule or assign work.","It does not verify that a measurement is correct, only records it.","It does not resolve a conflict automatically, by design.","It does not work as an unlimited photo or document store, and it does not replace an inspection record.","It does not replace a survey or an inspection record."]}$a$, $s${"title":"Field Sync","description":"Measurements taken on site and estimates held in the office are the same numbers at different moments, and this is the mechanism that brings them together.","keywords":"field sync, field sync, quoting, records and reference, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 802, 'longform'),
  ('material-prices', 'Material Prices', '/material-prices', 'commercial', 5, $q$[{"q":"What does the material price page show?","a":"Materials with their price, the unit it is quoted in, the market it applies to and the date it was recorded. That is a record rather than a quote, and the difference is the date: a price with a date can be judged for age, and a price without one cannot be judged at all. The page is deliberately boring about this, because an estimate depends on it."},{"q":"Are these prices guaranteed?","a":"No. They are recorded prices, which means they are what was known when they were entered, in the market they belong to. A price can change the day after it is recorded, and a supplier can quote something different for a particular order. The page gives a starting figure with a date so you can decide whether to use it or to get a quote for the job."},{"q":"Why does the date matter?","a":"Because material prices move, sometimes sharply, and a figure with no date cannot be assessed. A bag of cement recorded last month may still be right and may be ten percent out, and the only way to know is to see when it was recorded. The age of a price is a better guide to its reliability than the price itself."},{"q":"Can I see where a price came from?","a":"Every entry keeps its source and its date, and an estimate that used it can be traced back to it. That matters when a client asks why a reissued quote differs, or when a job is compared against a similar one from six months earlier. The answer is a figure, a market and a date, rather than a recollection."},{"q":"How does this relate to the calculators?","a":"The calculators read from the book for the market selected, and where no price exists for a material in that market, the calculator asks for a figure instead of substituting one. That keeps a price in a quote traceable to either the book or to you, which is the only basis on which a total can be defended line by line."}]$q$, $a${"summary":"Recorded material prices by market, each with a date and a source.","description":"Every estimate eventually rests on a price, and this page is where those prices live. Each material in the book carries a figure, a unit, the market it applies to and the date it was recorded, so a rate in a quote can be traced to a source rather than remembered.\n\nThe date is the most important field on the page. Construction material prices move, and a figure without a date is a figure that cannot be judged. Where a market has no verified price for a material, the page shows the gap and the calculators ask rather than substituting a number, which is why an estimate in a market without a price book looks complete in its quantities and honest in its prices.","functions":["Lists materials with their price, unit, market and the date the price was recorded.","Keeps each market separate, so a price is never applied outside the market it belongs to.","Shows the unit a price is quoted in, so a tonne and a bag are not confused.","Reports a material with no recorded price as unpriced rather than showing a figure from another market.","Feeds the calculators, so a rate used in an estimate can be traced to the entry it came from.","Records the movement since the previous entry, which is what a reissued quote is explained with.","Reports the age of each price, so a stale figure is visible before it is used.","Accepts a price you enter for a material that is not in the book, scoped to your own work."],"worked":"A bag of cement at a recorded figure in a given month, a cubic metre of sand at another, and a block at another, each with its date. An estimate that uses three hundred bags can show where the bag price came from and when. Change the market and the prices change with it, and where the new market has no recorded block price, the calculator asks for one rather than carrying the previous country's figure into a quote.","advantages":["Every price carries a date, a unit and a market.","The gap is shown where a market has no price, rather than filled.","Rates in estimates can be traced to the entries they came from.","Movement over time is recorded, which explains a reissued quote.","A price you enter stays yours and does not overwrite the book."],"limits":["It is not a quotation and does not guarantee a price.","It does not include delivery, handling or supplier terms.","It does not cover every material in every market.","It does not convert currency.","It does not determine tax, which is reported separately where a rule applies."]}$a$, $s${"title":"Material Prices","description":"Recorded material prices by market, each with a date and a source. Every estimate eventually rests on a price, and this page is where those prices live.","keywords":"material prices, material prices, quoting, records and reference, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 801, 'longform'),
  ('borehole-water-system', 'Borehole and Water System', '/borehole-water-system-estimator', 'services', 5, $q$[{"q":"How is the overhead tank and its stand sized?","a":"The stand is sized from the load, not from a picture of one. A litre of water weighs a kilogram, so a 5,000 litre tank carries five tonnes before the tank shell, the ring beam, the deck and the piers are counted. That load is divided between the piers, and each pier gets a footing pad sized so the pressure on the ground stays inside the allowable bearing value. The tank sits on a reinforced concrete ring beam the full width of its base, because point loading a plastic tank on four block corners is how bases crack. Above 12 times the pier thickness the tool warns that a freestanding pier is getting slender, and past the BS 5628 limit of 27 it tells you to pour columns instead."},{"q":"Why does the stand need wind and footing checks?","a":"Because the tower is the part that fails. A tank full of water six metres up behaves like a sail in wind and like a weight on whatever ground is under it, and those are two different checks. The wind check uses a basic wind speed for the market or your own figure, turns it into pressure, applies it to the tank and the stand, and compares the overturning moment with the resistance of the stand with the tank empty, at a required factor of safety of 1.5. The ground check compares the loaded pad pressure with the allowable bearing figure, which is a presumption unless you enter a test result."},{"q":"How deep should the submersible pump sit?","a":"Set it below the pumping water level, not the static level, because the level falls while the pump runs. The tool estimates drawdown from the safe yield and the aquifer, adds it to the static level, and sets the pump about five metres below the result. It also checks the cased depth, because a pump cannot sit in an uncased hole, and it warns if the setting leaves less than two metres of submergence, if the pump lands at or below the top of the screen, or if the cased section is too shallow to place it where it should go. Those warnings change the drilling instruction, which is why they are printed instead of being silently corrected."},{"q":"How much tank storage does a house need?","a":"Enough to cover the peak and survive an outage. The estimator takes your occupants and consumption tier, works out the daily demand, multiplies the average hourly rate by a peak factor for the morning rush, and measures that against what the pump delivers in the same hour. The shortfall over the rush window is the buffer. On top of it sits an emergency reserve of a day or more, because pumps fail, power goes and tanks run dry at the worst time. The total is then rounded to a tank that is actually sold not a theoretical volume nobody can order."},{"q":"What is left for a person to decide?","a":"It leaves out the things that need a person on site. The strata, the specific capacity and the water quality are modelled from what you enter, so a driller's log and a laboratory assay replace them. The stand is priced by quantity and checked against simple limits, not designed and signed: the ring beam reinforcement, the pad mesh and the column cage still need an engineer. Prices, tax and labour come from your price book, and where a market has no verified figure the tool does not invent one."}]$q$, $a${"summary":"Sizes the well, the pump, the treatment train, the tank and the stand that carries it.","description":"A borehole is a chain of decisions that all have to agree: hole depth, drawdown under pumping, storage against the morning peak, treatment, and what holds the tank up.\n\nThis tool works that chain end to end on the numbers you give it, and it shows every step it took. Nothing is guessed from an address, and nothing is priced from a rate that was never verified for your market.\n\nThe stand is part of the design, not an afterthought: water load, tank shell, platform, piers, footings and wind are all carried through.","functions":["Builds a strata profile for the depth and aquifer type you select, then sizes the plain casing, the slotted screen, the gravel pack and the cement bentonite sanitary seal from the annular volume between the drilled hole and the casing.","Estimates drawdown from the safe yield and an aquifer specific capacity, gives you the pumping water level, and sets the pump below it with its riser friction worked out by Hazen Williams not a rule of thumb.","Converts total dynamic head and flow into hydraulic power, then into a motor size at stated pump and motor efficiencies, then into a stocked rating, with a warning when the duty needs more than the largest standard motor.","Sizes storage from the peak morning rush against what the pump delivers, adds an emergency reserve, and rounds to a tank that is actually sold.","Designs the stand under that tank: water load, tank tare, stand and platform self weight, footing pads sized against an allowable bearing, a reinforced ring beam, and a check against the wind with the tank empty.","Selects treatment stages from your lab figures against the usual drinking water limits, and produces a bill of quantities in quantities only, so your own price book sets the money."],"worked":"A household of six at a suburban standard of 150 litres a head uses 900 litres a day. The morning rush at 2.8 times the average hourly rate needs about 105 litres an hour more than a 2.5 cubic metre an hour pump delivers, which is roughly 210 litres of buffer, and a day and a half of reserve adds 1,350 litres, so the tool recommends a 1,500 or 2,000 litre tank depending on the next stocked size. That tank of water weighs about two tonnes. On four blockwork piers at 6 metres, the pier load, the platform and the ring beam all add up, and the pads come out around a metre square on a firm clay presumption of 100 kPa. If the ground turns out to be fill at 50 kPa, the same load needs wider pads, and the page says so instead of quietly pouring less concrete.","advantages":["Every number on the page traces back to an input or a stated assumption, so a quantity can be defended when a client or a bank asks how it was reached.","The pump, the tank and the stand are sized together. A tank that is larger than the pump can fill, or a stand that cannot carry the tank it holds, shows up before the concrete is poured.","Site realities are named out loud: a soil bearing figure with no test behind it, a stand past the slenderness limit for a freestanding pier, wind overturning with the tank empty, a pump set too close to the screen.","The bill of quantities separates material quantities from money, so the same estimate works in Lagos, Nairobi, Manchester or Houston without rewriting a rate."],"limits":["Geology is modelled, not logged. Screen depth, gravel pack and drawdown follow from the depth and aquifer type you choose, so a geophysical log or a driller's log should replace them before work starts.","Structural quantities are a bill, not a design. The stand ring beam, the pads and the columns are priced by quantity and checked against simple limits; a licensed engineer still signs the design that carries water.","Wind is a static check at a basic speed. Sheltered sites and exposed rooftops behave differently, and no site specific study is done here.","Water quality is judged against standard limits from the figures you enter. A laboratory assay on a real sample is the only thing that establishes potability, and treatment media are specified, not commissioned."]}$a$, $s${"title":"Borehole and Water System","description":"A borehole is a chain of decisions that all have to agree: hole depth, drawdown under pumping, storage against the morning peak, treatment, and what holds","keywords":"borehole and water system, borehole and water system, building services, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 1312, 'longform'),
  ('mathematical-plan-elevation', 'Mathematical Plan Elevation', '/mathematical-plan-elevation', 'structure', 6, $q$[{"q":"What does the plan elevation calculator actually calculate?","a":"It turns typed dimensions into geometry and quantities. Footing width follows from an assumed line load and the bearing value you select, and the page compares the resulting contact pressure with that value. Excavation, blinding, footing and slab volumes follow from the plan dimensions and the stated thicknesses. Wall area is the perimeter times the storey height, less the openings you list by wall side. The ring beam comes from its length and section, the roof rise and true area from the span and the pitch, and the programme from the phases the engine carries. Each figure is printed beside the arithmetic that produced it, so nothing arrives without a line a reader can check."},{"q":"Does it read an uploaded floor plan?","a":"No, and the page says so in its own notice. An image can be attached as a reference beside the numbers, and it is never analysed, scaled or measured, because a dimension inferred from a photograph is an estimate presented as a measurement. Every number in the schedule comes from a field you typed. That is the property that makes the output repeatable: the same inputs produce the same quantities on any device and in any session, without a model between your dimensions and the result, and without a silent substitution of one building type for another."},{"q":"Can I enter dimensions in feet and inches?","a":"Yes. The toggle changes what the length fields show and accept, so a footprint can be typed in feet, and it converts area, volume and reinforcement into square feet, cubic feet and pounds in the schedule cards, the summary and the CSV export. Bearing pressure, basic wind speed and line load stay in SI in both modes, because those are engineering inputs quoted in SI by the standards the page names, and a converted figure would look more precise than the screening assumption it actually is. The schematic drawing itself stays in metres, and a caption under it says so rather than leaving the reader to notice."},{"q":"How is the footing width chosen?","a":"The line load is accumulated from roof, walls, ring beam, slab edge and a reduced live load, then divided by the bearing value you enter. The result is lifted by fifteen percent to carry the footing's own weight. The adopted width is the larger of that figure and three times the wall thickness, which keeps a narrow wall from producing a footing too thin to build. The page then divides the load by the adopted width and prints the contact pressure against your bearing value, with a badge that says whether the result sits within the assumption or exceeds it. Exceeding it is a prompt to look closer, not a failure."},{"q":"Can I export the schedule and the assumptions?","a":"The export writes one row per scheduled item with its level, unit, quantity and any rate you typed, and adds a totals row when rates exist, naming how many items were costed so a partial pricing is not mistaken for a complete one. Quantities follow the unit system on screen, so the file matches what you read. The copy button produces a text summary listing each level, the totals, the programme, the assumption boundary and any screening flag that was raised. That text is meant to survive being pasted into an email, so it says plainly that it is not a design check."},{"q":"Are the wind and soil results a design check?","a":"No. The wind figure uses the velocity pressure form from ASCE 7-22, but the coefficients illustrate a single height and a chosen exposure, and the bearing value is yours to select from a table of typical soils. Both are screening values: they show whether the geometry deserves a closer look, and they give a quantity schedule a stated basis. Foundation design, uplift connection design, masonry stability and code compliance all need information this page never asks for, including a site investigation and a licensed engineer. Treat a green result as arithmetic agreeing with itself, not as a building approved."}]$q$, $a${"summary":"Turns typed dimensions into an elevation, a geometry check and a preliminary quantity schedule.","description":"An elevation is a set of consequences. Enter a length, a width, a storey height and a roof pitch, and the height of the ridge, the length of a rafter, the area of roof covering, the width of a strip footing and the number of blocks all follow from those four numbers by arithmetic that can be written out line by line.\n\nThe page is built to show that arithmetic rather than to hide it. Every level of the building is a numbered block on screen: foundation, ground slab, walls, ring beam and roof. Inside each block the entered figure and the result sit beside the step that connects them, so a reader who disagrees with a number can find the line where the disagreement starts.\n\nWhat the page cannot do is see. A plan image can be attached for reference and is never measured, scaled or interpreted, because a dimension read off a photograph is an estimate dressed as a measurement. The dimensions are typed in, which is what makes the output repeatable: the same inputs give the same quantities on any device, in any session, without a model in the loop.","functions":["Derives footing width from an assumed line load and the bearing value you select, then compares the resulting contact pressure with that value.","Calculates excavation, blinding, footing and slab volumes from the plan dimensions and the thicknesses the page states.","Measures wall area from the perimeter and storey height, then deducts the door and window openings you list, side by side.","Calculates ring beam concrete and main reinforcement from the beam length, its section and the bar arrangement shown.","Calculates ridge rise, rafter length and true roof area from the span and the pitch, in both gable and hip form.","Converts every dimension and quantity to feet, square feet, cubic feet and pounds on request, while the arithmetic stays in SI.","Exports the schedule as CSV and the summary as text that carries the assumptions and any screening flag it raised."],"worked":"Take a twelve metre by nine metre bungalow at three metres floor to floor, with a fifteen degree gable roof and a two hundred and twenty five millimetre wall. The roof span is the shorter plan dimension, nine metres, so the ridge rises by four and a half metres times the tangent of fifteen degrees, about one and a fifth metres, and the rafter on each slope runs about four and two thirds metres. The plan area is a hundred and eight square metres, so the true roof area is that divided by the cosine of the pitch, about a hundred and twelve. Walls run the perimeter, forty two metres, against three metres of height, minus the openings entered. The footing width comes from the cumulative line load divided by the bearing value, lifted by fifteen percent for self weight, and the page prints the contact pressure that results. Switch the display to feet and the footprint reads thirty nine point four by twenty nine point five, the ridge reads about four feet, and the roof area reads about twelve hundred and five square feet, from the same calculation.","advantages":["The quantity schedule and the arithmetic that produced it appear together, so a figure can be checked rather than trusted.","The footprint, roof geometry and wall takeoff come from one set of dimensions, which stops the roof and the walls disagreeing.","Openings are deducted by wall side, so the same window is not lost from one elevation and double counted in another.","Feet and metres are a display choice, not a second calculation, so switching units cannot change a quantity.","The export includes the assumption boundary and the screening flags, so a schedule sent to a colleague is not a bare list of numbers."],"limits":["It does not read, scale or measure an uploaded plan or photograph.","It does not design foundations, size reinforcement for a load case, or check masonry capacity.","It does not determine code compliance, and its bearing and wind values are planning assumptions you supply or select.","It does not price anything by itself: the unit rates are the ones you type, and no supplier price is fetched.","It does not replace a site investigation, a geotechnical report or a licensed engineer's review."]}$a$, $s${"title":"Mathematical Plan Elevation","description":"Turns typed dimensions into an elevation, a geometry check and a preliminary quantity schedule. An elevation is a set of consequences.","keywords":"mathematical plan elevation, mathematical plan elevation, structural materials, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 1401, 'longform'),
  ('window-blinds', 'Window Blinds', '/window-blind-calculator', 'interiors', 5, $q$[{"q":"How is a window blind priced per window and per square metre?","a":"Because shops quote both, and the calculator applies both. The rate per square metre is the headline figure on the wall. The minimum charge per window is what stops a small opening being sold below cost, so it overrides the rate whenever the measured area prices lower. Fabric is then cut with an allowance, because the drop has to clear the hardware and a pattern has to line up. A four by four opening therefore rarely costs what four by four multiplied by the metre rate suggests. The page shows the rate, the charged area, the minimum and whether it applied, so the difference between the two numbers is visible, not mysterious."},{"q":"Why does a small window cost almost as much as a large one?","a":"Only the minimum charge explains most of it. A quarter of the fabric still needs the same headrail, the same brackets, the same cutting, the same van, the same fitter and the same return visit, and those costs do not shrink with the window. Once the minimum takes over, two windows of different sizes can cost the same. That is also why a whole house priced per window looks cheaper than the same house priced per square metre: the minimum is doing the work on every small opening. The calculator keeps the minimum separate from the rate for exactly that reason, so you can see where a supplier is charging for material and where they are charging for the visit."},{"q":"What measurements do I need before ordering blinds?","a":"The finished opening, not the glass. Measure the width across the reveal and the drop from the head to the sill or the floor, in the same unit for both, and measure more than one window if they look alike, because they rarely are. Blinds need a small clearance inside a reveal, and an outside fit adds to both dimensions, so decide which you are doing before you measure. Then decide the control side, because a chain on the wrong side is a return visit. The calculator takes width, drop, count and type per opening and does the rest, and it converts feet to metres before pricing, so a four by four is 1.49 square metres whichever unit you typed."},{"q":"What changes the price between blind types?","a":"The type first, then the grade. A rigid slat, a folded fabric and a woven natural blind are different products with different waste allowances and different minimums, so the type moves the price further than a few centimetres of window. Grade is the second lever: premium prints and heavier fabric sell at a large multiple of standard stock, and the calculator applies that as a multiplier on the rate. Motorisation is the third, and it is not a percentage, which is why the calculator asks for the motor figure instead of inventing one. Fitting is the fourth and the most predictable, because it is charged per window and does not care what the fabric cost."},{"q":"Can I price blinds outside Nigeria?","a":"Yes, and the rules do not change. The measurement, the waste allowance, the minimum charge and the fitting are universal; what changes is the rate, so the calculator opens in any market and asks for the local rate where it has no verified band, then prices the schedule with the same arithmetic. What it leaves out is a site survey, a colour and fabric decision, a motor figure, and tax. It also leaves out the awkward openings: a bay, a sloping head, a door with a handle to clear. Those need a person with a tape and a sample book, and the calculator is honest about stopping where measurement stops."}]$q$, $a${"summary":"Prices a schedule of window blinds per window and per square metre, with the minimum charge and the waste allowance shown.","description":"A blind looks like a single purchase and behaves like four at once: fabric, hardware, fitting and the minimum charge that shops add to small openings. Most quotes fold those into one figure per window, which is why two suppliers can quote the same room and differ by half.\n\nThe calculator separates them. You measure the opening, choose the type and grade, and it returns the price per window, the price for the schedule and the blended rate per square metre, with each step and each assumption printed beside the number.\n\nThe opening is the only thing you have to get right. Everything after it is arithmetic.","functions":["Converts the measured width and drop from feet or metres into square metres, because a rate per metre means nothing until the opening is a decimal figure.","Adds the waste allowance for that type: a folded roman blind is cut with more spare than a rigid venetian slat, and the difference is a property of the type, not a guess.","Prices the window at the market rate, then lifts it to the minimum charge per window when the opening is small enough that the rate alone would undercut the shop.","Multiplies by the count on each row, adds the chosen grade, and adds motors, cassette headrails or removal only when you have supplied those figures.","Totals the schedule, adds fitting per window, and reports a blended rate so you can see what the job averages across mixed sizes."],"worked":"Take a four by four foot opening in a day and night blind. Four feet is 1.22 metres, so the measured area is 1.49 square metres. Ten percent is added for the drop and the pattern, which charges 1.64 square metres. At the standard rate the fabric comes to a figure the market sets, and because that figure lands below the minimum charge that shops apply to a window this size, the minimum takes over and becomes the price per window. The same opening in a rigid venetian slat carries a smaller waste allowance, so less area is charged, but it reaches its own minimum sooner. Scale the count to six identical windows and the fitting line grows with it, while the minimum per window stays where it was. That is the whole shape of a blind quote: rate, waste, minimum, count, fitting.","advantages":["The window is priced the way the customer approves it, and the metre rate is reported alongside it, so the shop's own arithmetic can be checked instead of argued about.","The minimum charge is shown as a decision, not hidden inside a total, so a small window that costs nearly as much as a large one is explained before the client asks.","Grade is a multiplier on the rate and never on the minimum, which matches how suppliers actually quote better fabric.","A mixed schedule reports one blended rate, which is the number that decides whether the job is worth taking."],"limits":["The markets with a verified band are named. Anywhere else the calculator asks for the rate you were quoted instead of converting another country's prices.","Motors, cassette headrails and taking down old blinds vary too much by supplier to carry a figure here, so they are added only when you type the amount.","Sizes are the finished opening. A recess fitting, a bay or a sloping head needs a site measurement, which no calculator can replace.","Tax is not determined. The total is stated before tax so you can apply the rate that belongs to your jurisdiction."]}$a$, $s${"title":"Window Blinds","description":"A blind looks like a single purchase and behaves like four at once: fabric, hardware, fitting and the minimum charge that shops add to small openings.","keywords":"window blinds, window blinds, interior decor and window treatments, construction calculator, quantity estimate, metric and imperial, Nigeria, Ghana, Kenya, South Africa, United Kingdom, United States"}$s$, 1230, 'longform')
ON CONFLICT (slug) DO UPDATE SET
  name = EXCLUDED.name,
  route = EXCLUDED.route,
  category = EXCLUDED.category,
  question_count = EXCLUDED.question_count,
  questions = EXCLUDED.questions,
  article = EXCLUDED.article,
  seo = EXCLUDED.seo,
  word_count = EXCLUDED.word_count,
  source = EXCLUDED.source,
  published = true,
  updated_at = now();

DO $$
DECLARE
  row_count INTEGER;
  short_count INTEGER;
BEGIN
  SELECT count(*) INTO row_count FROM public.tool_faq_articles;
  -- The registry holds groups of five to eight questions, so the rule is a
  -- floor plus agreement between the stored count and the stored array. An
  -- assertion of exactly five failed the moment a six question tool was added.
  SELECT count(*) INTO short_count
    FROM public.tool_faq_articles
    WHERE question_count < 5
       OR question_count <> jsonb_array_length(questions);
  IF short_count > 0 THEN
    RAISE EXCEPTION 'tool_faq_articles has % rows whose question count disagrees with their questions', short_count;
  END IF;
  RAISE NOTICE 'tool_faq_articles: % rows, % long form', row_count,
    (SELECT count(*) FROM public.tool_faq_articles WHERE source = 'longform');
END $$;

COMMIT;
